-- Drop unique constraint to allow multiple evidence items per person per criterion
ALTER TABLE person_criteria DROP CONSTRAINT IF EXISTS person_criteria_person_id_criterion_id_key;

BEGIN;
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 2, 'Schumer cosponsored the Israel Anti-Boycott Act (S.720), bipartisan legislation to combat BDS activity targeting Israel.', 'https://www.schumer.senate.gov/newsroom/press-releases/schumer-co-sponsors-bipartisan-legislation-to-combat-bds-bill-protects-states-and-localities-that-divest-from-entities-engaging-in-bds-activity-targeting-israel', '2019-02-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 2, 'Schumer expressed support for a Senate resolution opposing the delegitimization of Israel and the global BDS movement, calling BDS "a deeply biased campaign" and "a reinvented form of anti-Semitism."', 'https://jewishinsider.com/2019/06/chuck-schumer-to-support-anti-bds-legislation/', '2019-06-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 5, 'Schumer is an original cosponsor of the Antisemitism Awareness Act of 2025 (S.558), which directs the Department of Education to use the IHRA definition of antisemitism when investigating antisemitic acts on campus.', 'https://jewishinsider.com/2025/02/schumer-to-co-sponsor-antisemitism-awareness-act-in-the-senate/', '2025-02-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 5, 'Schumer proposed incorporating the Antisemitism Awareness Act into the National Defense Authorization Act during 2024 lame-duck session negotiations to fast-track the bill''s passage.', 'https://jewishinsider.com/2024/11/chuck-schumer-antisemitism-awareness-act-national-defense-authorization-act-a/', '2024-11-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 5, 'Schumer delivered a landmark 45-minute Senate floor address on rising antisemitism, condemning anti-Zionism as antisemitism and warning that Jewish Americans feel "targeted and isolated" since the Hamas attack on Israel.', 'https://www.democrats.senate.gov/newsroom/press-releases/majority-leader-schumer-delivers-major-address-on-antisemitism-on-the-senate-floor', '2023-11-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 6, 'Schumer and Gillibrand announced passage of a federal spending bill that includes more than $700 million in funds for U.S.-Israeli missile defense programs including Iron Dome.', 'https://www.schumer.senate.gov/newsroom/press-releases/schumer-and-gillibrand-just-passed-federal-spending-bill-includes-more-than-700-million-in-funds-for-us-israeli-missile-defense-programs-', '2022-03-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 6, 'Schumer supported the $1 billion Iron Dome Supplemental Appropriations Act, stating "Iron Dome is very important and it''ll get done."', 'https://www.congress.gov/bill/117th-congress/house-bill/5323', '2021-09-23');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 12, 'Schumer released a statement on October 7 calling the Hamas terrorist attacks on Israel "absolutely horrific" and stating the United States stands with Israel''s right to defend itself.', 'https://www.democrats.senate.gov/newsroom/press-releases/majority-leader-schumer-statement-condemning-the-terrorist-attacks-by-hamas-against-the-people-of-israel', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 12, 'Schumer traveled to Israel and delivered a press conference in Tel Aviv standing in solidarity with Israel, stating "we cannot let this evil continue to prowl the earth" and pledging resolute solidarity.', 'https://www.democrats.senate.gov/news/press-releases/transcript-majority-leader-schumer-remarks-from-tel-aviv_press-conference-standing-in-solidarity-with-israel-and-against-the-brutal-attacks-of-hamas', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 12, 'Schumer led passage of a bipartisan Senate resolution (S.Res.417) condemning Hamas and standing with Israel, which passed 97-0, stating "October 7th, 2023, will go down as a day of infamy."', 'https://www.democrats.senate.gov/newsroom/press-releases/majority-leader-schumer-floor-remarks-on-passage-of-a-bipartisan-resolution-to-stand-with-israel', '2023-10-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 12, 'Schumer released a statement on the one-year anniversary of October 7 observing the attack and reaffirming support for Israel.', 'https://www.democrats.senate.gov/newsroom/press-releases/majority-leader-schumer-statement-observing-one-year-since-hamass-october-7th-attack-against-israel', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 14, 'Schumer spoke at the March for Israel rally in Washington D.C., the largest pro-Israel gathering in U.S. history with ~290,000 attendees, declaring "We stand with Israel" and leading a bipartisan chant with House and Senate leaders.', 'https://jewishinsider.com/2023/11/chuck-schumer-mike-johnson-joni-ernst-hakeem-jeffries-israel-march-washington/', '2023-11-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 14, 'Schumer led a bipartisan Senate delegation to Israel in October 2023, meeting with Netanyahu, President Herzog, and opposition leader Gantz, and was forced into a shelter during Hamas rocket fire in Tel Aviv.', 'https://www.axios.com/2023/10/15/schumer-senate-israel-hamas-war', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 14, 'Schumer addressed a gathering of Jewish leaders in New York City in February 2026, stating one of his "many jobs" as Senate Democratic leader was to "fight for aid to Israel" and pledged to "always fight to give Israel what it needs to protect itself."', 'https://www.democracynow.org/2026/2/5/headlines/chuck_schumer_defends_us_arming_israel_as_trump_admin_approves_67_billion_weapons_sale', '2026-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 16, 'Schumer cosponsored Senate Resolution 417, a bipartisan resolution standing with Israel against terrorism that passed 97-0, condemning Hamas and reaffirming U.S. commitment to Israel''s security.', 'https://www.congress.gov/bill/118th-congress/senate-resolution/417', '2023-10-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 6, 'Schumer stated "The United States'' commitment to Israel''s security and defense must be ironclad" following Israel''s strikes on Iran in June 2025, affirming Israel''s right to defend itself and that Iran must never have a nuclear weapon.', 'https://jewishinsider.com/2025/06/schumer-u-s-commitment-to-israels-security-and-defense-must-be-ironclad/', '2025-06-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (265, 6, 'Schumer voted against Sanders'' resolutions to block $675 million in arms sales to Israel in July 2025, arguing Israelis have the right to defend themselves, despite a majority of his Democratic caucus voting the other way.', 'https://www.axios.com/2025/07/31/israel-weapons-sales-democrats-vote-fail', '2025-07-31');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 2, 'Gillibrand originally cosponsored the Israel Anti-Boycott Act (S.720), though she later withdrew her cosponsorship citing First Amendment concerns after meeting with the ACLU. She continues to oppose the BDS movement itself.', 'https://www.timesofisrael.com/sen-kirsten-gillibrand-withdraws-support-for-anti-bds-bill/', '2017-08-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 5, 'Gillibrand cosponsored the Antisemitism Awareness Act of 2024 (S.4127), which requires the Department of Education to consider the IHRA definition of antisemitism when enforcing federal anti-discrimination laws.', 'https://www.congress.gov/bill/118th-congress/senate-bill/4127/cosponsors', '2024-04-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 5, 'Gillibrand is a cosponsor of the Antisemitism Awareness Act of 2025 (S.558), reintroduced in the 119th Congress.', 'https://www.congress.gov/bill/119th-congress/senate-bill/558/cosponsors', '2025-02-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 5, 'Gillibrand cosponsored the Countering Antisemitism Act (S.4091) in April 2024.', 'https://www.congress.gov/bill/118th-congress/senate-bill/4091/cosponsors', '2024-04-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 5, 'Gillibrand led a bipartisan push to protect synagogues and other religious institutions from hate crimes, calling for $500 million in FEMA Nonprofit Security Grant Program funding following a rise in antisemitic attacks.', 'https://www.gillibrand.senate.gov/news/press/release/following-disturbing-rise-in-antisemitism-and-hate-crimes-gillibrand-announces-push-to-protect-synagogues-other-religious-institutions/', '2023-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 6, 'Gillibrand led a group of six senators in a letter to President Biden calling for replenishment of Iron Dome and urging the U.S. to stand ready to provide additional munitions to Israel.', 'https://www.gillibrand.senate.gov/news/press/release/gillibrand-leads-group-of-six-senators-to-call-for-replenishment-of-iron-dome-and-for-the-u-s-to-stand-ready-to-provide-additional-munitions-to-israel-as-it-defends-itself/', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 6, 'Gillibrand and Rounds led 44 senators in a bipartisan push to fully fund U.S.-Israel missile defense cooperation at $500 million for fiscal year 2023.', 'https://www.gillibrand.senate.gov/news/press/release/gillibrand-rounds-lead-forty-four-senators-in-bipartisan-push-to-fully-fund-us-israel-missile-defense-cooperation/', '2022-06-15');
