INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 6, 'Gillibrand introduced the bipartisan U.S.-Israel FUTURES Act with Sen. Budd in February 2026 to strengthen bilateral defense programs, expand defense technology cooperation, and accelerate joint R&D between the U.S. and Israel.', 'https://www.budd.senate.gov/2026/02/12/budd-gillibrand-introduce-bipartisan-bill-to-strengthen-bilateral-defense-programs-between-the-u-s-and-israel/', '2026-02-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 6, 'Gillibrand stated "I will always support Israel''s right to defend itself" in response to the Israel-Iran conflict in June 2025, characterizing Iran as "the foremost sponsor of terrorism in the world."', 'https://www.gillibrand.senate.gov/news/press/release/gillibrand-statement-on-israel-iran-conflict/', '2025-06-14');
