INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 12, 'Gillibrand strongly condemned the October 7 Hamas attack, stating "I strongly condemn the unprovoked terrorist attack launched by Hamas and stand shoulder to shoulder with the Israeli people in this moment of tragedy."', 'https://www.gillibrand.senate.gov/news/press/release/gillibrand-statement-on-terrorist-attacks-against-israel/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
