INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (266, 12, 'Gillibrand introduced a bipartisan Senate resolution with Senators Graham, Britt, Collins, Blumenthal, and Ernst calling for an independent investigation into October 7 sexual violence committed by Hamas.', 'https://www.britt.senate.gov/news/press-releases/u-s-senators-katie-britt-lindsey-graham-kirsten-gillibrand-susan-collins-richard-blumenthal-joni-ernst-introduce-resolution-calling-for-investigation-into-october-7-sexual-violence/', '2024-03-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
