INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 6, 'Stefanik voted for and cosponsored the Israel Security Assistance Support Act to force Biden to send withheld military assistance to Israel', 'https://stefanik.house.gov/2024/5/stefanik-votes-to-pass-the-israel-security-assistance-support-act', '2024-05-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 12, 'Stefanik condemned Oct 7 as barbaric crimes against Israel and the Jewish people, supported House resolution standing with Israel''s right to defend itself', 'https://stefanik.house.gov/2023/10/stefanik-statement-on-passage-of-the-resolution-to-stand-with-israel-against-the-war-launched-by-hamas-terrorists', '2023-10-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
