INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 12, 'Stefanik strongly supported US-Israel strikes on Iran, calling Iran the world''s largest sponsor of terror that must never achieve nuclear weapons capability', 'https://stefanik.house.gov/2026/2/stefanik-statement-on-operation-epic-fury', '2026-02-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 14, 'Stefanik delivered historic address at Israeli Knesset in May 2024, the highest-ranking House member to visit Israel since October 7th', 'https://stefanik.house.gov/2024/5/stefanik-delivers-historic-address-on-antisemitism-and-u-s-support-for-israel-at-israeli-knesset', '2024-05-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 16, 'Stefanik cosponsored H.Res.771/resolution standing with Israel and cosponsored resolution condemning Oct 7 terrorist attack by Hamas', 'https://stefanik.house.gov/2024/10/stefanik-cosponsors-resolution-condemning-10-7-terrorist-attack-on-israel-by-hamas-terrorists', '2023-10-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 16, 'Stefanik co-led letter with D''Esposito and Molinaro urging Biden to oppose ICC arrest warrants for Israeli officials', 'https://stefanik.house.gov/2024/4/stefanik-d-esposito-and-molinaro-urge-biden-administration-to-oppose-arrest-warrants-for-israeli-officials', '2024-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 12, 'Stefanik sponsored Illegitimate Court Counteraction Act to sanction the ICC for prosecuting Israel and other American allies', 'https://stefanik.house.gov/2024/5/stefanik-roy-introduce-the-illegitimate-court-counteraction-act-sanctioning-the-icc-for-prosecuting-israel-and-other-american-allies', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 12, 'Stefanik sponsored the Uncovering UNRWA''s Terrorist Crimes Act and advocated for permanently defunding UNRWA, calling it Hamas-infiltrated', 'https://stefanik.house.gov/2024/11/stefanik-stands-with-israel-and-renews-call-to-defund-unrwa', '2024-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (287, 16, 'Stefanik sent letter to Harvard President demanding university condemn antisemitic student organizations that blamed Israel for Hamas attacks', 'https://www.cruz.senate.gov/newsroom/press-releases/icymi-cruz-stefanik-confront-alma-mater-in-letter-demanding-harvard-condemn-antisemitism', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (288, 12, 'Mannion stated on Facebook: "I am sickened by the terrorist attack and the invasion of Israel" following the October 7 Hamas attack, condemning the violence against Israeli civilians.', 'https://www.facebook.com/JohnMannionforNY/posts/my-statement-on-the-invasion-of-israeli-am-sickened-by-the-terrorist-attack-and-/715533523728824/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (288, 16, 'Mannion released a statement declaring "I stand firmly with our ally Israel in the face of ongoing threats and hostilities from Iran" and affirmed his continued support for economic and military aid to Israel.', 'https://mannion.house.gov/media/press-releases/statement-representative-john-mannion-support-israel', '2025-06-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (288, 6, 'Mannion stated his commitment to "continuing to provide aid to Israel" and supporting Israel''s right to defend itself, as part of his broader pro-Israel stance including military aid.', 'https://mannion.house.gov/media/press-releases/statement-representative-john-mannion-support-israel', '2025-06-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (289, 12, 'Langworthy cosponsored H.Res.768, "Standing with Israel as it defends itself against the barbaric war launched by Hamas and other terrorists," and stated "I will always stand with Israel, and they need our support now, more than ever, to defend their freedoms following the brutal terrorist attacks of October 7."', 'https://www.congress.gov/bill/118th-congress/house-resolution/768/cosponsors', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (289, 6, 'Langworthy was an original cosponsor of the "Operation Swords of Iron" Iron Dome Supplemental Appropriations Act (H.R. 5918) introduced by Tenney and Gottheimer to appropriate $2 billion for Israel''s Iron Dome defense system.', 'https://gottheimer.house.gov/posts/release-gottheimer-tenney-introduce-bipartisan-legislation-to-resupply-israels-iron-dome-missile-defense-system', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (289, 6, 'Langworthy voted in favor of H.R. 6126, the Israel Security Supplemental Appropriations Act, providing $14.3 billion in weapons and other resources for Israel including defense systems.', 'https://langworthy.house.gov/media/press-releases/langworthy-votes-pass-israel-aid-package', '2023-11-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (289, 16, 'Langworthy joined a joint statement with NY Republican congressmen condemning Democrats for voting against the Israel aid package, declaring unwavering support for Israel.', 'https://lawler.house.gov/news/documentsingle.aspx?DocumentID=1308', '2023-11-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (289, 5, 'Langworthy introduced the Veto Your Visas Act to revoke student visas of those supporting Foreign Terrorist Organizations including Hamas, stating "The antisemitic actions that have threatened the safety of Jewish students must end."', 'https://langworthy.house.gov/media/press-releases/congressman-langworthy-introduces-bill-remove-visa-and-begin-deportation', '2025-03-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (289, 6, 'Langworthy condemned the Biden Administration''s decision to withhold munitions from Israel, calling it "brazenly subverting the will of Congress and an outright betrayal of our ally."', 'https://langworthy.house.gov/media/press-releases/langworthy-condemns-biden-administrations-decision-withhold-munitions-israel', '2024-05-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (289, 16, 'Langworthy issued a statement supporting Operation Epic Fury, the US-Israel joint strikes against Iran, stating the mission is "about protecting our homeland and finishing the job of blocking this murderous regime from obtaining a nuclear weapon."', 'https://wellsvillesun.com/blog/2026/02/28/statement-from-congressman-nick-langworthy-on-operation-epic-fury/', '2026-02-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 1, 'Tenney introduced H.R. 5179, the Anti-BDS Labeling Act, which passed the House 231-189, codifying rules against BDS-motivated country-of-origin labeling restrictions on Israeli products.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenneys-anti-bds-labeling-act-passes-house-representatives', '2024-09-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 1, 'Tenney reintroduced the Countering Hate Against Israel by Federal Contractors Act alongside Congressman Moskowitz to ban federal contracts with entities supporting the BDS movement targeting Israel.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-reintroduces-legislation-counteract-anti-semitic-bds', '2025-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 1, 'Tenney introduced the Countering Hate Against Israel by Federal Contractors Act requiring federal contractors to certify they are not engaged in a boycott of Israel.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-introduces-countering-hate-against-israel-federal', '2023-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 6, 'Tenney introduced the "Operation Swords of Iron" Iron Dome Supplemental Appropriations Act to appropriate $2 billion for Israel''s Iron Dome defense system, days after the October 7 attack.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-stands-israel-and-introduces-legislation-restock-israels', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 6, 'Tenney proposed a $14.056 billion "Operation Swords of Iron" Supplemental Appropriations Act providing targeted security aid for Israel including air defense systems.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-proposes-14056-billion-targeted-security-aid-israel', '2023-10-31');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 12, 'Tenney condemned October 7 as "one of the most heinous attacks against a U.S. ally" and stated "This is not Hamas fighting a war against IDF soldiers; this is Hamas attempting to kill, rape, torture, brutalize, and kidnap as many Jews as possible."', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-stands-israel-and-introduces-legislation-restock-israels', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 14, 'Tenney spoke at the "Stand with Israel" rally at Freedom Plaza in Washington, D.C., saying "This is Israel''s 9/11" and outlining priorities of military support, holding Iran accountable, and cutting off terrorist funding.', 'https://cnsmaryland.org/2023/10/13/at-dc-rally-marylands-moore-hoyer-and-others-declare-solidarity-with-israel/', '2023-10-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 5, 'Tenney sent letters to NY college and university presidents demanding clarification on whether calling for genocide of Jews violates codes of conduct, noting 73% of Jewish students felt unsafe on campuses since October 7.', 'https://dailycaller.com/2023/12/08/claudia-tenney-suny-antisemitism-demands-answers/', '2023-12-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 16, 'Tenney led a letter with 15 House Republican colleagues to Treasury Secretary Bessent urging review of Ireland''s proposed boycott of Israel under U.S. anti-boycott law.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-leads-letter-treasury-urging-review-irelands-boycott', '2025-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 16, 'Tenney led a letter to Treasury Secretary Bessent urging formal review of Spain''s anti-Israel boycott laws under Section 999 of the Internal Revenue Code, signed by multiple colleagues including Langworthy.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-leads-letter-urging-treasury-review-spains-israel-boycott', '2025-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (290, 16, 'Tenney released a comprehensive Israel and Iran Plan and led a bipartisan resolution supporting Israel''s strikes to end Iran''s nuclear capabilities during Operation Epic Fury.', 'https://tenney.house.gov/media/press-releases/congresswoman-tenney-leads-resolution-supporting-israels-strikes-end-irans', '2026-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (291, 12, 'Morelle stated on X: "I condemn in the strongest terms possible these senseless and horrific attacks by Hamas terrorists against innocent Israeli civilians. My prayers are with the people of Israel."', 'https://x.com/RepJoeMorelle/status/1710626303458639980', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (291, 12, 'Morelle stated he stands "in solidarity with, and reaffirm my unwavering commitment, to Israel''s security and right to defend itself against unjustifiable and indefensible acts of pure evil perpetrated by the terrorist organization Hamas."', 'https://morelle.house.gov/media/press-releases/statement-congressman-joe-morelle-6', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (291, 16, 'Morelle''s campaign website states "I stand unequivocally with Israel and support Israel taking the necessary action to defend its country and protect its people" and affirms his vocal support for Israel''s right to defend itself.', 'https://www.votemorelle.com/us-israel-relations', '2024-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (291, 6, 'Morelle stated on X: "I remain a vocal supporter of Israel and its right to defend itself" regarding an Israel aid bill, though he voted against the standalone bill because it did not include aid for other global partners.', 'https://x.com/RepJoeMorelle/status/1755017624457490839', '2024-02-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (292, 12, 'Kennedy stated on the anniversary: "One year ago, on October 7th, Hamas launched a horrific attack on the State of Israel, taking 251 hostages and slaughtering 1,195 people."', 'https://kennedy.house.gov/news/documentsingle.aspx?DocumentID=1141', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (292, 14, 'Kennedy visited Israel on an AIPAC-affiliated American Israel Education Foundation trip in August 2025 as part of a 14-member House Democratic delegation, meeting with Israeli President Isaac Herzog and visiting the Nova festival site.', 'https://jewishinsider.com/2025/08/house-democrats-freshmen-israel-aipac-trip-isaac-herzog/', '2025-08-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (292, 16, 'Kennedy issued a statement following the Iranian attack on Israel declaring that "Israel has a right to defend itself, and the United States'' relationship with the Israeli people is ironclad."', 'https://kennedy.house.gov/news/documentsingle.aspx?DocumentID=1137', '2025-10-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (1, 16, 'Palumbo signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, which condemned Hamas''s October 7 attack as "a war crime" and declared "we will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (1, 12, 'Palumbo signed the "New York Legislators Stand with Israel" letter which called the Hamas attack "despicable," denouncing "the taking of hostages, the wholesale murder of civilians, the use of torture, the beating, mutilation and killing of captured soldiers."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (1, 14, 'Palumbo joined the Senate Republican Conference in calling on Governor Hochul to deploy the National Guard to protect Jewish students at Columbia University amid pro-Hamas protests in April 2024, urging the Governor to "take swift action to protect Jewish students."', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (2, 12, 'Mattera stated regarding Columbia protests: "What we are seeing right now on Columbia University''s campus is Antisemitic, anti-American, and in many cases illegal. Hamas is a known terror organization with a similar world view as Al Qaeda and ISIS."', 'https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senator-mattera-and-senate-republican-conference-call', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (2, 14, 'Mattera joined Senate Republican Leader Rob Ortt and the Senate Republican Conference in calling on Governor Hochul to deploy the National Guard to protect Jewish students at Columbia University and demanding the resignation of Columbia President Minouche Shafik.', 'https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senator-mattera-and-senate-republican-conference-call', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (2, 14, 'Mattera joined the Senate Republican Conference and Run for Their Lives organizers at a rally in Albany advocating for the release of 134 hostages held in Gaza, stating: "I had the honor of joining the Commack organizers of Run for their Lives recently and I thank the organizers of all the rallies across our state, our nation and the world in support of those who were abducted in the October 7th terrorist attacks."', 'https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senate-minority-conference-joins-run-their-lives', '2024-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (2, 12, 'Mattera joined the Senate Republican Conference in sending a letter calling for Democratic Socialist Senators Julia Salazar, Jabari Brisport, and Kristen Gonzalez to be stripped of committee assignments due to their affiliation with NYC DSA, which "rallied in support of the terrorist group Hamas who unleashed carnage against Israel."', 'https://www.nysenate.gov/newsroom/press-releases/2023/mario-r-mattera/senator-mattera-joins-republican-conference-call', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (5, 14, 'Rhoads joined the Plainview community on December 12, 2023 to rally against antisemitism, unite against terror, and demand the safe return of hostages taken by Hamas on October 7. He joined faith leaders and hundreds of community members for prayers, statements on antisemitism, and a community menorah lighting.', 'https://www.midislandtimes.com/articles/plainview-community-rallies-agains-antisemitism/', '2023-12-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (5, 12, 'Rhoads demanded "Bring them home NOW!" regarding hostages taken by Hamas, and introduced antisemitism legislation "in the wake of the horrific Hamas terrorist attacks in Israel on October 7th." He stated Columbia University''s "failure to take swift and decisive action to protect the safety of its own students and campus is abhorrent and unacceptable."', 'https://www.nysenate.gov/newsroom/press-releases/2024/steven-d-rhoads/new-york-state-senator-steve-rhoads-senate-republicans', '2024-05-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (5, 5, 'Rhoads sponsored S.1268 which prohibits state funding for degree-granting institutions that permit pro-terrorist groups on campus. He also introduced a legislative package in May 2024 to curb antisemitism on college campuses, including bills on mask-wearing crimes and prohibiting state funding for colleges where staff promote terrorist organizations. He stated: "I will always stand up against hate and keep fighting to ensure that every student can learn in a safe, respectful environment."', 'https://www.nysenate.gov/newsroom/press-releases/2025/steven-d-rhoads/senate-democrats-block-bills-combat-campus', '2025-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (7, 1, 'Martins co-sponsored S6378A with Senator Simcha Felder, which prohibits New York State from contracting with or investing in businesses that promote boycotts of Israel and other US allies. The bill passed the Senate on January 20, 2016. Martins called BDS activities "hate speech" and "anti-Semitism."', 'https://jewishinsider.com/2016/01/ny-senate-passes-anti-bds-legislation/', '2016-01-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (7, 1, 'Martins introduced legislation in 2016 to prohibit public colleges and universities from funding campus organizations that support BDS efforts against Israel. He stated the legislature has "no choice but to step in and prevent taxpayer dollars" from supporting pro-BDS sentiment, characterizing such advocacy as "anti-freedom and anti-capitalism."', 'https://reason.com/2016/06/14/ny-wants-to-defund-probds-student-groups/', '2016-06-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (7, 5, 'Martins serves as Chair of the Senate Republican Antisemitism Working Group, formed in February 2023. The group released a 2023-2024 report with legislative recommendations to combat antisemitism in New York, including defining antisemitism in state human rights law, restricting financial aid for antisemitic behavior, and implementing awareness training in colleges.', 'https://www.nysenate.gov/newsroom/articles/2024/jack-m-martins/antisemitism-working-group-2023-2024-report', '2024-03-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (7, 12, 'Martins characterized the October 7th attacks as "the worst attack against the Jewish people since the Holocaust" and called pro-Hamas campus protests "funded and organized by outside forces, using university students as unwitting pawns." He called on Columbia University President Shafik to testify before the NY Senate regarding the endangerment of Jewish students.', 'https://www.nysenate.gov/newsroom/press-releases/2024/jack-m-martins/new-york-democrats-legislature-remain-silent-columbia', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (7, 14, 'Martins joined over 150 Great Neck residents at a forum to combat anti-Semitism, sponsored by Stand With Us and the Iranian-American Jewish Federation. He discussed combating BDS harassment of Jewish students on college campuses.', 'https://www.nysenate.gov/newsroom/press-releases/2016/jack-m-martins/senator-martins-joins-great-neck-community-combat-anti', '2016-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (7, 14, 'Martins posted on Facebook: "We continue to stand with Israel. Am Yisrael Chai. #StandWithIsrael" on April 19, 2024.', 'https://www.facebook.com/SenatorJackMartins/posts/we-continue-to-stand-with-israel-am-yisrael-chai-standwithisrael-/383974391283695/', '2024-04-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (7, 12, 'Martins published a column on November 1, 2023 titled "We must all work to stamp out antisemitism" addressing antisemitic incidents in New York following the October 7 Hamas attacks, stating "Today and every day, I''m proud to stand with Israel."', 'https://www.martinsforsenate.com/post/from-the-desk-of-jack-martins-we-must-all-work-to-stamp-out-antisemitism', '2023-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (9, 5, 'Canzoneri-Fitzpatrick sponsored S7773, the "Dismantling Student Antisemitism (DSA) Act," implementing antisemitism awareness and prevention sensitivity training at colleges with threat of loss of funding for non-compliance. Also unveiled legislation to withhold state aid from higher education institutions that fail to report antisemitism.', 'https://www.nysenate.gov/newsroom/press-releases/2023/patricia-canzoneri-fitzpatrick/senator-canzoneri-fitzpatrick-and', '2023-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (9, 5, 'Canzoneri-Fitzpatrick cosponsored S531 (the New York Antisemitism Act), which would criminalize the destruction of pro-Israel public materials including posters featuring names and photographs of hostages held in Gaza. She stated: "we are allowed to speak out in favor of pro-Israel concepts and bringing these hostages home, and that should be protected as our freedom of speech."', 'https://www.jns.org/bill-targeting-anti-israel-vandalism-introduced-in-new-york-state-senate/', '2025-01-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (9, 12, 'Canzoneri-Fitzpatrick cited "the alarming surge of antisemitic incidents following the Hamas terror attack" as underscoring "the pressing need for decisive action" when unveiling the Senate Republican Antisemitism Report and related legislation. She stated she was "disgusted by the recent increase of anti-Semitic hatred" and worked to "ensure that our Jewish brothers and sisters no longer have to live in fear."', 'https://www.nysenate.gov/newsroom/press-releases/2024/patricia-canzoneri-fitzpatrick/sen-canzoneri-fitzpatrick-republican', '2024-04-03');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (9, 16, 'Canzoneri-Fitzpatrick, along with Senate Minority Leader Ortt and the Senate Antisemitism Working Group, led a letter calling on Governor Hochul to help New Yorkers stranded in Israel return home safely, stating "New York''s connection to Israel is unmatched, and so is our responsibility."', 'https://www.foxnews.com/politics/ny-lawmakers-call-hochul-aid-jews-stranded-israel-after-desantis-facilitates-rescue-flights', '2025-06-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (11, 5, 'Stavisky sponsored S4559B, requiring every New York college and university to designate a Title VI coordinator to receive, investigate, and resolve discrimination complaints. She stated "The rise of antisemitism and other forms of hate on college campuses must end" and cited data showing 35% of Jewish students were subjected to antisemitism. Bill signed into law by Governor Hochul on August 26, 2025.', 'https://qns.com/2025/06/rozic-stavisky-bill-combat-antisemitism-on-campus/', '2025-06-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (11, 16, 'Stavisky signed the "New York Legislators Stand with Israel" letter dated October 20, 2023, which condemned the October 7 Hamas attack as "a war crime" including "the taking of hostages, the wholesale murder of civilians, the use of torture" and stated "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (11, 12, 'Stavisky signed the "New York Legislators Stand with Israel" letter which described the October 7 attack as "a despicable sneak attack against the Israeli people" and "a cruel, barbaric and brutal throwback to primitive times," condemning Hamas alongside those "aligned with Hamas, Russia and Iran." She also spoke on the Israel Resolution during a NY Senate session.', 'https://www.nysenate.gov/newsroom/video/toby-ann-stavisky/sen-stavisky-speaks-israel-resolution-during-session', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (12, 1, 'Gianaris sponsored S6086, anti-BDS legislation that would prohibit New York State from contracting with corporations boycotting Israel, require contractors to certify they don''t boycott Israel, and mandate state pension fund divestment from companies boycotting Israel. He stated: "The goal is to make a strong statement that New York stands with Israel and any effort to undermine the legitimacy of our strongest ally in the region will not be successful."', 'https://www.jpost.com/international/new-yorks-sen-gianaris-introduces-anti-bds-bill-432237', '2015-11-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (12, 5, 'Gianaris, as Senate Deputy Leader, led effort with over 80 state legislators to call for doubling security funding at Jewish and Muslim schools in response to escalating hate across New York following the October 7 attack, securing $70 million in the 2024-2025 state budget for school safety equipment.', 'https://www.nysenate.gov/newsroom/press-releases/2023/michael-gianaris/senate-deputy-leader-gianaris-assembly-member-hevesi', '2023-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (13, 11, 'Ramos published a statement on Medium calling for "a permanent ceasefire in Gaza," stating: "I call on our federal officials to support a permanent ceasefire in Gaza. As a New York State Senator, I stand for de-escalation, diplomacy and human rights for all people -- Palestinian and Israeli." She was the 13th NY state senator to call for a permanent ceasefire.', 'https://medium.com/@jessica_ramos/ramosceasefirestatement-839bb35c22e7', '2024-03-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (13, 11, 'Ramos called for "an immediate bilateral ceasefire and the safe return of all hostages" and stated "The Israeli government, driven by Benjamin Netanyahu''s right wing coalition, cannot continue to bomb hospitals and civilian infrastructure." She described the situation as "the attempt to eradicate a people from their ancestral land" and said "The murder of children is not self-defense."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-03-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (15, 1, 'Addabbo is the primary sponsor of S1255 (2025) and S4479 (2023), anti-BDS bills that would prohibit New York State from contracting with corporations boycotting Israel and restrict investment of public pension funds in companies boycotting Israel.', 'https://www.nysenate.gov/legislation/bills/2025/S1255', '2025-01-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (15, 12, 'Addabbo welcomed the release of Israeli hostages held by Hamas, stating: "To hear of the hostages being released and safely reunited with their families underscores the belief that every innocent life deserves to be treated with dignity. I am hopeful with the release of the hostages; this is a positive step forward towards an end to death and violence in the Middle East."', 'https://qns.com/2025/10/queens-reaction-hostage-release/', '2025-10-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (15, 5, 'Addabbo spoke out against the DSA''s questionnaire asking City Council candidates to boycott Israel, calling it "not only wrong, it is Anti-Semitic," stating that for many a visit to Israel is "a visit to their family''s homeland, a holy site of their religion, or to improve important relations."', 'https://www.nysenate.gov/newsroom/press-releases/2020/joseph-addabbo/addabbo-speaks-out-against-dsa-anti-semitic-question', '2020-08-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (15, 14, 'Addabbo attended the Queens Unity Rally Against Anti-Semitism on January 12, 2020 in Forest Hills, organized to show solidarity with Jewish New Yorkers following a series of antisemitic attacks including the Monsey machete attack and Jersey City kosher market shooting.', 'https://foresthillspost.com/queens-rally-against-anti-semitism-to-be-held-in-forest-hills-sunday', '2020-01-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (16, 16, 'Liu is described as pro-Israel and has "issued his support for the Jewish nation." When endorsing mayoral candidate Mamdani in June 2025, Liu acknowledged a "big disagreement" on Israel, stating: "Though I differ from him, we have had honest conversations, and he has never lost his integrity in the process." Over 60 Jewish leaders in Queens condemned his Mamdani endorsement as "a slap in our face."', 'https://www.amny.com/news/queens-liu-endorses-mamdani-disagreement-israel/', '2025-06-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (18, 9, 'Salazar called the situation in Gaza "genocidal" on October 13, 2023 and wrote in Jacobin about refusing to "let our grief be weaponized to justify a genocide in Gaza." On July 24, 2024, she posted on X accusing Israel of "mass extermination of Palestinian civilians."', 'https://jacobin.com/2023/10/julia-salazar-palestinians-liberation-cease-fire-israeli-occupation', '2023-10-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (18, 10, 'Salazar posted on X on January 17, 2025 accusing Israel of "occupation and apartheid." She has a history of such statements, writing in January 2018 that "the State of Israel and its brutal military occupation needs to be relentlessly resisted."', 'https://canarymission.org/individual/Julia_Salazar', '2025-01-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (18, 11, 'Salazar called for a ceasefire on October 13, 2023, making her one of the first NY state legislators to do so. On December 6, 2023, she posted: "Been calling for a ceasefire publicly since Israel began its ongoing bombing campaign in Gaza in October; was arrested in the action at Grand Central demanding it a month ago."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-10-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (18, 15, 'Salazar was arrested at the Jewish Voice for Peace-organized Grand Central Terminal sit-in on October 27, 2023, demanding a Gaza ceasefire, where nearly 400 people were arrested in the largest NYC civil disobedience action since the Iraq War. She has been arrested at least four times at anti-Israel protests.', 'https://www.democracynow.org/2023/10/30/grand_central_protest', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (18, 8, 'Salazar wrote in Jacobin in October 2023 calling on the American government to "stop fueling oppression and instability through military aid and hawkish diplomacy" to Israel, and instead affirm "full and equal rights of Palestinians and Israelis."', 'https://jacobin.com/2023/10/julia-salazar-palestinians-liberation-cease-fire-israeli-occupation', '2023-10-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (18, 13, 'Salazar co-authored a statement in early October 2023 acknowledging some rallies "failed to first acknowledge the fear, grief, death and destruction that was occurring" without naming Hamas or October 7 specifically. While she later stated she "condemned the Hamas attack," her primary public emphasis was on calling for a ceasefire and opposing Israeli military operations, and she fired a staffer who openly endorsed the October 7 attack.', 'https://www.jta.org/2023/11/20/ny/ny-state-sen-julia-salazar-distances-herself-from-staffers-endorsement-of-hamas-attack', '2023-11-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (20, 12, 'Myrie tweeted on October 7, 2023: "The attacks today in Israel have been sickening and heart-wrenching to watch. I stand unequivocally with innocent Israelis targeted by Hamas'' brutal actions." He also stated "Israel has the right to defend itself, and I pray it does so in a way that increases the chances of an eventual lasting peace."', 'https://x.com/SenatorMyrie/status/1710800047762190512', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (20, 14, 'Myrie has actively engaged with Crown Heights'' Chabad-Lubavitch community, sponsored legislation honoring Rabbi Menachem Mendel Schneerson including co-naming President Street as "Lubavitcher Rebbe Way," and condemned pro-Palestinian demonstrations that harassed Jewish people at the Brooklyn Museum and Borough Park. He also denounced an antisemitic Crown Heights rally in August 2025 as "seeking to sow division."', 'https://www.jta.org/2025/03/12/ny/a-jewish-guide-to-the-2025-nyc-mayoral-candidates', '2025-03-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (21, 5, 'Parker is the primary sponsor of S7034/S7034A, the HOPE Act (Honoring Our Pledge to Eliminate Anti-Semitism), which requires NY state agencies and courts to use the IHRA definition of antisemitism when reviewing discrimination complaints. Agudath Israel of America thanked Parker for his leadership on the bill.', 'https://www.nysenate.gov/legislation/bills/2025/S7034/amendment/A', '2025-06-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (21, 16, 'Parker issued a statement on January 5, 2009 on violent attacks on Israel, stating: "The military action in Gaza is a reminder to us all of the stakes in confronting terror, and the need to stand with our allies." He referenced his visits to Israel: "I have visited the border, driven through checkpoints, and visited with settlers," and urged continued US support for Israel.', 'https://www.nysenate.gov/newsroom/in-the-news/2009/kevin-s-parker/statement-state-senator-kevin-parker-violent-attacks', '2009-01-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (21, 14, 'Parker has traveled to Israel, visiting the border, driving through checkpoints, and meeting with settlers, as referenced in his 2009 official statement on the conflict in Gaza.', 'https://www.nysenate.gov/newsroom/in-the-news/2009/kevin-s-parker/statement-state-senator-kevin-parker-violent-attacks', '2009-01-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (22, 16, 'Sutton committed to ''unwavering support for Israel, ensuring state partnerships and moral backing for the Jewish state'' as one of his top legislative priorities when announcing his candidacy for State Senate.', 'https://imageusa.com/sam-sutton-announces-candidacy-for-state-senate/', '2025-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (22, 12, 'Sutton pledged to combat antisemitism with zero tolerance and to protect Jewish students and institutions throughout New York. As a Sephardic Jewish community leader, he participated in a 1973 mission facilitated by the Nativ Division of the Mossad to the Soviet Union, countering false propaganda against Israel.', 'https://communitym.com/2025/05/01/sam-sutton-announces-candidacy-for-state-senate-poised-to-make-history-for-sephardic-community/', '2025-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (23, 12, 'Scarcella-Spanton stated ''What is happening in Israel is an absolute travesty. To witness the horrors of the footage from overseas is sickening. Our community must come together to stand firmly in solidarity with the local families who have been impacted and denounce hatred and antisemitism that runs rampant.''', 'https://www.nysenate.gov/newsroom/in-the-news/2023/jessica-scarcella-spanton/everyone-shock-brooklynites-come-together-after', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (23, 14, 'Scarcella-Spanton participated in a solidarity event with Borough President Fossella and the Council of Jewish Organizations (COJO) for victims of violence in Israel on Staten Island in October 2023. Her office was also represented at a ''Prayer for Israel'' rally held by Chabad-Lubavitch on Eastern Parkway.', 'https://www.nysenate.gov/newsroom/in-the-news/2023/jessica-scarcella-spanton/day-mourning-and-prayer-bp-fossella-speaks', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (23, 16, 'Scarcella-Spanton received the Distinguished Legislator Award from COJO Flatbush in May 2025, where she emphasized support for Israel and the importance of fighting the rise in anti-Semitism, stressing her strong backing of Israel.', 'https://www.jewishpress.com/sections/community/jewish-community/cojo-flatbush-honors-legislators-israeli-diplomat-and-more/2025/05/08', '2025-05-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (24, 1, 'Lanza drafted a New York State Senate resolution to show support for Israel as violence escalated in May 2021. The resolution was co-sponsored by every member of the Senate Republican Conference. The Senate Majority refused to allow the resolution to be formally introduced, citing foreign policy concerns.', 'https://www.nysenate.gov/newsroom/press-releases/2021/andrew-j-lanza/senator-lanza-drafts-senate-resolution-show-support', '2021-05-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (24, 12, 'Lanza, as Senate Deputy Republican Leader, called on Governor Hochul to deploy the National Guard to protect Jewish students at Columbia University following pro-Hamas protests in April 2024, and demanded the resignation of Columbia University President Minouche Shafik. He characterized Columbia as a ''bastion of hatred.''', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-22');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (24, 5, 'Lanza led a Staten Island community effort in 2020 to condemn anti-semitic attacks and pledged to keep Staten Island''s Jewish community safe, stating ''People of faith and Staten Islanders of all traditions are rightfully alarmed at the heinous acts of hate that have recently occurred.''', 'https://www.nysenate.gov/newsroom/press-releases/2020/andrew-j-lanza/staten-island-community-leaders-condemn-anti-semitic', '2020-01-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (25, 3, 'Brisport is the lead Senate sponsor of the ''Not on Our Dime Act'' (S6992/S606), which would prohibit New York-based charities from funding Israeli settlement activity and allow the Attorney General to dissolve nonprofit status and fine organizations that knowingly fund settler activity. First introduced May 2023, reintroduced January 2025.', 'https://www.nysenate.gov/legislation/bills/2025/S606', '2025-01-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (25, 9, 'Brisport posted on X on April 13, 2024: ''A genocide is still occurring in Gaza.'' On March 27, 2024, he posted: ''Do not vote for genocide in the Democratic primary.''', 'https://canarymission.org/individual/Jabari_Brisport', '2024-04-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (25, 10, 'Brisport called for ''an immediate and permanent ceasefire in Palestine and an end to Israeli apartheid and occupation'' in an April 2024 socialist officials'' statement. In June 2020, he posted: ''We should not be subsidizing apartheid states. In fact, we should be actively opposing them & working to liberate the people they''re oppressing. / Free Palestine.''', 'https://x.com/JabariBrisport/status/1275094545336668161', '2020-06-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (25, 11, 'Brisport was arrested on October 20, 2023 at the ''Cease Fire Now Rally for Gaza'' on Fifth Avenue in Manhattan, where he and 139 other protesters blocked traffic. He posted: ''Last night I was arrested with 100+ peace activists calling for an immediate ceasefire.''', 'https://resistthemainstream.com/nyc-council-member-state-senator-arrested-among-100-others/', '2023-10-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (25, 15, 'Brisport was arrested at the ''Cease Fire Now Rally for Gaza'' on Fifth Avenue on October 20, 2023, among 139 anti-Israel protesters who blocked traffic. In a video shared on social media, the senator chants ''free Palestine'' while handcuffed behind NYPD officers.', 'https://freebeacon.com/latest-news/democratic-ny-lawmakers-arrested-at-anti-semitic-rally/', '2023-10-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (25, 13, 'Brisport did not issue a personal statement condemning Hamas after the October 7 attack. Instead, within two weeks he was arrested at a pro-ceasefire rally demanding an end to Israeli military operations. He posted on X using ''From the river to the sea'' rhetoric on December 20 and 21, 2023.', 'https://canarymission.org/individual/Jabari_Brisport', '2023-12-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (25, 8, 'Brisport posted on X: ''Our government isn''t simply allowing war crimes against Palestinians — it''s subsidizing them. To the lawmakers who opposed this bill & didn''t understand a year ago why we introduced it: I invite you to change course and stand with us now.'' He also joined JVP-NYC''s ''Break the Bonds'' campaign opposing NYC pension fund investment in Israel bonds.', 'https://x.com/JabariBrisport/status/1792561346489270605', '2024-05-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (28, 12, 'Krueger called Hamas''s October 7 actions ''absolutely despicable - carefully planned to murder, terrify, and kidnap civilians, including children'' and ''the largest single act of violence targeting Jews since the Holocaust.'' She stated ''Hamas members are not freedom fighters or liberators; it is a terrorist organization with the avowed aim of destroying Israel and Israelis.''', 'https://www.lizkrueger.com/sen-kruegers-message-on-the-tragedy-unfolding-in-israel/', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (28, 16, 'Krueger co-authored a statement by Jewish New York elected officials on Israel/Gaza and the hostage release and ceasefire deal in November 2023, calling for hostage return and expressing commitment to Israel''s Jewish and democratic future.', 'https://www.nysenate.gov/newsroom/articles/2023/liz-krueger/jewish-new-york-elected-officials-statement-israelgaza-and', '2023-11-22');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (28, 16, 'Krueger co-signed an open letter in February 2024 from Jewish elected officials stating ''We make no excuses for terrorists or their defenders, but we cannot support the actions of the current Israeli government'' and that ''the Israeli government cannot continue the mass destruction of Gaza and the killing of civilians.'' The letter called for a two-state solution and end to the Occupation.', 'https://www.nysenate.gov/newsroom/articles/2024/liz-krueger/open-letter-jewish-elected-officials-regarding-war-gaza', '2024-02-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (31, 4, 'Jackson is a co-introducer of S606 (2025), the "Not on our dime!: Ending New York funding of Israeli settler violence act," alongside Senators Brisport, Gonzalez, and Salazar. The bill prohibits not-for-profit corporations from engaging in unauthorized support of Israeli settlement activity.', 'https://www.nysenate.gov/legislation/bills/2025/S606', '2025-01-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (31, 11, 'Jackson joined a Jewish Voice for Peace protest at Grand Central Terminal on October 27, 2023, demanding an immediate ceasefire in Gaza. He stated: "I stood in solidarity with the Jewish Voice for Peace-NYC alongside my colleagues, New York State Legislators, and NYC Council Members, as we joined thousands of protesters at Grand Central Station last night, demanding an immediate ceasefire in Gaza to save lives."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (31, 15, 'Jackson participated in the Jewish Voice for Peace sit-in at Grand Central Terminal on October 27, 2023, joining thousands of protesters demanding a ceasefire in Gaza. Hundreds of protesters were arrested at the demonstration, which was led by JVP and IfNotNow.', 'https://www.jewishvoiceforpeace.org/2023/10/30/shut-it-down-grand-central-coverage/', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (35, 2, 'Stewart-Cousins voted in favor of S2492, S2493, and S4837 in 2017, anti-BDS bills that prohibit state contracting with, and state investment in, persons and businesses that promote or engage in activities to boycott American allied nations including Israel.', 'https://wespac.org/2017/03/11/open-letter-to-nys-senator-andrea-stewart-cousins/', '2017-03-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (35, 12, 'Stewart-Cousins strongly condemned the October 7 Hamas attack, stating "Everyone -- no matter your views -- should condemn this brutal act" and "We''ve seen unprecedented viciousness coming from Hamas aimed at innocent families and children." She also blasted a pro-Palestinian rally held October 8, 2023 as "completely inappropriate."', 'https://www.thecentersquare.com/new_york/article_8310379a-678e-11ee-976c-3f06a0b630d7.html', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (35, 14, 'Stewart-Cousins spoke at the "Westchester Stands With Israel" rally at Temple Israel Center of White Plains on October 10, 2023, attended by over 1,500 people. She stated: "The New York State Senate, the assembly, the governor, we are very clear that whatever is needed, whatever is necessary, whatever collaboration we must do, whatever support we must give, you will have."', 'https://jewishlink.news/westchester-stands-with-israel/', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (35, 5, 'Stewart-Cousins issued a statement on the Day of Action Against Antisemitism in 2021, saying she stands with her Jewish neighbors and will "continue to support legislation to combat hate and support critical funding to increase security at our synagogues and community centers." She also pushed for $45 million in funding for private school safety equipment following Oct. 7, tripling the previous $15 million allocation.', 'https://www.nysenate.gov/newsroom/press-releases/2021/andrea-stewart-cousins/statement-senate-majority-leader-andrea-13', '2021-05-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (33, 11, 'Rivera called for an immediate ceasefire, de-escalation, humanitarian aid to Gaza, and the release of all hostages. He was listed among New York elected officials calling for a ceasefire in Gaza by City & State New York.', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (37, 12, 'Mayer issued statement on Oct 10, 2023 strongly condemning Hamas attack: "hundreds of ordinary civilians were murdered by Hamas'' unprovoked attacks" and Hamas was "holding civilian hostages - including children." Stated "make no mistake, we stand by Israel without hesitation."', 'https://www.nysenate.gov/newsroom/articles/2023/shelley-b-mayer/statement-senator-shelley-mayer-war-israel', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (37, 14, 'Mayer spoke at the Westchester Stands With Israel Rally at Temple Israel Center in White Plains on Oct 10, 2023, attended by over 1,500 people. Event organized by Westchester Jewish Council and UJA Federation New York.', 'https://www.nysenate.gov/newsroom/articles/2023/shelley-b-mayer/lohud-westchester-stands-israel-during-rally-temple-israel', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (37, 16, 'Mayer issued Oct 7 anniversary statement reaffirming: "I remain steadfast in my support for Israel''s right to exist and defend itself from attacks on its citizens" and "believe the hostages must be brought home now while we work toward an end to the overall conflict."', 'https://www.nysenate.gov/newsroom/press-releases/2024/shelley-b-mayer/statement-senator-shelley-b-mayer-one-year-anniversary', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (37, 5, 'Mayer, as Chair of the Senate Education Committee, pushed for release of $45 million in Non-Public School Safety Equipment funding increased from $15 million to address urgent safety needs for Jewish and Islamic schools in New York amid rising antisemitism.', 'https://www.nysenate.gov/newsroom/press-releases/2023/shelley-b-mayer/nys-senators-applaud-release-45-million-non-public', '2023-10-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (38, 5, 'Weber sponsored S7752, the Combating Campus Antisemitism Act, which prohibits students from receiving TAP tuition assistance if engaging in antisemitic behavior using the IHRA working definition of antisemitism. Introduced November 2023 in response to post-Oct 7 campus incidents.', 'https://www.nysenate.gov/legislation/bills/2023/S7752', '2023-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (38, 12, 'Weber wrote in op-ed: "the atrocities committed on October 7th by the Hamas terror organization were horrific and the worst attack against the Jewish people since the Holocaust" and "the horrific attack by Hamas on Israel on Oct. 7 made it clear that hate is being taught right here in New York."', 'https://www.nysenate.gov/newsroom/in-the-news/2024/bill-weber/senator-weber-op-ed-say-no-hate-acts-antisemitism-have-been', '2024-01-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (38, 14, 'Weber delivered keynote address at Chabad gathering at Sleepy Hollow Hotel in Tarrytown on May 26, 2025, emphasizing "strong, bipartisan support for Israel" and encouraging Israelis and Jewish people to "remain united, regardless of political views, especially in times of national challenge."', 'https://www.rocklanddaily.com/news/senator-bill-weber-addresses-security-of-eretz-yisroel-and-rising-antisemitism-at-prominent-chabad-gathering-in-tarrytown', '2025-05-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (38, 5, 'Weber appointed to Senate Republican Antisemitism Working Group in February 2023. Co-authored 2023-2024 antisemitism report released March 27, 2024, recommending legislative action to combat rising antisemitic hate crimes in New York.', 'https://www.nysenate.gov/newsroom/press-releases/2024/bill-weber/republican-state-senators-unveil-antisemitism-report', '2024-03-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (39, 5, 'Rolison joined the Senate Republican Conference''s Antisemitism Working Group on Feb 5, 2026 at his own initiative. Stated "When people are targeted and threatened because of their faith, that''s unacceptable." Criticized NYC Mayor Mamdani for rolling back antisemitism executive orders.', 'https://www.jns.org/new-member-of-ny-state-senate-jew-hatred-panel-aims-to-hold-state-officials-accountable-on-safety/', '2026-02-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (39, 12, 'Rolison pointed to the surge of campus protests after Oct. 7 as an example of how quickly tensions can escalate, stating "Our responsibility isn''t just to be reactive." Emphasized personal commitment to Jewish safety despite not being Jewish himself.', 'https://www.jns.org/new-member-of-ny-state-senate-jew-hatred-panel-aims-to-hold-state-officials-accountable-on-safety/', '2026-02-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (40, 12, 'Harckham stated: "My supporters in the Jewish community know that I stood with them after the October 7 terrorist attacks - and still stand with them today." Said he hosted four community forums on hate speech denouncing antisemitism after Oct. 7 attack. Visited Israel in 2012 in solidarity.', 'https://www.theexaminernews.com/harckham-arena-spar-as-40th-senate-district-race-shifts-into-high-gear/', '2024-09-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (40, 5, 'Harckham has hosted six "Hate in the Age of Multiculturalism" forums since taking office, including forums specifically addressing antisemitism after Oct 7. Hosted student forum in Brewster on hate in the age of multiculturalism.', 'https://www.nysenate.gov/newsroom/press-releases/2024/pete-harckham/harckham-hosts-forum-students-brewster-hate-age', '2024-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (41, 14, 'Hinchey spoke at "Stand With Israel" prayer service at Congregation Emanuel in Kingston on Oct 18, 2023. Stated: "My heart breaks for my Jewish peers. We are bonded in that shared trauma." Called for humanity and denounced hate.', 'https://hudsonvalleyone.com/2023/10/19/stand-with-israel-prayer-service-at-congregation-emanuel/', '2023-10-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (41, 12, 'Hinchey, who is Jewish on her mother''s side, spoke at Stand With Israel prayer service on Oct 18, 2023 stating: "My heart breaks for my Jewish peers" and "The world I believe in is one where we respect support and love one another. And yet we find ourselves grappling with the dehumanizing notion that we can still be blinded by hate."', 'https://hudsonvalleyone.com/2023/10/19/stand-with-israel-prayer-service-at-congregation-emanuel/', '2023-10-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (42, 5, 'Skoufis sponsored mask ban bill (S3070) in the NY Senate aimed at preventing antisemitic harassment. Stated: "It''s critical that there''s broad buy-in for this public safety measure to ensure we don''t go another year during which people are attacked by individuals who cover their faces to evade accountability."', 'https://jewishinsider.com/2024/07/new-york-mask-ban-protests-antisemitism-bipartisan-support/', '2024-07-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (42, 5, 'Skoufis stood in solidarity with local faith leaders and legislators against antisemitism in Newburgh on Aug 31, 2023, after antisemitic posters appeared on poles and signs. Stated: "It''s despicable and it''s really unsettling that right here in our own backyard in the year 2023, we still see such antisemitism."', 'https://www.nysenate.gov/newsroom/in-the-news/2023/james-skoufis/local-leaders-denounce-antisemitism', '2023-09-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (43, 12, 'Ashby posted on Facebook after Oct 7 attack: "Peaceful towns I recently visited on a legislative exchange trip to Israel are under siege from Hamas rockets and occupied by terrorists. Today, I''m praying for the friends I made and for Israel''s allies, especially our country, to demonstrate their steadfast support and ensure they prevail."', 'https://www.facebook.com/JakeAshbyforNYSSenate/posts/962654662340037/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (43, 14, 'Ashby visited Israel on a legislative exchange trip, including Kibbutz Kfar Aza, prior to the Oct 7 attack. He referenced this visit in his statement expressing solidarity with Israel after the Hamas attack.', 'https://www.facebook.com/JakeAshbyforNYSSenate/posts/962654662340037/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (43, 5, 'Ashby cosponsored S7773, the Dismantling Student Antisemitism (DSA) Act, requiring mandatory antisemitism awareness training at SUNY/CUNY and all accredited higher education institutions, with reporting requirements. Introduced Nov 29, 2023 in response to rising antisemitism following Oct 7 Hamas attack.', 'https://www.nysenate.gov/legislation/bills/2023/S7773', '2023-11-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (44, 5, 'Tedisco sponsored S7773, the Dismantling Student Antisemitism (DSA) Act, requiring mandatory antisemitism awareness and prevention training at all accredited higher education institutions in NY. Stated: "People have a 1st Amendment right of freedom of speech, but they don''t have a right to be antisemites or racists with a state-subsidized education."', 'https://www.nysenate.gov/newsroom/press-releases/2023/james-tedisco/tedisco-no-tax-dollars-anti-semites-racists-college', '2023-11-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (44, 12, 'Tedisco introduced legislation for lifetime expulsion of SUNY/CUNY students convicted of hate crimes, explicitly citing "the October 7th Hamas terrorist attack on Israel that resulted in the deaths of over 1,400 people and the taking hostage of 240 Israelis, Americans and others" as the catalyst for rising campus antisemitism.', 'https://www.nysenate.gov/newsroom/press-releases/2023/james-tedisco/tedisco-no-tax-dollars-anti-semites-racists-college', '2023-11-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (44, 5, 'Tedisco sponsored S9297 with Assemblyman Eichenstein, bipartisan bill to add antisemitic desecration of Jewish cemeteries to state hate crimes law, elevating penalties. Stated: "Antisemitism, racism, intolerance, and hatred are the center of evil and must be opposed whenever they rear their ugly head." Referenced rising antisemitism following Oct 7 Hamas attack.', 'https://www.nysenate.gov/newsroom/press-releases/2024/james-tedisco/tedisco-eichenstein-call-new-bipartisan-bill-add', '2024-10-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (45, 14, 'Stec visited Israel in December 2022 on a legislative tour with the America-Israel PAC, including Kibbutz Kfar Aza. He stated: "I was invited to go over under the America-Israel PAC. They''re there to foster the value and the importance of the relationship between the United States and Israel." He walked the streets of the kibbutz and met residents before it was attacked on Oct 7.', 'https://www.wrvo.org/2023-10-13/state-senator-recalls-trip-to-kibbutz-attacked-by-hamas', '2023-10-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (45, 12, 'Stec recalled his visit to Kibbutz Kfar Aza after the Oct 7 Hamas attack, noting he had met residents who were later killed or taken hostage. He stated a woman he met "had collected a bunch of debris" from prior rocket attacks, and learned "her sister and nieces and nephews had been taken hostage." Said: "If it wasn''t for that trip I wouldn''t have had a personal connection."', 'https://www.wrvo.org/2023-10-13/state-senator-recalls-trip-to-kibbutz-attacked-by-hamas', '2023-10-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (45, 5, 'Stec cosponsored S3275, a bill to place a definition of anti-Semitism within the state human rights law, providing that antisemitism shall constitute a violation of the human rights law and that antisemitism inciting violence or property damage shall be deemed a hate crime.', 'https://www.nysenate.gov/legislation/bills/2023/S3275', '2023-02-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (46, 11, 'Fahy (then Assemblywoman) posted on Instagram: "We need a ceasefire now and the return of all hostages." Also listed among NY elected officials calling for ceasefire by City & State NY.', 'https://www.instagram.com/p/C2fOj8HgGsk/', '2024-01-24');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (46, 12, 'Fahy responded to shooting outside Temple Israel in Albany on the first night of Hanukkah 2023 (suspect shouted "Free Palestine"): "I''m horrified over reports of shots fired outside Temple Israel in Albany today. Thankfully, no one was hurt and the suspect was detained. To our Jewish community in Albany and the Capital Region — we stand with you, and we share your pain. Hate will never win here."', 'https://x.com/PatriciaFahy46/status/1732883977193541768', '2023-12-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (46, 5, 'Fahy sponsored S5784, legislation to create a permanent New York State Holocaust Memorial at the Empire State Plaza. Stated: "When we say ''Never Again'', we need to act in order for those words to have meaning." Bill passed both houses and was signed by Governor Hochul. The memorial is intended to educate about the Holocaust and the dangers of antisemitism, racism, and intolerance.', 'https://www.nysenate.gov/newsroom/press-releases/2025/patricia-fahy/nys-legislature-passes-fahy-romero-legislation-create', '2025-06-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (46, 5, 'Fahy, as Chair of Assembly Higher Education Committee, stated: "There is no place for hate, including antisemitism, in our civil or political discourse, or New York State more broadly" and that students engaging in antisemitic threats or violence should face disciplinary action. Defended not signing GOP antisemitism bill while maintaining strong stance against antisemitism.', 'https://www.dailygazette.com/news/govt_politics/danz-fahy-antisemitism/article_94c3fe42-1137-11ef-a445-e7f56fb965e2.html', '2024-05-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (47, 12, 'Bottcher (then City Council member) posted on X on Oct 7, 2023: "I stand in total solidarity with the people of Israel and condemn the Hamas terrorist organization''s attacks during the Sukkot holiday. Hamas has kidnapped innocent civilians from Israeli towns, reportedly including grandmothers, and we demand their safe return."', 'https://x.com/ebottcher/status/1710683878640197935', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (47, 14, 'Bottcher attended event at Central Synagogue on Oct 23, 2023 meeting families of Israeli-American hostages taken by Hamas. Posted: "This morning at Central Synagogue I was part of a small group of elected officials who met with family members of Israeli-Americans who were taken hostage by the Hamas terrorists. We heard from a father whose daughter was kidnapped, from a sister whose sister was kidnapped."', 'https://x.com/ebottcher/status/1716487375998669173', '2023-10-23');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (47, 14, 'Bottcher was among 13 NYC politicians who participated in an all-expenses paid solidarity tour to Israel in November 2023, hosted by the Jewish Community Relations Council of New York (JCRC). Trip included City Councilmembers, borough presidents, and state legislators.', 'https://www.jfrej.org/news/2023/11/politico-war-time-tour', '2023-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (47, 12, 'Bottcher stated after the December 2025 Sydney Hanukkah massacre that slogans like "globalize the intifada" "don''t advance justice, they escalate hostility and make Jewish communities feel targeted." Added: "Leaders should be lowering the temperature" and "we should be unequivocal: antisemitic violence is unacceptable, full stop."', 'https://jewishinsider.com/2025/12/hanukkah-massacre-sydney-globalize-the-intifada-slogan-democrats-new-york/', '2025-12-22');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (51, 5, 'Oberacker sponsored bill S8774, which expands the prohibition of harassing conduct involving Nazi symbols, making the display of Nazi Germany symbols in a public location in a manner likely to cause another person to feel harassed, annoyed, threatened or alarmed a crime of aggravated harassment. Oberacker stated: "My bill, S8774, is simple and straightforward. It will criminalize the display of Nazi symbols and give police and prosecutors another tool to charge those who are targeting Jewish individuals."', 'https://www.nysenate.gov/legislation/bills/2023/S8774', '2024-03-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (51, 5, 'Oberacker, as a member of the NY Senate Republican Antisemitism Working Group, called for antisemitism legislation to be an Albany priority, stating: "Heinous, violent acts in the name of antisemitism have been on the rise in New York and we must take decisive action to halt these disturbing crimes" and "Now it is time for Albany to make these bills an immediate priority to ensure no one comes under attack because of their faith or religion."', 'https://www.nysenate.gov/newsroom/press-releases/2024/peter-oberacker/senator-oberacker-calls-antisemitism-legislation-be', '2024-03-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (51, 14, 'Oberacker joined the NY Senate Minority Conference at an Albany rally with Run For Their Lives, calling for the return of hostages held by Hamas in Gaza. Oberacker stated: "I stand with you in your continued fight to bring the hostages home" and "It is vital that we keep the spotlight on the hostage crisis and ensure that the innocent individuals taken by Hamas terrorists are not forgotten."', 'https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senate-minority-conference-joins-run-their-lives', '2024-04-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (51, 16, 'Oberacker joined Senate Republican Leader Rob Ortt and the Senate Republican Antisemitism Working Group in a letter to Governor Hochul calling for immediate action to help New Yorkers stranded in Israel during the Israel-Iran conflict, including organizing emergency rescue flights. Oberacker stated: "Our families are desperate for answers, and our citizens deserve the full support of their state."', 'https://www.nysenate.gov/newsroom/articles/2025/robert-g-ortt/official-correspondence-senate-republicans-asking-governor', '2025-06-24');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (53, 5, 'Griffo sponsored bill S6842 (and its predecessors S3275, S4563, S4932A across prior sessions), which places a definition of antisemitism within the NY state human rights law and provides that antisemitic acts causing violence, injury, or property damage shall constitute a hate crime.', 'https://www.nysenate.gov/legislation/bills/2025/S6842', '2025-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (53, 5, 'Griffo, as a member of the Senate Republican Antisemitism Working Group, expressed disappointment after two bills protecting Jewish students and addressing antisemitism on college campuses were blocked in committee, stating that students should feel safe on campus regardless of their religion.', 'https://www.nysenate.gov/newsroom/press-releases/2025/joseph-griffo/griffo-antisemitism-working-group-express-disappointment', '2025-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (53, 12, 'Griffo, as ranking member of the Senate Higher Education Committee, urged Cornell University''s president to condemn the "reprehensible" remarks of professor Russell Rickford, who called the Hamas October 7 terrorist attacks on Israel "exhilarating" and "energizing" at an off-campus rally. Griffo called the remarks a defense of terrorism.', 'https://www.nysenate.gov/newsroom/press-releases/2023/joseph-griffo/griffo-cornell-university-should-condemn-reprehensible', '2023-10-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (53, 12, 'Griffo and the Senate Republican Working Group on Antisemitism issued a statement condemning the "Not on Our Dime" bill as "the latest in a disgusting trend of antisemitic sentiment and a clear attack on the State of Israel and the Jewish people," stating: "We remain unequivocal in our support of Israel and our Jewish population here in New York." The statement referenced the "horrific attacks on Israel on October 7th" and the "disturbing rise of antisemitism" that followed.', 'https://www.nysenate.gov/newsroom/press-releases/2024/joseph-griffo/statement-new-york-state-sen-joseph-griffo-and-senate', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (53, 12, 'Griffo expressed disgust at the murder of two Israeli Embassy staff members outside the Capital Jewish Museum in Washington, D.C. in May 2025, calling it a heinous act of antisemitic violence.', 'https://www.nysenate.gov/newsroom/press-releases/2025/joseph-griffo/griffo-statement-murders-israeli-embassy-staff-members', '2025-05-22');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (53, 14, 'Griffo joined the NY Senate Minority Conference at an Albany rally with Run For Their Lives, calling for the return of hostages held by Hamas in Gaza, on the 179th day of captivity.', 'https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senate-minority-conference-joins-run-their-lives', '2024-04-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (53, 16, 'Griffo joined Senate Republicans in calling on Democratic committee chairs to demand answers from Columbia University President Minouche Shafik regarding pro-Hamas protests on campus and the safety of Jewish students, in the wake of the October 7 attacks.', 'https://www.nysenate.gov/newsroom/press-releases/2024/thomas-f-omara/senate-republicans-call-democratic-committee-chairs', '2024-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (54, 5, 'Helming is a cosponsor of S3275 (Griffo), which places a definition of antisemitism within the NY state human rights law and provides that antisemitic acts causing violence or property damage shall constitute a hate crime.', 'https://www.nysenate.gov/legislation/bills/2023/S3275', '2023-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (54, 5, 'Helming is a cosponsor of S1752, the "Dismantling Student Antisemitism Act" (DSA Act), which amends education law to address antisemitism on college campuses.', 'https://www.nysenate.gov/legislation/bills/2025/S1752', '2025-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (54, 5, 'Helming joined the Senate Republican Antisemitism Working Group as it released its 2023-2024 antisemitism report on March 27, 2024, and sent a letter to Governor Hochul and Legislative Majority Leaders recommending legislative action to combat the increase in antisemitic hate crimes in New York.', 'https://www.nysenate.gov/newsroom/articles/2024/pamela-helming/senate-republicans-recommend-legislative-action-combat', '2024-03-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (54, 14, 'Helming joined the NY Senate Minority Conference at an Albany rally with Run For Their Lives, calling for the return of hostages held by Hamas in Gaza. Helming stated: "I proudly stand with Run for Their Lives New York in their fight to bring these innocent civilians home."', 'https://www.nysenate.gov/newsroom/press-releases/2024/mario-r-mattera/senate-minority-conference-joins-run-their-lives', '2024-04-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (57, 14, 'Borrello joined the Senate Republican Conference in calling on Governor Hochul to deploy the National Guard at Columbia University, stating "the governor must act now" against antisemitic mobs targeting Jewish students during pro-Hamas campus protests.', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (57, 12, 'Borrello called for "swift and decisive action against the antisemitic mobs" at Columbia University and demanded the resignation of university president Shafik, as part of the Senate Republican Conference response to pro-Hamas demonstrations in the wake of the October 7 attack.', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (58, 14, 'O''Mara joined the Senate Republican Conference in calling on Governor Hochul to deploy the National Guard at Columbia University, stating "New York State cannot stand for the anti-Jewish, anti-American hatred and violence" and demanding "immediate, unequivocal, and strong action against radical extremists."', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (58, 12, 'O''Mara stated "Governor Hochul must take immediate, unequivocal, and strong action against these radical extremists" at Columbia, condemning the anti-Jewish protests that followed Hamas''s October 7 attack and demanding the resignation of the university president.', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (59, 11, 'Gonzalez called for "an immediate ceasefire" on October 27, 2023, stating it is "not only the right answer, it is the only answer" and "the only way to de-escalate tensions in the region, ensure immediate access to critical humanitarian aid in Gaza, and ensure the safe return of all hostages."', 'https://www.nysenate.gov/newsroom/press-releases/2023/kristen-gonzalez/statement-senator-kristen-gonzalez-responds', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (59, 9, 'Gonzalez wrote on October 13, 2023: "Make no mistake, these actions by the Israeli government are genocidal." In her October 27 statement she reiterated: "Just as I condemned the Hamas terrorist attacks, I condemn the genocidal actions of the IDF."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-10-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (59, 4, 'Gonzalez cosponsored S6992 (2023) and S606 (2025), the "Not on Our Dime!: Ending New York Funding of Israeli Settler Violence Act," which would prohibit not-for-profit corporations from engaging in unauthorized support of Israeli settlement activity and empower the AG to dissolve violating groups.', 'https://www.nysenate.gov/legislation/bills/2025/S606', '2023-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (59, 15, 'Gonzalez co-hosted a town hall with Assembly Member Zohran Mamdani on August 29, 2023, at CUNY School of Law in Long Island City to promote the "Not on Our Dime!" bill, attended by over 200 people. She stated: "it should not be on our dime that we would fund what we have universally admitted is a human rights violation."', 'https://licpost.com/queens-lawmakers-push-controversial-bill-banning-ny-charities-from-supporting-israeli-organizations-in-west-bank-settlements', '2023-08-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (59, 12, 'Gonzalez stated on October 12, 2023: "I am horrified by Hamas'' brutality toward Israeli civilians, and I condemn—in the strongest terms possible—all violence against civilians." However, within two weeks she equated this with Israeli actions, stating "Just as I condemned the Hamas terrorist attacks, I condemn the genocidal actions of the IDF."', 'https://www.nysenate.gov/newsroom/press-releases/2023/kristen-gonzalez/senator-kristen-gonzalez-responds-ongoing-violence', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (60, 14, 'Gallivan joined the full Senate Republican Conference in calling on Governor Hochul to deploy the National Guard at Columbia University to protect Jewish students from antisemitic pro-Hamas protests, and demanding the immediate resignation of Columbia University President Shafik.', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (60, 12, 'Gallivan, as a member of the Senate Republican Conference, joined the statement condemning "Antisemitic, anti-American, and in many cases illegal" protests at Columbia, describing Hamas as "a known terror organization with a similar world view as Al Qaeda and ISIS" and calling for action to protect Jewish students.', 'https://www.nysenate.gov/newsroom/press-releases/2024/andrew-j-lanza/members-new-york-state-senate-republican-conference', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (62, 1, 'Ortt sponsored S1584, which would prohibit student organizations that participate in hate-speech including advocating for BDS of Israel from receiving public funding. He also sponsored S1528, prohibiting state contracting with businesses that boycott American allied nations. S1584 previously passed the Senate with bipartisan support (48-14 in 2016, 48-12 in 2017 and 2018).', 'https://www.nysenate.gov/legislation/bills/2023/S1584', '2023-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (62, 12, 'Ortt stated on October 8, 2023: "Israel is at war with terrorists who share the same mentality of the 9/11 hijackers. We stand with Israel and against their sympathizers in our midst." He added: "I have always been proud to stand with Israel" and called for the US to remain "steadfast in our support of Israel and their right to defend the Jewish state."', 'https://www.thedailynewsonline.com/news/lawmakers-express-shock-anger-at-attacks-on-israel/article_eca88328-66bd-11ee-b883-031d74860374.html', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (62, 5, 'Ortt created the Senate Republican Anti-Semitism Working Group in March 2023 to hold roundtables statewide and develop legislative recommendations addressing the rise in antisemitic incidents. The group produced a formal report with legislation proposals in 2024, and Ortt called for defunding institutions that fail to address campus antisemitism.', 'https://www.nysenate.gov/newsroom/press-releases/2023/robert-g-ortt/senate-republican-leader-rob-ortt-announces-creation', '2023-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (62, 14, 'Ortt joined faith leaders, elected officials, and members of the Jewish community at a "Bring Them Home Tour" press conference at Statler Buffalo on September 24, 2024, calling for the release of American hostages held by Hamas. Hundreds of yellow ribbons were tied around trees in Niagara Square to mark the first anniversary of October 7.', 'https://www.nysenate.gov/newsroom/press-releases/2024/robert-g-ortt/nys-senator-and-minority-leader-rob-ortt-joined-faith', '2024-09-24');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (62, 16, 'Ortt issued a statement on March 14, 2024, criticizing Senator Schumer''s call for new elections in Israel, stating the true "obstacle to peace" is "the Hamas backed terror regime that sanctioned the rape and murder of Israeli civilians on October 7th" and that "peace in the region will only come when the United States stands strongly in support of Israel''s right to defend itself."', 'https://www.nysenate.gov/newsroom/press-releases/2024/robert-g-ortt/statement-senate-republican-leader-rob-ortt-senator', '2024-03-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (62, 16, 'Ortt led Senate Republicans in sending a letter to Governor Hochul demanding action to bring home New Yorkers stranded in Israel during the Iran conflict, writing: "New York''s connection to Israel is unmatched, and so is our responsibility. Our state should lead in standing with Israel, supporting Jewish communities under threat."', 'https://www.nysenate.gov/newsroom/press-releases/2025/patricia-canzoneri-fitzpatrick/senator-canzoneri-fitzpatrick-minority', '2025-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (62, 14, 'Ortt led the Senate Republican Conference in calling on Governor Hochul to deploy the National Guard at Columbia University. He stated: "President Shafik must provide answers and inform the Legislature of her plan going forward to put an end to these violent, anti-Jewish protests" and called Hamas "a known terror org with a similar worldview as Al Qaeda and ISIS."', 'https://www.nysenate.gov/newsroom/press-releases/2024/robert-g-ortt/senate-republicans-call-democratic-committee-chairs', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (64, 14, 'Schiavoni attended the Rally in Solidarity with Israel held at the Jewish Center of the Hamptons in East Hampton on October 11, 2023, as Southampton Town Councilman, joining approximately 300 attendees in a show of support for Israel following the October 7 Hamas attack', 'https://patch.com/new-york/easthampton/rally-solidarity-israel-draws-crowd-li-no-one-alone', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (65, 16, 'Giglio signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, which condemned the October 7 attack as a "war crime" and declared "We will continue to stand with Israel"', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (65, 12, 'Giglio co-signed the "New York Legislators Stand with Israel" letter which called the October 7 attack "a despicable sneak attack against the Israeli people" and "a cruel, barbaric and brutal throwback to primitive times," condemning the taking of hostages, murder of civilians, and use of torture', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (66, 12, 'DeStefano called for the release of 134 hostages held in Gaza since the "Oct. 7 terrorist attacks," attending the "Run for Their Lives" rally and stating the situation involves "an atrocious and horrifying war and hostage situation"', 'https://nyassembly.gov/mem/Joe-DeStefano/story/109870', '2024-04-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (66, 14, 'DeStefano attended the "Run for Their Lives" rally on April 2, 2024, a pro-Israel hostage awareness event, stating "I am honored to be able to say I was one of many individuals who attended" and urging the federal government to bring New Yorkers held hostage home', 'https://nyassembly.gov/mem/Joe-DeStefano/story/109870', '2024-04-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (67, 5, 'Kassay stated "For our Jewish community members, I share their relief that the fight against antisemitism will remain a priority in District Four" and cited her support for legislation aimed at addressing hate and discrimination in communities and on college campuses, as well as partnerships with local rabbis and faith leaders', 'https://www.jta.org/2026/02/03/politics/a-gen-z-student-activist-against-antisemitism-is-running-for-state-assembly-on-long-island', '2026-02-03');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (68, 16, 'Smith signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, which condemned the October 7 attack as a "war crime" and declared "We will continue to stand with Israel"', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (68, 12, 'Smith co-signed the "New York Legislators Stand with Israel" letter which called the October 7 attack "a despicable sneak attack against the Israeli people" and "a cruel, barbaric and brutal throwback to primitive times," condemning the taking of hostages, murder of civilians, and use of torture', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (68, 5, 'Smith, as co-chairman of the Assembly Minority Task Force on School Safety & Security and ranking member of the Education Committee, condemned antisemitism at Hillcrest High School stating "The recent incidents of violence and antisemitism at Hillcrest High School in Queens demand immediate and steadfast attention" and called for "swift, significant action"', 'https://nyassembly.gov/mem/Doug-Smith/story/108238', '2023-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (128, 12, 'Lee stated in her 2024 JOLDC questionnaire: "I fully support Israel''s right to defend itself and I fully condemn the terrorist attacks on October 7th." She added: "We must bring all the hostages home, ensure humanitarian aid is getting to Palestinian civilians and there is a long term two-state solution where Israel and Palestine can live in peace."', 'https://jimowles.org/news/candidate-answers-to-joldc-grace-lee-for-ny-assembly-district-65-2024', '2024-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (129, 2, 'Glick spoke in support of the NY Assembly anti-BDS resolution on June 18, 2015, stating: "The people who have started this movement are not honest in that they, when asked, if they support the right of Israel to exist, exist in any shape or form, they either demur and refuse to answer the question or indeed indicate that they really don''t believe that Israel should exist...I support very, very strongly, this resolution." The resolution, introduced by Assemblyman Walter T. Mosley with 74 co-sponsors, rejected the BDS movement.', 'https://nyassembly.gov/mem/Deborah-J-Glick/video/6229/', '2015-06-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (130, 16, 'Rosenthal co-organized a letter with 66 Assembly Democrats condemning the "Not on Our Dime!: Ending New York Funding of Israeli Settler Violence Act" (A6943), introduced by Assemblymember Zohran Mamdani. The letter denounced the bill as "a ploy to demonize Jewish charities with connections to Israel" and to "antagonize pro-Israel New Yorkers and further sow divisions within the Democratic Party." The letter was led by Assemblymember Daniel Rosenthal and signed by a majority of the 150-member Assembly''s Democrats.', 'https://www.algemeiner.com/2023/05/18/majority-of-new-york-state-assembly-democrats-condemn-bill-targeting-pro-israel-charities/', '2023-05-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (132, 12, 'Lasher referred to the October 7 attacks as "horrific" in the context of his ACCESS Act legislation, stating the bill responds to "incidents of harassment and discrimination -- not just antisemitism, which we have seen more and more since the horrific attacks of October 7th." He also stated he wanted to see "Hamas out of Gaza and Netanyahu out of the Knesset."', 'https://nyassembly.gov/mem/Micah-C-Lasher/story/113014', '2025-02-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (132, 14, 'Lasher received $36,486 in campaign funds from the pro-Israel lobby group Solidarity PAC, which backs candidates "who value the American alliance with Israel." In his 2024 victory speech for Assembly District 69, Lasher stated that his campaign "was a place where you could be both a proud progressive and a proud Zionist," adding "Everyone should look at the results of this election and know that the voters in the highest-turnout Assembly District in the state of New York don''t think you have to choose."', 'https://forward.com/news/766762/micah-lasher-jerry-nadler-congress/', '2024-06-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (132, 5, 'Lasher sponsored the ACCESS Act (Assuring College Campus and Educational Safety and Support Act), which requires colleges and universities to take proactive steps to prevent and respond to harassment based on student identity, aligning legal standards with workplace discrimination laws and allowing lawsuits against universities that allow unchecked harassment. The legislation was supported by UJA-Federation, Anti-Defamation League, and StandWithUs and was introduced in response to rising campus antisemitism.', 'https://vinnews.com/2025/02/10/new-york-lawmakers-push-bills-to-combat-campus-antisemitism/', '2025-02-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (132, 16, 'Lasher tweeted on October 28, 2023: "This is a particularly vital corrective to the awful use of the word ''genocide'' by some westerners to describe Israel''s actions." He also tweeted on October 1, 2024 during the Iran-Israel conflict: "The path to lasting peace in the Middle East does not involve acquiescing to the Iranian regime and its terrorist proxies. It requires defeating them. This is not a fight Israel ever would have wanted but it is the fight they must win. Praying for Israel and peace."', 'https://x.com/MicahLasher/status/1718276762616901818', '2023-10-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (133, 11, 'Wright answered "Yes" when asked "Do you support an immediate ceasefire in the Middle East?" in his 2024 JOLDC questionnaire for the Assembly District 70 race.', 'https://jimowles.org/news/candidate-answers-to-joldc-jordan-jg-wright-for-ny-assembly-district-70-2024', '2024-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (133, 8, 'Wright stated in his 2024 JOLDC questionnaire when asked about conditioning aid to Israel: "In order to achieve a ceasefire, the U.S. must leverage its immense international power; though I leave it to foreign affairs experts and officials on which conditions are appropriate and viable options for negotiations for what is a matter impacting many nations."', 'https://jimowles.org/news/candidate-answers-to-joldc-jordan-jg-wright-for-ny-assembly-district-70-2024', '2024-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (134, 14, 'Taylor held an October 7th, 2023 Vigil for Israel Victims, as listed on his official New York State Assembly media page. The vigil commemorated the victims of the Hamas terrorist attack on Israel.', 'https://assembly.state.ny.us/mem/Al-Taylor/media/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (135, 4, 'De Los Santos was an original cosponsor of A6943, the "Not on Our Dime!: Ending New York funding of Israeli settler violence act," introduced by Assemblymember Zohran Mamdani in May 2023. The bill would prohibit not-for-profit corporations from engaging in unauthorized support of Israeli settlement activity. However, De Los Santos withdrew his name as cosponsor within days of the bill''s introduction.', 'https://forward.com/fast-forward/547366/ny-lawmakers-criticize-bill-that-would-penalize-charitable-groups-supporting-israeli-settlements/', '2023-05-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (135, 16, 'De Los Santos withdrew as cosponsor of the "Not on Our Dime" bill and signed a letter led by Assemblymembers Daniel Rosenthal and Nily Rozic condemning the legislation. The letter, signed by 66 Democratic assemblymembers, called the bill "a ploy to demonize Jewish charities with connections to Israel" that was "only introduced to antagonize pro-Israel New Yorkers and further sow divisions within the Democratic Party."', 'https://www.algemeiner.com/2023/05/18/majority-of-new-york-state-assembly-democrats-condemn-bill-targeting-pro-israel-charities/', '2023-05-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (136, 12, 'Bores publicly condemned Hamas as a terrorist organization and joined hundreds of New Yorkers at a rally demanding the release of all hostages abducted by Hamas, stating that "terrorists don''t get to make demands after taking civilians -- women, the elderly, infants -- from their homes." He also stated the October 7 attack was "horrifying and despicable" and that "antisemitism is a growing threat around the world."', 'https://www.washingtonexaminer.com/premium/4393546/will-new-york-12th-congressional-district-election-choose-israel-supporter/', '2023-10-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (136, 14, 'Bores joined hundreds of New Yorkers at a rally demanding the release of all hostages abducted by Hamas. He stated: "terrorists don''t get to make demands after taking civilians -- women, the elderly, infants -- from their homes. Bring them home."', 'https://www.cbsnews.com/newyork/news/rally-set-to-be-held-on-manhattans-east-side-as-calls-grow-for-hamas-to-release-hostages/', '2023-10-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (136, 5, 'Bores stated: "I have repeatedly condemned the use of the slogan ''globalize the intifada.'' I believe that phrase, regardless of a specific speaker''s intent, has been tied inextricably to violent attacks, strikes fear in many New Yorkers and has no place in our city." He further stated: "Any rhetoric or actions that dehumanize Jews, incite violence or put Jewish communities at risk must be called out and stopped, without exceptions."', 'https://www.commentary.org/seth-mandel/mass-murderers-dont-care-how-jews-feel/', '2024-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (136, 11, 'Bores stated in his 2024 JOLDC questionnaire: "I support a sustainable ceasefire which can only begin with the return of the hostages. It should also include assurances that another attack like that on October 7th will not be the stated goal of whomever winds up ruling Gaza." He also stated that "Israel should not move to reoccupy Gaza." Note: this is a conditional ceasefire position tied to hostage return, not an unconditional ceasefire call.', 'https://jimowles.org/news/candidate-answers-to-joldc-alex-bores-for-ny-assembly-district-73-2024', '2024-01-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (137, 14, 'Powers, as NYC Council Member, held a street co-naming ceremony designating East 67th Street as "Yad Vashem Way" in honor of the World Holocaust Remembrance Center. He stated: "In a time of rising antisemitism and fear, it is more important than ever before that we remember what happened during the Holocaust. New York City is home to the most survivors of the Holocaust outside of Israel." He called the dedication "a no-brainer" and "a major opportunity to honor an important institution."', 'https://council.nyc.gov/keith-powers/press/new-york-city-council-member-keith-powers-holds-street-co-naming-of-east-67th-street-in-honor-of-yad-vashem/', '2025-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (137, 12, 'Powers released a statement on the ceasefire deal saying: "I am relieved that Israel and Hamas have come to an agreement to cease fighting in Gaza... Hostages who have been held captive by Hamas are on their way home, returned to their families after suffering more than a year of imprisonment. Every single hostage must be returned safely, and the remains of those who died in captivity must be returned to receive burial." When a Republican opponent sent a mailer accusing him of being a "Hamas coddler," over 250 east siders signed a letter stating "Keith Powers has always been a true ally to the Jewish community."', 'https://council.nyc.gov/keith-powers/press/new-york-city-council-member-keith-powers-statement-on-ceasefire-deal-in-the-middle-east/', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (137, 5, 'Powers spoke about rising antisemitism during the Yad Vashem Way street naming ceremony, stating there was "a very deeply concerning rise in antisemitism throughout the city" and emphasizing the importance of saying "Never again." Over 250 residents signed a letter confirming Powers "has always been a true ally to the Jewish community" after a political opponent tried to question his record.', 'https://www.timesofisrael.com/spotlight/new-york-city-honors-holocaust-center-and-survivors-with-a-street-naming/', '2025-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (138, 8, 'Simone stated in his 2024 JOLDC questionnaire response: "I agree with President Biden''s recent moves to limit the supply of offensive weapons that would be used in a Rafah operation that would undoubtedly result in massive civilian casualties." This indicates support for conditioning military aid to Israel.', 'https://jimowles.org/news/candidate-answers-to-joldc-tony-simone-for-ny-assembly-district-75-2024', '2024-06-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (139, 12, 'Seawright released a statement on October 7, 2023: "I strongly condemn the horrific and depraved attacks on the citizenry of Israel and extend deepest and profound condolences to the families and friends." She also expressed being "deeply distressed by the many reports of blatant antisemitism and expressions of support for terrorism by some protestors at Columbia University, New York University and at other colleges in New York and elsewhere."', 'https://nyassembly.gov/mem/Rebecca-A-Seawright/press/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (139, 5, 'Seawright hosted an antisemitism town hall in July 2025 at the Upper East Side''s Lenox Hill Neighborhood House, gathering rabbis, Jewish advocates, and educators to speak on a panel about the rise in antisemitic incidents since October 7, 2023. She cited the 2020 vandalism of her own office with an antisemitic note, saying "It was a stark reminder that hate festers when we do not confront it directly." She is a member of the Assembly''s bipartisan Jewish caucus despite not being Jewish herself.', 'https://www.amny.com/news/upper-east-side-antisemitism-town-hall-07292025/', '2025-07-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (139, 14, 'Seawright hosted an antisemitism town hall in July 2025 at Lenox Hill Neighborhood House. Panelists discussed the rise in anti-Israel sentiment and emphasized the need for security, education, and strict policy enforcement on college campuses. The event included discussion of Columbia University''s $220 million deal with the Trump administration to address Title VI antisemitism violations.', 'https://www.amny.com/news/upper-east-side-antisemitism-town-hall-07292025/', '2025-07-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (141, 16, 'Alvarez signed the "New York Legislators Stand with Israel" letter dated October 2023, a bipartisan statement by NY state legislators condemning the October 7 Hamas attack as a "despicable sneak attack" and "war crime."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (143, 12, 'Zaccaro attended a "Prayer for Israel" vigil at the Bronx Jewish Center in Pelham Parkway on October 12, 2023, joining nearly 100 residents and elected officials following the October 7 Hamas attacks that killed over 1,200 Israelis.', 'https://www.norwoodnews.org/pelham-parkway-bronx-vigil-held-for-israeli-victims-of-hamas-attacks/', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 5, 'Dinowitz is a sponsor of Assembly Bill A2139, the "Honoring Our Pledge to Eliminate Antisemitism (HOPE) Act," which requires state agencies and courts to use the IHRA definition of antisemitism when investigating or deciding violations of anti-discrimination laws.', 'https://www.nysenate.gov/legislation/bills/2025/A2139/amendment/A', '2025-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 12, 'Dinowitz denounced the DSA''s pro-Palestinian rally on Oct. 8, 2023, writing "NYC-DSA is holding a rally in solidarity with the Palestinian people Sunday, on Simchas Torah, and the day after the Iranian-backed Hamas launched its attacks on Israeli civilians... It seems NYC-DSA is happy hundreds of Israelis have been viciously murdered. This is a sickening display of antisemitism."', 'https://www.norwoodnews.org/update-dinowitz-hochul-others-denounce-rally-in-support-of-palestinians-following-terrorist-attack-on-israel/', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 12, 'Dinowitz wrote in an Oct. 8 email that "Israel not only has a right to defend itself but must respond in the most substantial possible way against these barbaric attacks without regard to proportionality."', 'https://www.riverdalepress.com/stories/defending-pro-israel-stance,132408', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 14, 'Dinowitz attended a vigil for Israel at Bell Tower Monument on West 239th Street in Fieldston on October 8, 2023, organized by Bronx Jewish clergy, joining hundreds of Bronx residents and elected officials.', 'https://www.norwoodnews.org/update-dinowitz-hochul-others-denounce-rally-in-support-of-palestinians-following-terrorist-attack-on-israel/', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 14, 'Dinowitz spoke at a Riverdale rally on October 24, 2023, stating "We have got to stand up, stand tall and stand together in support of Israel, especially now and more than ever. We have to demand the release of hostages now."', 'https://www.riverdalepress.com/stories/dinowitzes-release-hostages,129176', '2023-10-24');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 14, 'Dinowitz joined Jewish leaders and Senate Majority Leader Chuck Schumer at a Times Square rally demanding the release of all hostages held by Hamas in Gaza following the Oct. 7 attack.', 'https://www.riverdalepress.com/stories/dinowitzes-release-hostages,129176', '2023-10-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 14, 'Dinowitz attended an Oct. 7 anniversary vigil at SAR Academy in Riverdale, joining Bronx leaders to call for unity, an end to hate, and the return of remaining hostages.', 'https://www.bxtimes.com/bronx-leaders-call-for-unity-end-to-hate-and-return-of-hostages-on-anniversary-of-oct-7-terror-attacks/', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (144, 16, 'Dinowitz was among 25 pro-Israel Assembly members who signed an open letter led by Assemblymembers Daniel Rosenthal and Nily Rozic opposing Mamdani''s "Not on Our Dime" bill (A6943), calling it "a ploy to demonize Jewish charities with connections to Israel."', 'https://www.queensjewishlink.com/index.php/local/79-community-corner/shabsie-saphirstein/8639-rosenthal-and-rozic-lead-pushback-against-leftist-bill-targeting-jewish-orgs', '2023-05-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (146, 16, 'Heastie as Assembly Speaker called Mamdani''s "Not on Our Dime" bill (A6943), which would have blocked nonprofits from funding Israeli settlements, a "non-starter" and prevented it from advancing in the Assembly.', 'https://www.jta.org/2025/11/03/politics/what-to-know-about-not-on-our-dime-zohran-mamdanis-bill-targeting-donations-to-israeli-settlements', '2023-05-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (146, 13, 'Heastie as Assembly Speaker torpedoed a bipartisan bill to commemorate October 7 as a day of remembrance in New York State, stacking a committee with allies to ensure the bill would not reach the Assembly floor for a vote. He was accused of "veiled antisemitism" by critics.', 'https://www.yahoo.com/news/ny-assembly-dems-accused-veiled-235242323.html', '2025-06-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (147, 12, 'Septimo issued a strong condemnation after Oct. 7, stating "We''ve watched indiscriminate, brutal violence unleashed on innocent civilians... there is absolutely no justification for Hamas'' attacks. Narratives that work to paint Hamas as an underdog organization carrying out acts of retribution are deeply misinformed, and incredibly dangerous."', 'https://jewishinsider.com/2025/12/amanda-septimo-ritchie-torres-primary-zohran-mamdani-ally/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (147, 14, 'Septimo visited Israel in 2016 on a trip sponsored by the AIPAC-affiliated American Israel Education Foundation, praising the country in social media posts and appearing in a group photo with Israeli Prime Minister Benjamin Netanyahu.', 'https://jewishinsider.com/2025/12/amanda-septimo-ritchie-torres-primary-zohran-mamdani-ally/', '2016-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (147, 14, 'Septimo repeatedly met with pro-Israel advocates and attended AIPAC events as recently as late 2023, per Jewish Insider reporting.', 'https://jewishinsider.com/2025/12/amanda-septimo-ritchie-torres-primary-zohran-mamdani-ally/', '2023-12-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (147, 16, 'Septimo publicly opposed the "Not on Our Dime" bill (A6943), tweeting "The Jewish community makes New York better, and the state''s relationship with Israel makes New York stronger" and calling the bill a "disturbing effort to bring the delegitimization of Israel to the halls of power in New York."', 'https://x.com/AmandaSeptimo/status/1659232546968817664', '2023-05-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (151, 12, 'Paulin issued a statement on October 10, 2023: "These last few days have been like living a nightmare. The kidnappings and brutal murders that have and continue to happen in Israel have wounded all of us." She added: "I stand firmly behind Israel and feel strongly that Israel must defend itself and prevail." She noted having family in Israel and relatives called up to fight.', 'https://assembly.state.ny.us/mem/Amy-Paulin/story/107680', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (151, 12, 'Paulin posted on X on August 7, 2024: "It''s been 10 months since October 7th, when Hamas terrorists infiltrated Israel, slaughtering and kidnapping thousands. It has been 306 painful days since families lost their children, siblings, parents, grandparents. It has been 10 months too long. We must bring them home now."', 'https://x.com/AmyPaulin/status/1821259540270366847', '2024-08-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (151, 12, 'Paulin issued a statement on the one-year anniversary of October 7, 2024: "We have spent a year mourning October 7. There are still 101 captives, and we don''t know if they are dead or alive." She called antisemitism "now fully awake" and "an existential threat," and stated: "When someone says they are anti-Zionist but not anti-Jewish, their words are false."', 'https://scarsdale10583.com/section-table/98-on-the-market/11132-assemblywoman-amy-paulin-on-the-one-year-anniversary-of-the-october-7-massacre', '2024-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (151, 14, 'Paulin travelled to Israel in late November/early December 2023 with Westchester County Executive George Latimer and other elected officials on a solidarity mission organized by the Westchester Jewish Council. The group met with Israeli President Isaac Herzog, visited Kibbutz Kfar Aza, and met with survivors, first responders, and IDF members. Paulin described the trip as "incredibly serious and devastatingly sad."', 'https://scarsdale10583.com/section-table/277-pet-of-the-week/10595-paulin-and-latimer-travel-to-israel', '2023-12-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (151, 6, 'Paulin issued a statement on April 14, 2024 after Iran''s attack on Israel: "I stand with Israel and pray that America continues to stand unequivocally with Israel as it confronts and responds to Iran''s attack." She thanked "American, British and Jordanian governments and pilots who served to protect Israel" and called Iran''s attack "a reckless and irresponsible escalation of war."', 'https://yonkerstimes.com/assemblywoman-amy-paulins-statement-regarding-irans-attack-on-israel/', '2024-04-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (151, 16, 'Paulin signed the "New York Legislators Stand with Israel" letter dated October 20, 2023, a bipartisan statement by NY state legislators calling the Hamas attack "a war crime" and "a cruel, barbaric and brutal throwback to primitive times," and pledging to "continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (151, 5, 'Paulin is a cosponsor of Assembly Bill A2139, the "Honoring Our Pledge to Eliminate Antisemitism (HOPE) Act," which requires state agencies and courts to use the IHRA definition of antisemitism when investigating or deciding whether there has been a violation of anti-discrimination laws.', 'https://www.nysenate.gov/legislation/bills/2025/A2139/amendment/A', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (153, 11, 'Sayegh issued a statement on the Middle East conflict (circa October 2023) calling for "an immediate ceasefire," stating: "The conflict which has raged on for nearly 75 years needs to be resolved diplomatically not militarily." He emphasized that "Innocent people on both sides of the conflict are harmed and killed" and called on "The United Nations and especially the Government of the United States" to adopt "a fair and even-handed approach."', 'https://myemail.constantcontact.com/Assemblyman-Nader-Sayegh-Statement--Middle-East-Conflict.html?soid=1132313915492&aid=QlGlPCFtNhY', '2023-10-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (154, 12, 'Otis spoke at the Larchmont-Mamaroneck Tri-Municipal Vigil on October 12, 2023, characterizing Hamas as "the terrorist group" with the goal to "eliminate the state of Israel and to kill, terrorize, and torture." He stated: "If we believe that America aspires to human happiness and toleration, then we know today that Israel''s battle against Hamas is our battle as well."', 'https://assembly.state.ny.us/mem/Steven-Otis/story/107779', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (154, 14, 'Otis attended a solidarity vigil for Israel at Harbor Island Park in Mamaroneck on October 12, 2023, joining hundreds of community members, County Executive George Latimer, and NYS Senator Shelley Mayer. Officials stressed the Jewish community "does not stand alone."', 'https://patch.com/new-york/larchmont/sorrow-anger-resolve-3-communities-come-together-israel', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (155, 12, 'Shimsky condemned Hamas'' attack on Israel, mourned the loss, injury, and capture of innocent lives, supported U.S. government efforts to work toward peace, and called for standing with Israel in the aftermath of the attack', 'https://shimsky4assembly.com/new-page', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (155, 12, 'Shimsky acknowledged that in the weeks since October 7th, evidence emerged that widespread, horrific acts of rape and sexual violence were systematically perpetrated by Hamas attackers against Israeli women and girls during the assault', 'https://shimsky4assembly.com/new-page', '2023-12-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (155, 5, 'Shimsky partnered with Assembly Members Amy Paulin, Chris Burdick, Dana Levenberg, Steve Otis, Gary Pretlow, and Nader Sayegh to secure $100,000 from New York State for the Holocaust & Human Rights Education Center (HHREC) in White Plains', 'https://hhrecny.org/assemblywoman-amy-paulin-westchester-legislators-secure-1m-for-the-holocaust-and-human-rights-education-center-in-white-plains/', '2024-06-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (156, 5, 'Burdick led the Town of Bedford in passing a resolution against Anti-Semitism during his time as Bedford Town Supervisor', 'https://www.burdickforassembly.com/about', '2020-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (156, 5, 'Burdick partnered with Assembly Members Amy Paulin, MaryJane Shimsky, Dana Levenberg, and others to secure $100,000 from New York State for the Holocaust & Human Rights Education Center (HHREC) in White Plains', 'https://hhrecny.org/assemblywoman-amy-paulin-westchester-legislators-secure-1m-for-the-holocaust-and-human-rights-education-center-in-white-plains/', '2024-06-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (157, 12, 'Slater stated "we as a country and a state need to stand shoulder to shoulder with the country of Israel" and "we have to defeat these dangerous terrorists who want to bring harm, destruction, and death to freedom loving countries all around the world"', 'https://assembly.state.ny.us/mem/Matt-Slater/story/108032', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (157, 14, 'Slater participated in a press conference organized by the New York Chapter of "Run for Their Lives" to demand the release of 134 hostages held in Gaza, stating he continues to "stand shoulder to shoulder with our Jewish brothers and sisters"', 'https://nyassembly.gov/mem/Matt-Slater/story/109875', '2024-04-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (157, 5, 'Slater co-sponsored the Dismantling Student Anti-Semitism (DSA) Act requiring compulsory antisemitism training at NY state colleges and annual reporting on combating hate; the bill was blocked by Assembly Democrats', 'https://news.halstonmedia.com/categories/press-releases/articles/slater-s-antisemitism-bill-blocked-by-assembly-democrats', '2025-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (157, 5, 'Slater co-introduced the Combating Campus Antisemitism Act (A.4772) applying to tuition assistance programs and designed to address antisemitic activities on college campuses', 'https://www.nysenate.gov/legislation/bills/2025/A4772', '2025-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (157, 14, 'Slater joined Congressman Mike Lawler and former New Castle Supervisor Lisa Katz of the Combat Antisemitism Movement to host a roundtable focused on tackling the rising tide of antisemitism', 'https://x.com/RepMikeLawler/status/1834981569565475047', '2024-09-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (157, 5, 'Slater joined Congressman Mike Lawler and State Senator Rob Rolison in urging NYSED Commissioner to remove Carmel school trustee Jim Wise for antisemitic rhetoric including spreading "From the River to the Sea" and equating Israel with terrorist organizations', 'https://www.slaterforny.com/post/hudson-valley-lawmakers-call-for-removal-of-carmel-school-trustee-jim-wise-for-antisemitism-rhetoric', '2024-07-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (158, 12, 'Levenberg stated "There are no words to describe the devastation and anguish wrought by Hamas''s attack on Israel" and "Nothing justifies violence against civilians, and all people deserve to live without fear of unprovoked violence." As a child of Holocaust survivors, she noted the attacks evoke "strong memories of our recent history"', 'https://nyassembly.gov/mem/Dana-Levenberg/story/107777', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (158, 12, 'Levenberg affirmed that "Israel has a right and a duty to defend itself, and I hope Israel can make wise decisions that minimize civilian casualties amid the growing conflict"', 'https://nyassembly.gov/mem/Dana-Levenberg/story/107777', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (158, 5, 'Levenberg partnered with Assembly Members Amy Paulin, Chris Burdick, MaryJane Shimsky, and others to secure $100,000 from New York State for the Holocaust & Human Rights Education Center (HHREC) in White Plains', 'https://hhrecny.org/assemblywoman-amy-paulin-westchester-legislators-secure-1m-for-the-holocaust-and-human-rights-education-center-in-white-plains/', '2024-06-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (158, 5, 'Levenberg, as a Jewish elected official, publicly condemned antisemitic actions including Elon Musk''s apparent Nazi salutes and his promotion of the antisemitic "Great Replacement" theory', 'https://assembly.state.ny.us/mem/Dana-Levenberg/story/112827', '2025-01-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (159, 14, 'Carroll attended the Rockland County chapter of Agudath Israel of America''s legislative meet and greet at the Paramount Country Club in New City, connecting with approximately 150 members of the Rockland Jewish community on issues including combating antisemitism', 'https://agudah.org/agudath-israel-rockland-legislative-meet-and-greet-enables-community-members-elected-officials-to-connect-on-a-personal-level', '2025-12-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (160, 5, 'Wieder, as a Rockland County Legislator, co-sponsored a resolution addressing campus anti-Israel protests, noting that "civil discourse has transformed into something much uglier" on college campuses', 'https://patch.com/new-york/newcity/rockland-lawmakers-pass-resolution-campus-anti-israel-protests', '2024-05-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (160, 5, 'Wieder publicly confronted an antisemite at a press conference in Rockland County, telling the individual "All Nazis are dead by now, so you are not a Nazi but an anti-Semite" after the person approached him aggressively', 'https://www.theyeshivaworld.com/news/general/1780128/watch-it-rockland-county-legislator-aron-wieder-confronts-anti-semite-to-his-face.html', '2019-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (160, 14, 'Wieder attended the Agudath Israel of America Rockland legislative meet and greet, praising the organization and connecting with the Orthodox Jewish community on issues including security funding and combating antisemitism', 'https://agudah.org/agudath-israel-rockland-legislative-meet-and-greet-enables-community-members-elected-officials-to-connect-on-a-personal-level', '2025-12-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (160, 14, 'Wieder studied at rabbinical college in Israel after graduating from Machzikei Hadas Yeshiva, and has been a prominent Orthodox Jewish leader in Rockland County for over 30 years representing its large Hasidic population', 'https://nyassembly.gov/mem/Aron-Wieder', '2025-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (161, 12, 'Brabenec stated "Let''s not mince words: Israel and her people are under siege from an army of terrorists that are hellbent on removing Jewish people from the face of the earth. It is the responsibility of every person to stand in solidarity with the people of Israel and denounce Hamas'' acts of terror"', 'https://nyassembly.gov/mem/Karl-Brabenec/story/107693', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (161, 5, 'Brabenec participated in a press conference at Newburgh City Hall with other local leaders and faith leaders to speak and stand against antisemitic actions after posters with aggressive antisemitic rhetoric were posted on telephone poles in the city', 'https://www.nysenate.gov/newsroom/in-the-news/2023/james-skoufis/local-leaders-denounce-antisemitism', '2023-08-31');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (162, 16, 'Eachus signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, which condemned the October 7 attack as a "war crime" and declared "We will continue to stand with Israel"', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (162, 12, 'Eachus co-signed the "New York Legislators Stand with Israel" letter which called the October 7 attack "a despicable sneak attack against the Israeli people" and "a cruel, barbaric and brutal throwback to primitive times," condemning the taking of hostages, murder of civilians, and use of torture', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (165, 12, 'Tague issued a statement on the Israel-Palestine peace agreement praising the release of hostages, calling it "a monumental victory for peace and humanity" and stating "my prayers are with the families who have suffered since the tragic events of October 7, 2023," referencing Hamas abducting 251 people and the "unimaginable horrors" endured by hostages', 'https://assembly.state.ny.us/mem/Chris-Tague/story/115572', '2025-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (166, 4, 'Shrestha cosponsored the "Not on Our Dime!: Ending New York Funding of Israeli Settler Violence Act" (A6943), introduced by Assemblymember Zohran Mamdani, which would prohibit not-for-profit corporations from engaging in unauthorized support of Israeli settlement activity in the occupied territories', 'https://www.nysenate.gov/legislation/bills/2023/A6943', '2023-05-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (166, 11, 'Shrestha was "one of the first to call for a ceasefire in 2023" regarding Israel''s war in Gaza, and "firmly sided with protesters even when it was not politically expedient to do so," according to City & State NY profile', 'https://www.cityandstateny.com/personality/2025/07/sarahana-shrestha-building-progressive-movement-hudson-valley/406845/', '2023-10-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (166, 9, 'Shrestha co-signed the "Socialists in Office Stand in Solidarity with Student Encampments for a Free Palestine" statement in April 2024, which declared signers were "moved watching students exercise their protected rights to freedom of speech and assembly in a united call for an end to the ongoing genocide in Gaza"', 'https://www.nysenate.gov/newsroom/press-releases/2024/jabari-brisport/socialists-office-stand-solidarity-student-encampments', '2024-04-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (166, 15, 'Shrestha spoke at a rally in Kingston on March 7, 2026, a national day of action against the U.S.-Israel war with Iran, joining approximately 200 Hudson Valley residents at Academy Green Park alongside speakers from MHVDSA Palestinian Liberation and Jewish Voice for Peace', 'https://oracle.newpaltz.edu/no-war-in-iran-kingston-rally/', '2026-03-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (166, 13, 'Shrestha did not condemn the October 7 Hamas attack; instead, the DSA chapter she co-chairs posted "In Solidarity with the Palestinian people and their right to resist 75 years of occupation and apartheid," and she criticized Gov. Hochul''s pro-Israel response, tweeting "The Governor has no empathy for her Palestinian constituents. Instead, she effectively calls for more deaths and war crimes"', 'https://x.com/sarahana/status/1712554662002671863', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (167, 16, 'Jacobson signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, which condemned the October 7 attack as a "war crime" and declared "We will continue to stand with Israel"', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (167, 12, 'Jacobson co-signed the "New York Legislators Stand with Israel" letter which called the October 7 attack "a despicable sneak attack against the Israeli people" and "a cruel, barbaric and brutal throwback to primitive times," condemning the taking of hostages, murder of civilians, and use of torture', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (167, 5, 'Jacobson attended a press conference at Newburgh City Hall in August 2023 alongside Sen. Skoufis, Sen. Rolison, and faith leaders to denounce antisemitic posters found on telephone poles, stating "Hate speech is wrong" and "There is simply no excuse for what has recently happened here, and what is happening elsewhere in this country"', 'https://www.nysenate.gov/newsroom/in-the-news/2023/james-skoufis/local-leaders-denounce-antisemitism', '2023-08-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (168, 14, 'Beephan attended the JNS International Policy Summit in Jerusalem on April 28, 2025, as the only U.S. state legislator present, stating "New York is home to the largest Jewish community outside of Israel. It''s important to ensure their voice is represented in government"', 'https://www.jns.org/ny-assemblyman-stands-with-jewish-community-at-jns-summit/', '2025-04-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (168, 12, 'Beephan has worked with the Jewish Federation in Dutchess County since the October 7 attack, stating "It''s key for us to support each other, because if we don''t stand up for Jews, and vice versa, we never know who they might come for next" and calling pro-Palestinian protests "unfortunate"', 'https://www.jns.org/ny-assemblyman-stands-with-jewish-community-at-jns-summit/', '2025-04-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (168, 5, 'Beephan co-signed a letter with Congressman Lawler, Sen. Rolison, and Assemblyman Slater to NYSED Commissioner Rosa calling for removal of Carmel school trustee Jim Wise for defending the slogan "from the river to the sea," which the letter called "antisemitic rhetoric" requiring "zero tolerance"', 'https://www.slaterforny.com/post/hudson-valley-lawmakers-call-for-removal-of-carmel-school-trustee-jim-wise-for-antisemitism-rhetoric', '2024-08-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (169, 14, 'Barrett was endorsed by the Solidarity PAC, a pro-Israel political action committee launched by the New York Solidarity Network that explicitly backs state-level candidates who "value the American alliance with Israel." Barrett was listed on the PAC''s website as one of nine inaugural endorsed candidates for the 2024 Democratic primary.', 'https://www.nysolidaritypac.org/didi-barrett', '2024-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (169, 14, 'Barrett received financial support from the Solidarity PAC, which channeled at least $300,000 total to its endorsed candidates in the 2024 cycle. The PAC was described as "the first committee to explicitly back New York state-level candidates" on a pro-Israel platform. Barrett won her primary 57% to 42% against WFP-endorsed challenger Claire Cousin.', 'https://nysfocus.com/2024/06/06/new-york-elections-israel-donations', '2024-06-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (170, 12, 'Bendett issued a statement on October 11, 2023 titled "Devastating Attack on The State of Israel By Hamas Will Not Be Tolerated," condemning "the horrific acts of terrorism committed by Hamas against the State of Israel." He stated he was "deeply troubled by these attacks" and that "Israel...deserves to exist without being terrorized." He identified himself as a member of the Jewish community.', 'https://nyassembly.gov/mem/Scott-Bendett/story/107752', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (170, 16, 'Bendett declared "I stand with Israel in solidarity and unwavering support during this tumultuous time" in his October 11, 2023 official statement. He called Israel "one of the U.S.'' strongest allies" and offered condolences to families affected by the Hamas attacks.', 'https://nyassembly.gov/mem/Scott-Bendett/story/107752', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (172, 11, 'Romero co-sponsored (with Councilor Sergio Adams) an Albany Common Council resolution calling for "an immediate and permanent ceasefire to allow more humanitarian aid to flow into Gaza." She read the resolution aloud before the vote, stating: "this document is a ceasefire document, that this document is supporting peace and that this document is trying to end the war and end the violence ceasefire now." The resolution passed 10-2 on January 4, 2024, while she served on the Albany Common Council (6th Ward) prior to joining the Assembly.', 'https://www.wamc.org/news/2024-01-05/gaza-ceasefire-resolution-passed-in-albany', '2024-01-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (172, 5, 'Romero sponsored Assembly bill A.7614, legislation to provide for a memorial for the victims of the Holocaust and to educate the public about the history of the Holocaust and the dangers of antisemitism, racism, and all manifestations of intolerance. She spoke on the Assembly floor about the bill on June 16, 2025.', 'https://nyassembly.gov/mem/Gabriella-A-Romero/video/26854/', '2025-06-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (176, 12, 'Woerner joined Saratoga Springs Mayor Ron Kim and Public Safety Commissioner James Montagnino in condemning a DSA pro-Hamas rally held in New York City approximately 24 hours after the October 7 Hamas attack. The joint statement read: "We condemn, without reservation, the horrific attack waged by Hamas and supported by Iran, in which hundreds of innocent Israelis (and others, including several Americans) were murdered. Scores of innocent people, including many children, were taken hostage, and thousands were wounded."', 'https://www.movingsaratogaforward.com/post/woerner-kim-montagnino-condemn-dsa-pro-hamas-rally', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (176, 16, 'Woerner signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, organized by Assemblymember Charles D. Lavine. The letter called the Hamas attack "a despicable sneak attack against the Israeli people" and "a war crime," condemned "the wholesale murder of civilians, the use of torture, the beating, mutilation and killing of captured soldiers," and declared "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (177, 12, 'Simpson issued a statement on November 9, 2023 titled "Simpson Stands in Solidarity with Israel," joining legislative colleagues in condemning Hamas attacks. He stated: "We stand strong in our support for Israel, not just in foreign affairs but here at home as well. By uniting to condemn the violence unleashed on innocent Israelis, we send a clear message that we will stand in the way of hate here and abroad." He emphasized remaining "unwavering in our commitment to combating hate, bigotry and discrimination."', 'https://nyassembly.gov/mem/Matthew-Simpson/story/107973', '2023-11-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (177, 16, 'Simpson signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, organized by Assemblymember Charles D. Lavine. The letter called the Hamas attack "a war crime" and declared "We will continue to stand with Israel." Simpson also co-signed a separate letter from state legislators underlining their "commitment to this message of unity" with Israel.', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (177, 6, 'Simpson applauded President Trump''s brokered Israel-Palestine peace agreement on October 7, 2025, stating: "I commend the president for his pursuit of peace in the Middle East. This agreement could only have been achieved through the kind of strong leadership that prioritizes security and a relentless pursuit of stability." He added: "My thoughts and prayers remain with the families on both sides who have suffered unimaginable loss."', 'https://nyassembly.gov/mem/Matthew-Simpson/story/115553', '2025-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (179, 16, 'Gray signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, organized by Assemblymember Charles D. Lavine. The letter stated: "As we stand in solidarity with the Jewish state, we must confront the profound question of whether a free, liberal, and democratic nation can defeat a culture founded on tyranny. The answer is clear — we will win, the good people will win, as long as we stand together and united."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (179, 12, 'Gray attended a Capitol press conference on May 31, 2023 opposing the "Not On Our Dime!" bill (A.6943, Mamdani), which would penalize non-profit entities affiliated with Israel. Gray stated: "It was my pleasure to stand with my colleague and friend, Ari Brown, to say no to this anti-Israel, anti-Semitic bill which is highly offensive and discriminatory to all of our Jewish friends in the state of New York." He argued the bill would "penalize not-for-profit businesses and organizations for simply exercising their freedom of association and expression."', 'https://assembly.state.ny.us/mem/Scott-Gray/story/106347', '2023-06-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (181, 12, 'Smullen issued a statement on October 7, 2023 titled "Smullen Reacts to Attack on the State of Israel," condemning "the unprovoked and abhorrent attack on the state of Israel by Hamas" as "a reminder that terrorists will stop at nothing in their efforts to humiliate and destroy a peaceful partner in a large global alliance." As a retired Marine Corps colonel with three combat tours in Afghanistan, he noted having close personal connections to individuals in the region.', 'https://assembly.state.ny.us/mem/Robert-Smullen/press/5', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (181, 6, 'Smullen issued a statement on June 23, 2025 supporting U.S. strikes against Iran''s nuclear weapons infrastructure, stating: "America must never allow the Iranian regime — the world''s leading state sponsor of terrorism — to obtain a nuclear weapon." He called the strikes "a necessary measure to protect not just our homeland, but our allies and partners across the globe" and concluded: "Peace through strength isn''t just a slogan — it''s a strategy built on deterrence and the credible will to act."', 'https://assembly.state.ny.us/mem/Robert-Smullen/story/114539', '2025-06-23');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (182, 12, 'Buttenschon responded to the October 7, 2023 Hamas attacks on Israel in a statement reported by WKTV, saying: "As we have witnessed the horrific terrorist attacks on Israel over the weekend," she extended "sincere condolences to the families" and called for "God''s blessings on the military, first responders, families, and loved ones as they face continuing danger," asking people to keep them "in their thoughts and prayers."', 'https://www.wktv.com/news/local/mohawk-valley-representatives-respond-to-attacks-on-israel/article_aec9a068-66aa-11ee-87b0-f7d4a1460dcd.html', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (193, 12, 'Manktelow signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, which called the Hamas attack "a war crime" and "a cruel, barbaric and brutal throwback to primitive times," condemned the taking of hostages, murder of civilians, torture, and mutilation, and pledged "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (193, 16, 'Manktelow signed the bipartisan "New York Legislators Stand with Israel" letter organized by Assemblymember Charles D. Lavine, president of the NY chapter of the National Association of Jewish Legislators, which was signed by dozens of Assembly members and Senators condemning Hamas and standing in solidarity with Israel.', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (194, 12, 'Gallahan signed the bipartisan "New York Legislators Stand with Israel" letter dated October 20, 2023, which called the Hamas attack "a war crime" and "a cruel, barbaric and brutal throwback to primitive times," condemned the taking of hostages, murder of civilians, torture, and mutilation, and pledged "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (194, 16, 'Gallahan signed the bipartisan "New York Legislators Stand with Israel" letter organized by Assemblymember Charles D. Lavine, president of the NY chapter of the National Association of Jewish Legislators, which was signed by dozens of Assembly members and Senators condemning Hamas and standing in solidarity with Israel.', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (194, 12, 'Gallahan attended a bipartisan press conference in Albany on April 2, 2024, calling for release of 134 hostages held by Hamas in Gaza, stating: "It is despicable to see the terrorist group Hamas continue to hold these 134 hostages—two of which are New York citizens—prisoner in Gaza. These individuals and their families deserve peace and justice." He concluded: "We must work together to mobilize, make a difference and bring them home now."', 'https://nyassembly.gov/mem/Jeff-Gallahan/story/109892', '2024-04-03');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (71, 16, 'Fitzpatrick signed the October 20, 2023 "New York Legislators Stand with Israel" letter organized by Assemblymember Charles Lavine, which called the Hamas attack "a war crime" and stated "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (71, 5, 'Fitzpatrick cosponsored NY Assembly Bill A8284, the "Stop Anti-Semitism on College Campuses Act," which would ensure no state aid is granted to any college or university that authorizes, facilitates, or supports events promoting antisemitism on campus.', 'https://www.nysenate.gov/legislation/bills/2023/A8284', '2023-11-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (71, 12, 'Fitzpatrick signed the bipartisan "New York Legislators Stand with Israel" letter which described the October 7 attack as "a despicable sneak attack" and "a war crime," condemning "the taking of hostages, the wholesale murder of civilians, the use of torture, the beating, mutilation and killing of captured soldiers."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (72, 5, 'Durso cosponsored NY Assembly Bill A8284, the "Stop Anti-Semitism on College Campuses Act," which would ensure no state aid is granted to any college or university that authorizes, facilitates, or supports events promoting antisemitism on campus.', 'https://www.nysenate.gov/legislation/bills/2023/A8284', '2023-11-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (72, 5, 'Durso cosponsored the reintroduced "Stop Anti-Semitism on College Campuses Act" (A4797) in the 2025-2026 legislative session, continuing his support for measures addressing antisemitism on college campuses.', 'https://www.nysenate.gov/legislation/bills/2025/A4797', '2025-02-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (73, 12, 'Stern released a statement on October 8, 2023: "I most strongly condemn the horrific and unprovoked attacks, murder and taking of Israeli civilians by Hamas on the morning of Simchat Torah, a day of religious celebration." He affirmed Israel''s right to defend itself.', 'https://nyassembly.gov/mem/Steve-Stern/story/107660', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (73, 16, 'Stern signed the October 20, 2023 "New York Legislators Stand with Israel" letter organized by Assemblymember Charles Lavine, which called the Hamas attack "a war crime" and declared "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (73, 5, 'Stern cosponsored NY Assembly Bill A8284, the "Stop Anti-Semitism on College Campuses Act," which would ensure no state aid is granted to any college or university that authorizes, facilitates, or supports events promoting antisemitism on campus.', 'https://www.nysenate.gov/legislation/bills/2023/A8284', '2023-11-27');
