INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (75, 12, 'Brown released a statement on the one-year anniversary of October 7 declaring "These horrific attacks on a U.S. ally threaten not only the State of Israel but also Jewish-American citizens around the world" and calling Hamas and Iran''s actions "heinous, nothing short of crimes against humanity."', 'https://nyassembly.gov/mem/Keith-P-Brown/story/112197', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (75, 16, 'Brown signed the October 20, 2023 "New York Legislators Stand with Israel" letter organized by Assemblymember Charles Lavine, which called the Hamas attack "a war crime" and stated "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (75, 14, 'Brown joined Assembly Minority Conference colleagues and community members at a press conference in Albany on April 2, 2024, calling for the immediate release of 134 hostages held by Hamas in Gaza, specifically highlighting the cases of American citizens Omer Neutra and Edan Alexander.', 'https://nyassembly.gov/mem/Keith-P-Brown/story/112197', '2024-04-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (75, 5, 'Brown cosponsored NY Assembly Bill A8284, the "Stop Anti-Semitism on College Campuses Act," which would ensure no state aid is granted to any college or university that authorizes, facilitates, or supports events promoting antisemitism on campus.', 'https://www.nysenate.gov/legislation/bills/2023/A8284', '2023-11-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (76, 16, 'Lavine organized and authored the October 20, 2023 "New York Legislators Stand with Israel" letter, signed by dozens of Assembly members and Senators, which called the Hamas attack "a war crime" and declared "We will continue to stand with Israel." As president of the NY chapter of the National Association of Jewish Legislators, Lavine led this bipartisan effort.', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (76, 12, 'Lavine''s October 20, 2023 solidarity letter described the attack as "The despicable sneak attack against the Israeli people is a war crime. The taking of hostages, the wholesale murder of civilians, the use of torture, the beating, mutilation and killing of captured soldiers and the parading of their bodies and the bodies of dead civilians through the streets of Gaza is a cruel, barbaric and brutal throwback to primitive times."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (76, 12, 'Lavine issued a statement on October 7, 2024 marking one year since the attack: "One year after Hamas terrorists carried out a horrific unprovoked attack, the deadliest on Jews since the Holocaust, we stand united with Israel as it fights for its very survival." He noted more than 1,100 were murdered and highlighted hostage Omer Neutra from his district.', 'https://patch.com/new-york/glencove/lavine-statement-marking-one-year-oct-7-attack-israel', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (76, 14, 'Lavine, as president of the New York Chapter of the National Association of Jewish Legislators, has hosted Israeli government officials and has marched in the Salute to Israel Parade in commemoration of Israel''s Independence Day.', 'https://nyassembly.gov/mem/Charles-D-Lavine/bio/', NULL);
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (77, 12, 'McDonough released a statement on October 11, 2023: "The ongoing attack on Israel by the terrorist organization Hamas is appalling, Israel is our closest ally in the Middle East and has the absolute right to both exist and defend itself against these barbaric actions." He noted his meetings with Holocaust survivors and stated "I am proud to say I stand with Israel and all our Jewish neighbors across New York."', 'https://assembly.state.ny.us/mem/David-G-McDonough/story/107698', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (77, 16, 'McDonough signed the October 20, 2023 "New York Legislators Stand with Israel" letter organized by Assemblymember Charles Lavine, which called the Hamas attack "a war crime" and stated "We will continue to stand with Israel."', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (77, 5, 'McDonough cosponsored NY Assembly Bill A8284, the "Stop Anti-Semitism on College Campuses Act," which would ensure no state aid is granted to any college or university that authorizes, facilitates, or supports events promoting antisemitism on campus.', 'https://www.nysenate.gov/legislation/bills/2023/A8284', '2023-11-27');
