VALUES (78, 16, 'Blumencranz signed the bipartisan "New York Legislators Stand With Israel" solidarity letter dated October 20, 2023, which called the Hamas attack "a war crime" and declared "We will continue to stand with Israel"', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (78, 5, 'Blumencranz authored a Fox News op-ed calling for combating antisemitism in schools, stating "Jewish students across New York are under siege" and introduced the "United Against Hate Act" featuring a "New York Stands with Israel" license plate and a statewide high school art competition about antisemitism', 'https://www.foxnews.com/opinion/stop-talking-start-teaching-new-york-must-fight-end-antisemitism-our-schools', '2025-02-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (78, 12, 'Blumencranz spoke out against statements made about Israel and Jews during pro-Palestine protests, stating Hamas has "a really sophisticated PR machine" and expressed concern about "false or half-truth information" changing the narrative on social media', 'https://www.liherald.com/stories/jewish-elected-officials-speak-out-on-rise-of-antisemitism,201562', '2024-06-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (78, 14, 'Blumencranz stood alongside the family of Omer Neutra at the 500 Days in Hell Rally in Central Park, calling his murder "a painful reminder of the horrors endured by those still held captive" by Hamas', 'https://x.com/BlumencranzJake/status/1893869346406982061', '2025-03-21');
