VALUES (78, 14, 'Blumencranz joined Assemblyman Ari Brown and fellow legislators in welcoming Israeli Consul General Ofir Akunis to the New York State Capitol', 'https://assembly.state.ny.us/mem/Ari-Brown/story/114332', '2025-06-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (79, 12, 'Norber, an IDF veteran who was in a bomb shelter with his family during the October 7 attacks, stated "It was the worst atrocity to Jews since the Holocaust. Israel is not the same anymore" and ran for office motivated by post-Oct 7 antisemitism in the US', 'https://www.algemeiner.com/2024/11/11/ex-idf-soldier-becomes-first-republican-50-years-win-new-york-state-assembly-seat-long-island-district/', '2024-11-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (79, 14, 'Norber served as a staff sergeant in the IDF military police after being drafted at age 17, was raised in Israel, and stated "I saw what happened in Israel. I''ll do whatever I can to prevent that from happening here"', 'https://www.jfeed.com/news-israel/sms526', '2024-11-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (79, 5, 'Norber co-sponsored bill A.5448, a bipartisan measure requiring colleges and universities to appoint a Title VI coordinator to address antisemitism and discrimination', 'https://ballotpedia.org/Daniel_Norber', '2025-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (80, 6, 'Mikulin stated he is "outraged by the Iranian regime''s attacks on the State of Israel" and asserted "these senseless acts of violence on the State of Israel are also a direct assault on Jewish-Americans and will not be tolerated"', 'https://nyassembly.gov/mem/John-K-Mikulin/press/', '2024-04-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (80, 5, 'Mikulin supports the Combating Campus Anti-Semitism Act (A.8399/S.7752) which would prohibit granting tuition assistance awards to students who knowingly engage in promoting antisemitism at New York colleges and universities', 'https://www.assembly.ny.gov/mem/John-K-Mikulin/newsroom/', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (82, 5, 'Ra introduced the Dismantling Student Antisemitism Act (DSA Act, A.2376) requiring colleges to implement antisemitism training and annual reporting, stating "It''s been frustrating to see such blatant antisemitism unroll across our state, especially in places that are supposed to be dedicated to education"', 'https://nyassembly.gov/mem/Edward-P-Ra/story/108031', '2024-01-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (82, 5, 'Ra co-introduced legislation with Sen. Canzoneri-Fitzpatrick to withhold state aid from higher education institutions that fail to report antisemitism, stating "New Yorkers deserve a state free of antisemitism, and our students deserve a college experience free of threats"', 'https://www.nysenate.gov/newsroom/press-releases/2023/patricia-canzoneri-fitzpatrick/senator-canzoneri-fitzpatrick-and', '2023-12-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (83, 16, 'Brown signed the bipartisan "New York Legislators Stand With Israel" solidarity letter dated October 20, 2023, which called the Hamas attack "a war crime" and declared "We will continue to stand with Israel"', 'https://assembly.state.ny.us/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (83, 12, 'Brown called the ceasefire between Israel and Hamas "nothing more than a temporary and dangerous illusion" and stated "terrorist groups like Hamas have never honored a ceasefire for long"', 'https://www.5tjt.com/assemblyman-ari-brown-calls-out-dangerous-illusion-of-ceasefire-between-israel-and-hamas/', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (83, 14, 'Brown welcomed Israeli Consul General Ofir Akunis to the New York State Capitol, presenting an official Assembly Proclamation and stating "New York''s support for Israel is unwavering"', 'https://assembly.state.ny.us/mem/Ari-Brown/story/114332', '2025-06-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (83, 5, 'Brown condemned an antisemitic Department of Health billboard in the Five Towns Jewish community, writing "Antisemitism should not be a fact of Jewish life, something that we or anyone should simply accept as a way of life" and vowed "I will fight anti-Semitism and will not be silent"', 'https://assembly.state.ny.us/mem/Ari-Brown/story/106735', '2022-09-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (83, 5, 'Brown supports the Combating Campus Anti-Semitism Act (A.8399/S.7752) and proposed legislation to deny state funding for students who purposely engage in antisemitic behavior at New York colleges', 'https://www.liherald.com/stories/new-york-lawmakers-propose-bill-denying-state-funding-for-antisemitic-behavior-on-campuses,207876', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (83, 14, 'Brown hosted a press conference with Congressman Lee Zeldin at Cedarhurst Village Hall to address antisemitic flyers found in mailboxes around Cedarhurst, Oceanside and Long Beach, stating "Antisemitism will not stand in our community. There is no place in our state for hate crimes, period"', 'https://5townscentral.com/2022/08/17/ari-brown-lee-zeldin-to-hold-press-conference-addressing-growing-crime-antisemitism/', '2022-08-23');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (83, 14, 'Brown grilled NYC Mayor Zohran Mamdani during Albany budget hearings over his revocation of the IHRA definition of antisemitism and his refusal to condemn "Globalize the intifada," with the exchange growing so heated it was shut down by Democratic leadership', 'https://www.jta.org/2026/02/12/ny/mamdani-headed-to-albany-for-questions-about-his-budget-he-got-grilled-on-antisemitism', '2026-02-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (84, 5, 'Griffin condemned antisemitic flyers found in Rockville Centre in her district, calling the material "hateful garbage" and stating she was "incensed and disgusted" that residents had to discover such material on their lawns', 'https://www.nysenate.gov/newsroom/in-the-news/2022/anna-m-kaplan/officials-condemn-antisemitic-flyers-found-rockville-centre', '2022-07-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (85, 5, 'Solages co-introduced legislation with State Sen. Anna Kaplan banning display of hate symbols including swastikas and neo-Nazi imagery on public property, explicitly intended to protect communities from antisemitism; signed into law by Governor Hochul in November 2021', 'https://www.governor.ny.gov/news/governor-hochul-signs-legislation-prohibiting-municipal-corporations-selling-or-displaying', '2021-11-03');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (86, 14, 'Pheffer Amato joined a high-level solidarity delegation trip to Israel in December 2023, meeting with Knesset members, speaking with October 7th survivors, and visiting the devastated Kibbutz Kfar Aza near the Gaza border, stating "I had to take this opportunity to learn and see firsthand the atrocities that occurred on October 7th"', 'https://www.qgazette.com/articles/pheffer-amato-joins-delegation-solidarity-trip-to-israel/', '2023-12-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (86, 12, 'Pheffer Amato described the October 7th attack aftermath after visiting Kibbutz Kfar Aza stating "The stories I was told were heartbreaking. The atrocities of that day and what everyone went through is unfathomable" and "This was a community that believed in peace...I was now standing there and it was in complete shambles"', 'https://www.nyassembly.gov/mem/Stacey-Pheffer-Amato/story/108989', '2024-01-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (86, 14, 'Pheffer Amato confronted pro-Palestinian protesters at a SUNY achievement celebration on February 10, 2025 by chanting "Am Yisrael Chai" as a self-described "proud Zionist," stating "I could not be silent and let anti-Semitic individuals have control of the room. New York and Israel have an unbreakable bond"', 'https://assembly.state.ny.us/mem/Stacey-Pheffer-Amato/story/113918', '2025-02-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (86, 5, 'Pheffer Amato received the "Fighting Hate and Discrimination Award" at the 2024 Met Council on Jewish Poverty''s Annual Legislative Breakfast, recognized as "the leading advocate for the Jewish community in the State Legislature" having secured $105 million for school security and elevated 20 crimes to hate crime eligibility', 'https://nyassembly.gov/mem/Stacey-Pheffer-Amato/story/110711', '2024-06-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (86, 6, 'Pheffer Amato cosponsored the HOPE Act (A2139) which codifies the IHRA definition of antisemitism into New York State law, requiring all state agencies to use the definition when investigating discriminatory acts', 'https://www.nysenate.gov/legislation/bills/2025/A2139/amendment/A', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (86, 16, 'Pheffer Amato displays hostage posters outside her Capitol office and wore a "Bring Them Home" necklace received during her solidarity mission to Israel in the immediate aftermath of the October 7th terrorist attack', 'https://nyassembly.gov/mem/Stacey-Pheffer-Amato/story/110711', '2024-06-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (87, 2, 'Weprin praised Governor Cuomo''s 2016 Executive Order to divest public funds from BDS supporters, stating "The BDS movement seeks to de-legitimize Israel" and uses "underhanded tactics" and "rhetoric that aims to isolate Israel from its allies and the greater global community"', 'https://assembly.state.ny.us/mem/David-I-Weprin/story/70618', '2016-06-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (87, 14, 'Weprin applauded President Trump''s recognition of Jerusalem as Israel''s capital, stating "Jerusalem is the official home of the Israeli government...Today''s announcement is a testament to the special bond between Israel, the only democracy in the Middle East, and the United States"', 'https://politicsny.com/2017/12/08/queens-officials-support-trumps-change-jerusalem-israels-capital/', '2017-12-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (87, 12, 'Weprin condemned the antisemitic riot at Hillcrest High School in November 2023 where hundreds of students targeted a Jewish teacher for attending a pro-Israel rally, calling it "an utter disgrace" and stating "A Jewish educator was targeted for her religious identity. This is unacceptable and we will never tolerate hate in Queens"', 'https://qns.com/2023/12/weprin-antisemitism-schools-hillcrest/', '2023-12-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (87, 1, 'Weprin sent a joint letter with Assemblymember Lavine to SUNY Chancellor King demanding withdrawal of a SUNY Binghamton student association BDS resolution, citing New York State Executive Order 157 and calling the resolution illegal, stating "I''d like to have the chancellor tell the student association that there are consequences for calling for what would be an illegal action"', 'https://www.amny.com/news/queens-lawmaker-suny-binghamton-antisemitism/', '2024-04-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (87, 6, 'Weprin cosponsored the HOPE Act (A2139) which codifies the IHRA definition of antisemitism into New York State law, requiring all state agencies to use the definition when investigating discriminatory acts', 'https://www.nysenate.gov/legislation/bills/2025/A2139/amendment/A', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (88, 12, 'Rozic, the first Israeli-born member of the NY State Legislature, condemned Hamas on October 10, 2023, stating "If you murder civilians and children in cold blood, you do not get to claim the moral high ground" and "I really can''t get over the mental gymnastics that it must take in order to justify supporting or standing by Hamas"', 'https://nystateofpolitics.com/state-of-politics/new-york/news/2023/10/10/israeli-assembly-member-nily-rozic-speaks-out-against-hamas-attacks', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (88, 16, 'Rozic unveiled a "KIDNAPPED" poster display at her Queens district office on October 31, 2023 highlighting over 230 hostages taken by Hamas, stating "This should not be controversial: every single hostage must be released"', 'https://nyassembly.gov/mem/Nily-Rozic/story/107856', '2023-10-31');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (88, 14, 'Rozic co-hosted the "New York Stands With Israel" conference at the State Capitol in March 2016 with StandWithUs featuring Palestinian BDS critic Bassem Eid, stating "As lawmakers, we have an opportunity to speak out against the BDS movement and any attempt to delegitimize Israel as a sovereign, democratic and Jewish state"', 'https://assembly.state.ny.us/mem/Nily-Rozic/story/69386', '2016-03-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (88, 2, 'Rozic sponsored a legislative resolution in the Assembly honoring 70 years of Israeli Independence which was adopted and presented to the Consulate General of Israel in New York, and signed a resolution condemning the BDS movement', 'https://assembly.state.ny.us/mem/Nily-Rozic/story/80933', '2018-04-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (88, 12, 'Rozic condemned pro-Hamas protesters near a Queens synagogue in January 2026, stating "Instead of marching for the democratic revolution unfolding in Iran, hate mongers chose a predominantly Jewish neighborhood to cheer support for Hamas — a radical genocidal death cult" and called for others to "have moral clarity & forcefully denounce this antisemitism"', 'https://www.qchron.com/editions/north/synagogue-protest-roundly-condemned/article_6a617000-b3f8-46ce-95aa-f73a59cb4634.html', '2026-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (88, 6, 'Rozic cosponsored the HOPE Act (A2139) which codifies the IHRA definition of antisemitism into New York State law, requiring all state agencies to use the definition when investigating discriminatory acts', 'https://www.nysenate.gov/legislation/bills/2025/A2139/amendment/A', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (88, 14, 'Rozic marked the one-year anniversary of the October 7 Hamas attack on Israel on Capital Tonight, advocating for hostage release as "a loud advocate for hostages and their families, including two New Yorkers"', 'https://nystateofpolitics.com/state-of-politics/new-york/politics/2024/10/07/nily-rozic-marks-1-year-since-hamas-attack-on-israel', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (89, 14, 'Braunstein joined Assemblywoman Nily Rozic and Israel in New York to meet with families of hostages taken during the October 7th attack by Hamas in December 2023', 'https://nyassembly.gov/mem/Edward-C-Braunstein/media/', '2023-12-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (89, 5, 'Braunstein and Senator John C. Liu hosted a virtual Anti-Asian and Anti-Semitic Hate Crimes & Bias Conversation addressing the concerning rise in violence against the AAPI and Jewish community', 'https://nyassembly.gov/mem/Edward-C-Braunstein/press/3', '2021-05-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (89, 14, 'Braunstein attended JCRC-NY''s Annual Israel Day on Fifth event in May 2025, standing with other elected officials in support of the State of Israel and the New York Jewish community, at an event that welcomed Israeli citizens previously held hostage in Gaza', 'https://www.jcrcny.org/news-post/793473/', '2025-05-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (90, 5, 'Berger introduced the HOPE Act (A2139) to codify the IHRA definition of antisemitism into New York State law, stating "This legislation sends a strong, clear message: New York will not tolerate antisemitism" and "New York must do more. With the largest Jewish population outside Israel, we have a moral obligation to lead the fight against antisemitism"', 'https://qns.com/2024/12/assembly-member-sam-berger-bill-to-codify-antisemitism-new-york/', '2024-12-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (90, 12, 'Berger published an op-ed "Standing with Israel" calling the October 7 attacks "heinous terrorist attacks by Hamas" and wrote "Israel isn''t just defending its territory; it''s defending its very existence, its people, its heritage" while referencing his grandmother as a Holocaust survivor who fought in the IDF', 'https://qns.com/2023/10/op-ed-standing-with-israel/', '2023-10-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (90, 16, 'Berger created a dedicated "Israel Donation Resources" page on his campaign website listing organizations to support including Friends of the IDF, Michael Levin Lone Soldier Center, Israel Association of Community Centers, and IsraAID', 'https://www.sambergerforassembly.com/israel-emergency-resources', '2023-10-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (90, 12, 'Berger condemned pro-Hamas protesters near a Queens synagogue in January 2026, stating "What occurred was not peaceful protest. Chants such as ''we support Hamas'' and calls to ''globalize the intifada'' are not political critique, they are explicit endorsements of violence and terror" and called it "antisemitic harassment, plain and simple"', 'https://www.qchron.com/editions/north/synagogue-protest-roundly-condemned/article_6a617000-b3f8-46ce-95aa-f73a59cb4634.html', '2026-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (90, 14, 'Berger spent four years studying in Israel at Yeshiva Bircas HaTorah in the Old City of Jerusalem before entering politics, demonstrating deep personal ties to Israel', 'https://aish.com/assemblymember-sam-berger-making-a-difference-through-politics/', '2024-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (91, 16, 'Hevesi signed the "New York Legislators Stand with Israel" letter in October 2023 which stated "The despicable sneak attack against the Israeli people is a war crime" and expressed solidarity with Israel as "a free, liberal, and democratic nation"', 'https://nyassembly.gov/write/upload/member_files/013/pdfs/20231030_0107834.pdf', '2023-10-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (91, 5, 'Hevesi partnered with Senator Gianaris to lead a letter signed by over 80 state legislators calling on Governor Hochul to double Nonpublic School Safety Equipment funding from $45M to $90M in response to escalating hate against Jewish and Muslim communities after October 7, resulting in a $70 million allocation', 'https://www.nysenate.gov/newsroom/press-releases/2023/michael-gianaris/senate-deputy-leader-gianaris-assembly-member-hevesi', '2023-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (91, 12, 'Hevesi stated "The attack on Israel on October 7th and the events that have unfolded since, both internationally and domestically, require that we use every available resource to protect Jewish and Muslim communities that have been faced with an increased threat of attacks and extremist hate-crimes"', 'https://www.nysenate.gov/newsroom/press-releases/2023/michael-gianaris/senate-deputy-leader-gianaris-assembly-member-hevesi', '2023-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (91, 6, 'Hevesi cosponsored the HOPE Act (A2139) which codifies the IHRA definition of antisemitism into New York State law, requiring all state agencies to use the definition when investigating discriminatory acts', 'https://www.nysenate.gov/legislation/bills/2025/A2139/amendment/A', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (91, 14, 'Hevesi attended JCRC-NY''s Annual Israel Day on Fifth event in May 2025 as part of a group of elected officials standing with the State of Israel and the New York Jewish community', 'https://www.jcrcny.org/news-post/793473/', '2025-05-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (92, 11, 'Hyndman stated "Yes" when asked if she supports an immediate ceasefire in the Middle East, adding "but I support Israel''s right to defend itself" in her Jim Owles Liberal Democratic Club candidate questionnaire', 'https://jimowles.org/news/candidate-answers-to-joldc-alicia-l-hyndman-for-ny-assembly-district-29', '2024-03-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (92, 5, 'Hyndman attended a solidarity event at Ohel Chabad-Lubavitch in Cambria Heights condemning anti-Semitic attacks, stating "There is something terribly wrong in the world when we see a growing hate in our communities and do not combat it with justice and action"', 'https://qns.com/2020/01/queens-lawmakers-stand-in-solidarity-condemning-spate-of-anti-semitic-attacks/', '2020-01-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (94, 11, 'Anderson called for a ceasefire on Feb. 27, 2024, writing on X: "We are approaching nearly 150 days of conflict. There has to be a pathway towards peace in this moment."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-02-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (96, 5, 'Vanel attended a solidarity event at Ohel Chabad-Lubavitch in Cambria Heights condemning anti-Semitic attacks, stating "With all the anti-Semitic attacks on the Jewish community, we must stand in solidarity with our brothers and sisters to address the root causes of hatred and bigotry"', 'https://qns.com/2020/01/queens-lawmakers-stand-in-solidarity-condemning-spate-of-anti-semitic-attacks/', '2020-01-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (96, 16, 'Vanel was one of seven Queens Assembly members who signed a joint letter with 66 total Assemblymembers opposing the "Not on Our Dime" anti-settlement bill, calling it "a ploy to demonize Jewish charities with connections to Israel" that was "only introduced to antagonize pro-Israel New Yorkers"', 'https://qns.com/2024/05/western-queens-lawmakers-advocate-for-gaza-cease-fire-criticize-israeli-government/', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (97, 11, 'Gonzalez-Rojas called for a ceasefire on Oct. 10, 2023, writing on X: "I mourn the loss of Israeli & Palestinian civilian lives caused by decades of conflict & hope for a ceasefire & peace between the nations." Three days later she specifically implored federal officials to call for a ceasefire in Gaza', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (97, 13, 'Gonzalez-Rojas equivocated on October 7 by framing the attack as part of "decades of conflict" and mourning "Israeli & Palestinian civilian lives" equally without specifically condemning Hamas or the October 7 attack itself', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (97, 8, 'Gonzalez-Rojas called for DNC to give Palestinian a speaking slot, stating "I fully support the Uncommitted movement''s call for a Palestinian to speak on the stage of the DNC" and "all voices should be heard in our collective goal to secure a ceasefire and prevent further deaths"', 'https://www.cityandstateny.com/politics/2024/08/ny-elected-officials-call-dnc-give-speaking-slot-palestinian/399015/', '2024-08-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (99, 11, 'Moreno was arrested on October 20, 2023 at an anti-Israel rally in New York City demanding a ceasefire, posting on Instagram: "Last night I was arrested alongside 100+ New Yorkers demanding the bare f**king minimum: Ceasefire NOW!"', 'https://canarymission.org/individual/Diana_Moreno', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (99, 15, 'Moreno joined hundreds of New Yorkers in support of Columbia University students'' pro-Palestinian encampment in April 2024, posting on Instagram: "Joined hundreds of New Yorkers in support of @sjp.columbia students facing repression for standing up for Palestine...Solidarity Forever"', 'https://canarymission.org/individual/Diana_Moreno', '2024-04-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (99, 15, 'Moreno participated in the anti-Israel encampment at NYU on April 30, 2024, holding a sign that read "PREGNANT MAMA FOR A FREE PALESTINE"', 'https://canarymission.org/individual/Diana_Moreno', '2024-04-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (99, 9, 'Moreno stated "I got pregnant one month after the genocide in Gaza started. My relationship to motherhood cannot be divorced from witnessing the world dehumanize children in Palestine," using the term genocide to describe Israel''s actions in Gaza', 'https://jacobin.com/2026/02/moreno-queens-special-election-mamdani', '2026-02-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (99, 8, 'Moreno supports the Not on Our Dime Act, which would allow the state attorney general to strip charities of nonprofit status if they facilitate illegal occupations in the West Bank or war crimes in Gaza, stating it is about "not giving our tax dollars to nonprofits that are displacing Palestinians"', 'https://socialists.nyc/press-releases/democratic-socialist-diana-moreno-wins-special-election-in-assembly-district-36-to-succeed-mayor-mamdani/', '2026-02-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (100, 11, 'Valdez began calling for a ceasefire almost immediately after Israel launched an assault on Gaza in retaliation for Hamas'' attacks on October 7, 2023, and was among the first to call for a ceasefire', 'https://www.cityandstateny.com/politics/2026/03/pro-palestinian-pal-pac-endorses-claire-valdez-congress/412325/', '2023-10-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (100, 9, 'Valdez was among the first to call Israel''s actions in Gaza a genocide, labeling them as such on October 19, 2023, before Israel''s ground counter-offensive in Gaza had begun', 'https://www.jns.org/anti-israel-activist-introduces-congressional-candidate-at-nyc-event/', '2023-10-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (100, 8, 'Valdez supports the Boycott, Divestment and Sanctions movement against Israel and has called for the U.S. to cut off all military aid to Israel', 'https://jacobin.com/2026/01/claire-valdez-union-organizing-congress', '2026-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (100, 8, 'Valdez is a co-sponsor of the Not on Our Dime bill, legislation that would allow the state attorney general''s office to strip charities of their nonprofit status if they facilitate illegal occupations in the West Bank or war crimes in Gaza', 'https://www.cityandstateny.com/politics/2026/03/pro-palestinian-pal-pac-endorses-claire-valdez-congress/412325/', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (100, 15, 'Valdez was arrested outside U.S. Senators Chuck Schumer and Kirsten Gillibrand''s offices while protesting Israel''s military actions in Gaza, stating "Israel is starving two million people in Gaza with the full backing of the United States government"', 'https://www.yahoo.com/news/articles/nyc-lawmakers-arrested-pro-palestine-184200431.html', '2025-08-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (100, 9, 'Valdez stated at the protest: "I''m here because it''s unconscionable for anyone to stand by while a genocide is perpetrated on innocent people. We''re seeing a human-made famine unfold in Gaza that we''ve been warning about for years and months now"', 'https://www.newsweek.com/protesters-arrested-chuck-schumer-kirsten-gillibrand-offices-gaza-2107782', '2025-08-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (101, 14, 'Rajkumar marched in the 2025 Israel Day Parade on Fifth Avenue, standing in solidarity with thousands of Jewish New Yorkers as the parade called for the release of hostages held by Hamas', 'https://www.instagram.com/reel/DJz7PcgSdk3/', '2025-05-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (101, 5, 'Rajkumar was commended by the Rabbinical Alliance of America (RAA) for her "courage and leadership" in standing up against antisemitism, with Rabbi Mendy Mirocznik urging her government colleagues to follow her example', 'https://rabbinicalalliance.org/2024/08/19/raa-commends-assembly-member-jenifer-rajkumar/', '2024-08-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (101, 5, 'Rajkumar condemned the anti-Israel protest targeting Borough Park, tweeting: "I condemn the hate-fueled event targeting the largely Orthodox Jewish neighborhood of Borough Park. These protestors are deliberately singling out for harassment one of the largest Jewish communities in the world. This must stop"', 'https://x.com/JeniferRajkumar/status/1891965979963412894', '2025-02-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (101, 16, 'Rajkumar was among 66 Assembly members who signed a joint letter opposing the "Not on Our Dime" bill, calling it a ploy to "demonize Jewish charities with connections to Israel"', 'https://qns.com/2024/05/western-queens-lawmakers-advocate-for-gaza-cease-fire-criticize-israeli-government/', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (101, 6, 'Rajkumar visited Israel as part of a New York State delegation and advocated for US military aid to Israel in the face of attacks from Iran', 'https://www.queensjewishlink.com/index.php/local/26-community-corner/12709-assemblymember-jenifer-rajkumar-makes-kgh-campaign-stop-as-she-runs-for-public-advocate', '2025-04-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (101, 14, 'Rajkumar received the endorsement of Zioness Action Fund for her Public Advocate campaign, which cited her as "leading the fight against hate crimes across the city -- including anti-Jewish hate"', 'https://zionessaction.org/2025-nyc-democratic-primary-endorsements/', '2025-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (102, 11, 'Cruz released a statement on Instagram calling for an immediate ceasefire, stating: "We must call for an immediate ceasefire -- the cessation of violence, the immediate surge of unrestricted humanitarian aid, the release of hostages, and a true road to peace for both the Palestinian and Israeli people"', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-04-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 12, 'Yeger spoke at a pro-Israel rally in October 2023, stating: "For us this is the most important thing...standing up for what''s right, standing up for the Jewish people, standing up for people who did nothing and are facing the most heinous acts of barbarism that we haven''t seen in centuries"', 'https://vinnews.com/2023/10/19/watch-local-frum-nyc-politicians-express-support-for-israel-at-recent-rally/', '2023-10-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 14, 'Yeger took the floor of the NYC Council to denounce ceasefire advocates as the "Congressional Hamas Squad," recited the Mi Shebeirach prayer for the IDF in an historic first on any U.S. legislative floor, and stated there would not be another Holocaust because Jewish people are now protected by a defense force', 'https://www.theyeshivaworld.com/news/israel-news/2233817/epic-nyc-councilman-kalman-yeger-takes-on-the-congressional-hamas-squad-in-floor-remarks.html', '2023-10-23');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 12, 'Yeger tweeted "Palestine does not exist" in March 2019 and was unapologetic, stating at a press conference: "There is no state by that name. There is no place by that name. That''s a fact. I didn''t make it up, I didn''t invent it." He was removed from the City Council Immigration Committee but refused to retract', 'https://forward.com/fast-forward/421749/kalman-yeger-palestine-does-not-exist-tweet-protests-in-brooklyn/', '2019-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 5, 'Yeger co-sponsored Assembly Bill A2139A, the HOPE Act (Honoring Our Pledge to Eliminate Anti-Semitism), requiring state agencies and courts to use the IHRA definition of antisemitism when investigating discriminatory acts', 'https://www.nysenate.gov/legislation/bills/2025/A2139/amendment/A', '2025-01-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 1, 'Yeger criticized the BDS movement, stating: "The lies and propaganda being promulgated by the BDS movement have to be addressed and they have to be challenged" and questioning why BDS targets only Israel and not Cuba, Saudi Arabia, or Iran', 'https://www.cityandstateny.com/politics/2019/04/where-new-york-democrats-stand-on-israel/177469/', '2019-04-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 14, 'Yeger called for police presence to protect Borough Park''s Orthodox Jewish community from an anti-Israel protest, and opposed the NYC Council ceasefire resolution, stating that "a good number of members think this resolution is a very bad idea"', 'https://jewishinsider.com/2024/06/new-york-city-council-ceasefire-resolution-israel-gaza-hamas/', '2024-06-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 12, 'Yeger was among Mamdani''s most outspoken critics, calling his anti-Israel positions "terrifying" and warning that Mamdani''s "inability to get his brain around the notion that globalizing the intifada is a bad thing is terrifying," while criticizing NYC divestment from Israel Bonds as antisemitic', 'https://jewishinsider.com/2025/09/zohran-mamdani-jewish-leaders-new-york-city-mayoral-election/', '2025-09-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (104, 14, 'Yeger sarcastically mocked NYC Council members who wore "Ceasefire Now" t-shirts to a session, noting they had "never worn sweatshirts with ''Ceasefire'' at any time when Hamas was raining daily missiles on Israel or any time in their 22 months that they served on this council prior to October 7"', 'https://worldisraelnews.com/anti-israel-nyc-council-members-ripped-for-ceasefire-now-shirts/', '2023-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (105, 12, 'Bichotte Hermelyn condemned the October 7 attack, calling it "an inhumane terrorist attack that killed some 1,200 people, mostly civilians" and stating "Hamas'' atrocious assault on innocent civilians during one of the holiest Jewish holidays was an act of cowardice"', 'https://www.caribbeanlife.com/caribbean-pols-mark-first-anniversary-of-oct-7-attack-on-israel/', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (105, 14, 'Bichotte Hermelyn spoke at the "South Brooklyn Stands With Israel" rally at Holocaust Memorial Park in Sheepshead Bay on May 19, 2024, stating: "This 76th Independence Day of Israel is markedly somber, with our communities reeling from the most deadly attack on the Jewish people since the Holocaust"', 'https://brooklyneagle.com/articles/2024/05/22/political-leadership-in-south-brooklyn-standing-with-israel/', '2024-05-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (105, 16, 'Bichotte Hermelyn stated her "unwavering support to the Jewish people in their homeland and their right to self-defense" and called for the "unconditional release" of hostages, noting "we must continue to combat rising anti-Semitic hate crimes"', 'https://www.caribbeanlife.com/caribbean-pols-mark-first-anniversary-of-oct-7-attack-on-israel/', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (105, 14, 'Bichotte Hermelyn traveled to Israel in 2011, visiting Holy Sites and Yad Vashem Holocaust Museum, and successfully advocated for Yad Vashem to add an exhibit commemorating Haiti''s role in saving Jewish people fleeing the Holocaust', 'https://en.wikipedia.org/wiki/Rodneyse_Bichotte_Hermelyn', '2011-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (105, 5, 'Bichotte Hermelyn observed International Holocaust Remembrance Day and called for continued efforts to combat rising antisemitic hate crimes, noting that New York houses the largest Jewish population outside of Israel', 'https://www.caribbeanlife.com/bichotte-hermelyn-observes-international-holocaust-remembrance-day/', '2025-01-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (106, 12, 'Cunningham signed the "We Stand With Israel" letter published by Tablet Magazine on October 12, 2023, expressing "the strongest condemnation possible of the evil actions of Hamas" and standing "in unity in strong condemnation" of the October 7 attacks. He was listed as Assembly District 43, Flatbush/Crown Heights.', 'https://www.tabletmag.com/sections/israel-middle-east/articles/standing-with-israel', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (106, 16, 'Cunningham was a signatory to the "We Stand With Israel" open letter organized by Tablet Magazine in October 2023, which declared solidarity with Israel and the Jewish people following the October 7 Hamas attacks.', 'https://www.tabletmag.com/sections/israel-middle-east/articles/standing-with-israel', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (106, 1, 'Cunningham withdrew his endorsement of congressional candidate Yuh-Line Niou in July 2022 after she declared support for BDS, stating: "I will not support a candidate that fails to recognize our democratic ally''s right to exist." The Rabbinical Alliance of America commended his "staunch support of Israel and vehement opposition to the Boycott Divestment and Sanctions movement."', 'https://forward.com/fast-forward/509962/ny-lawmaker-withdraws-endorsement-from-congressional-candidate-yuhline-bds-israel/', '2022-07-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (107, 11, 'Carroll added his name to a January 2024 letter from Jewish Voice for Peace Action calling for an immediate and permanent ceasefire in Gaza. He was listed among New York elected officials calling for a ceasefire by City & State New York in their March 2024 tracker.', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (108, 12, 'Novakhov issued an official statement condemning the October 7 attacks: "Over the last few weeks, we have seen the absolute worst of humanity on display as militants from the terrorist group Hamas have inflicted pain, terror and death upon the people of Israel." He later stated: "It''s been six months since the barbaric terrorist group Hamas attacked innocent men, women and children in Israel."', 'https://assembly.state.ny.us/mem/Michael-Novakhov/story/109939', '2023-10-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (108, 14, 'Novakhov hosted one of the largest pro-Israel rallies in the history of Brooklyn on January 21, 2024 in Brighton Beach. He rallied with Run for Their Lives organizations from across South Brooklyn to call on Hamas to surrender and release the hostages. He expressed disbelief at the antisemitism experienced by Russian Jews in America since the conflict resurged.', 'https://www.brooklynpaper.com/brooklyn-100-days-rally-israeli-hostages/', '2024-01-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (108, 14, 'Novakhov hosted a memorial and vigil on October 5, 2025 to mark the second anniversary of the October 7 terror attacks at Holocaust Memorial Park at West End Avenue in Sheepshead Bay. Attendees included representatives of Chabad, Run for Their Lives, the American Russian-Speaking Jews Alliance, United Zionists, and American Forum for Israel.', 'https://brooklyneagle.com/articles/2025/10/03/oct-7-vigil-being-held-sunday-at-holocaust-memorial-park/', '2025-10-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (109, 14, 'Brook-Krasny attended the Chabad-Lubavitch "Prayer for Israel" rally on Eastern Parkway on October 9, 2023, two days after the Hamas attack. Roughly 2,500 Brooklynites gathered at the vigil to pray for Israel and the victims. An estimated 20,000 people attended the prayer rally outside Chabad world headquarters at 770 Eastern Parkway.', 'https://www.nysenate.gov/newsroom/in-the-news/2023/jessica-scarcella-spanton/everyone-shock-brooklynites-come-together-after', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (109, 14, 'Brook-Krasny spoke at a bipartisan press conference with Israeli Consul General Ofir Akunis at the New York State Capitol to discuss New York''s relationship with Israel and the unprecedented rise in antisemitic activity following the October 7 attacks.', 'https://assembly.state.ny.us/mem/Alec-Brook-Krasny/story/109868', '2024-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (109, 12, 'Brook-Krasny attended a press conference hosted by the New York Chapter of Run for Their Lives to call for the release of hostages held in Gaza since October 7. He stated: "October 7 was a traumatic day for many Jewish New Yorkers and unfortunately many are still hurting in the aftermath."', 'https://www.brooklynpaper.com/coney-islanders-honor-anniversary-oct-7-attack/', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (110, 14, 'Colton was instrumental in organizing a pro-Israel rally on the Brighton Beach Boardwalk in August 2014 that drew thousands. The line of demonstrators stretched from Brighton Fifth Street to Ocean Parkway. Colton stated: "We''re here to speak up for freedom because when freedom is threatened in one part of the world, it is threatened in every part of the world."', 'https://brooklyneagle.com/articles/2014/08/05/support-for-israel-rally-draws-thousands-to-brighton-beach-boardwalk/', '2014-08-05');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (110, 14, 'Colton participated in the "South Brooklyn Stands with Israel" rally at Holocaust Memorial Park in Sheepshead Bay on May 19, 2024. Over 150 people gathered to call for the release of hostages held by Hamas since October 7 and commemorate Israel''s 76 years of independence. Colton memorialized the remains of three Israeli hostages recovered by the Israeli military.', 'https://brooklyneagle.com/articles/2024/05/22/political-leadership-in-south-brooklyn-standing-with-israel/', '2024-05-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (110, 5, 'Colton introduced a bill that increases penalties for vandalizing property with a swastika or burning cross, which passed both the State Assembly and State Senate and was signed by the Governor. The legislation strengthened hate crime protections related to antisemitic vandalism.', 'https://nyassembly.gov/mem/William-Colton', '2020-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (111, 5, 'Eichenstein partnered with Gerstman Schwartz LLP and StandWithUs in January 2022 to launch a legal action initiative to combat antisemitic hate crimes, pursuing civil legal remedies for criminally based antisemitic actions. StandWithUs provided a network of nearly 250 pro bono attorneys for free legal services to victims.', 'https://standwithus.com/news/standwithus-partners-with-nyc-law-firm-state-rep-to-fight-antisemitism/', '2022-01-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (111, 5, 'Eichenstein co-sponsored bipartisan legislation (S.9297) with Senator Jim Tedisco to include aggravated cemetery desecration as a specified offense under New York''s hate crimes law, elevating penalties to up to 7 years for second-degree offenses and 15 years for first-degree offenses. He called cemetery desecration "an especially sinister and cowardly form of hate."', 'https://www.nysenate.gov/newsroom/press-releases/2024/james-tedisco/tedisco-eichenstein-call-new-bipartisan-bill-add', '2024-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (111, 5, 'Eichenstein co-sponsored Assembly Bill A2376 (2025), the "Dismantling Student Antisemitism Act" (DSA act), requiring mandatory sensitivity training on antisemitism at CUNY and SUNY institutions, with reporting requirements regarding antisemitism complaints and disciplinary processes.', 'https://www.nysenate.gov/legislation/bills/2025/A2376', '2025-01-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (111, 12, 'Eichenstein called anti-Israel protesters in Boro Park "Hamas sympathizers" in February 2025, demanding the NYPD and Mayor''s Office take action against a planned protest near an Israel real estate expo. He wrote: "The Hamas sympathizers have decided to ''flood'' our peaceful neighborhood of Boro Park." He also criticized Assemblyman Mamdani for refusing to say whether Hamas should lay down its arms, tweeting: "The mask is off, this was never about ceasefire now."', 'https://vinnews.com/2025/02/16/assemblyman-eichenstein-calls-for-action-against-planned-anti-israel-protest-in-boro-park/', '2025-02-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (111, 14, 'Eichenstein was profoundly involved in defending the Israel real estate expo in Boro Park in February 2025 when pro-Palestinian protesters attempted to disrupt it. After the expo relocated from Lumiere Hall to Brooklyn Square due to threats, fights broke out between pro-Israel and pro-Palestine groups, with arrests made. Eichenstein publicly championed the event and condemned the protesters.', 'https://vinnews.com/2025/02/17/planned-pro-hamas-protest-in-boro-park-prompts-change-of-venue-for-israel-real-estate-expo/', '2025-02-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (112, 12, 'Chang spoke at the COJO Flatbush annual breakfast in May 2025 about his frustrations trying to pass a bill in the Assembly honoring the October 7 assault on Israelis by Hamas terrorists. He remarked that "October 7 lives in our hearts" and wears a yellow ribbon pin in support of hostages and their families, demanding their release from Hamas.', 'https://www.jewishpress.com/sections/community/jewish-community/cojo-flatbush-honors-legislators-israeli-diplomat-and-more/2025/05/08', '2025-05-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (112, 14, 'Chang received the Distinguished Leadership Award at the COJO Flatbush annual breakfast in May 2025, an event that also honored an Israeli diplomat. He spoke to the audience about his efforts to pass an October 7 commemoration bill in the Assembly.', 'https://www.jewishpress.com/sections/community/jewish-community/cojo-flatbush-honors-legislators-israeli-diplomat-and-more/2025/05/08', '2025-05-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (112, 5, 'Chang introduced Assembly Bill A06557, which would enshrine October 7 as a day of commemoration in New York State alongside other recognized days like "Rosa Parks Day" and "Susan B. Anthony Day." He initially submitted a resolution in January which was rejected as "controversial," then converted it to a bill. Despite Democratic co-sponsors, the bill was blocked by Assembly Speaker Carl Heastie.', 'https://www.foxnews.com/politics/ny-lawmaker-lambastes-failed-commemoration-oct-7-attack', '2025-06-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (113, 4, 'Gallagher cosponsored the "Not on Our Dime!: Ending New York Funding of Israeli Settler Violence Act" (A6943) in 2023, alongside Mamdani, Shrestha, Forrest, and Mitaynes, to prohibit not-for-profit corporations from supporting Israeli settlement activity.', 'https://www.nysenate.gov/legislation/bills/2023/A6943/amendment/A', '2023-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (113, 4, 'Gallagher cosponsored the reintroduced "Not on Our Dime!" bill (A6101) in the 2025-2026 session, again alongside Mamdani, Shrestha, Forrest, and Mitaynes.', 'https://www.nysenate.gov/legislation/bills/2025/A6101', '2025-02-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (113, 11, 'Gallagher stated in her 2024 JOLDC questionnaire: "I was one of the first elected officials in New York State to call for [a ceasefire], and have participated in several rallies and actions for peace."', 'https://jimowles.org/news/candidate-answers-to-joldc-emily-gallagher-for-ny-assembly-district-50-2024', '2024-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (113, 15, 'Gallagher was arrested at the Jewish Voice for Peace sit-in at Grand Central Terminal on October 27, 2023, where nearly 400 people were arrested demanding a Gaza ceasefire. She stated: "I am here to represent my constituents...we need a peaceful cease-fire."', 'https://www.amny.com/news/war-israel-grand-central-station-protest-ceasefire/', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (113, 8, 'Gallagher stated in her 2024 JOLDC questionnaire: "The U.S. government should not provide military aid to countries actively carrying out human rights abuses and violations of international law" and that this includes Israel, who should be held to the same standard as Saudi Arabia and Egypt.', 'https://jimowles.org/news/candidate-answers-to-joldc-emily-gallagher-for-ny-assembly-district-50-2024', '2024-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (113, 9, 'Gallagher signed a joint statement with other democratic socialist officials expressing solidarity with student encampments "in a united call for an end to the ongoing genocide in Gaza" and for universities to divest from institutions profiting from genocide.', 'https://www.nysenate.gov/newsroom/press-releases/2024/jabari-brisport/socialists-office-stand-solidarity-student-encampments', '2024-04-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (113, 13, 'Gallagher did not issue an official condemnation of the October 7 Hamas attack. Instead, she reposted a statement on social media and added a quote from historian Howard Zinn: "There is no flag large enough to cover the shame of killing innocent people."', 'https://www.amny.com/news/nyc-dsa-israel-hamas-attack-response/', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 3, 'Mitaynes co-introduced the "Not on Our Dime!: Ending New York Funding of Israeli Settler Violence Act" (A6943) in 2023 with Mamdani and other DSA members, to prohibit not-for-profit corporations from engaging in unauthorized support of Israeli settlement activity.', 'https://www.cityandstateny.com/policy/2023/05/socialist-legislators-back-bill-block-new-york-charities-funding-israeli-settlements/386485/', '2023-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 3, 'Mitaynes co-introduced the reintroduced "Not on Our Dime!" bill (A6101) in the 2025-2026 session, alongside Mamdani, Shrestha, Forrest, and Gallagher.', 'https://www.nysenate.gov/legislation/bills/2025/A6101', '2025-02-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 15, 'Mitaynes was arrested for disorderly conduct on October 13, 2023, while blocking traffic outside Senate Majority Leader Chuck Schumer''s Brooklyn home during a Jewish Voice for Peace rally demanding a ceasefire in Gaza.', 'https://ny1.com/nyc/all-boroughs/news/2023/10/15/two-queens-assemblymembers-charged-with-disorderly-conduct-after-protesting', '2023-10-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 15, 'Mitaynes was arrested in August 2025 while blocking the street in front of Grand Army Plaza near Schumer''s residence, protesting Senators Schumer and Gillibrand''s votes against arms embargo resolutions on Israel.', 'https://peoplesdispatch.org/2025/08/04/pressure-mounts-on-us-politicians-as-democratic-party-voter-base-pushes-to-end-aid-to-israel/', '2025-08-03');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 11, 'Mitaynes signed on to a January 2024 letter from Jewish Voice for Peace Action calling for an immediate and permanent ceasefire, and was among the first NY elected officials to call for a ceasefire following October 7.', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-01-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 9, 'Mitaynes signed a joint statement with other democratic socialist officials expressing solidarity with student encampments "in a united call for an end to the ongoing genocide in Gaza" and calling for universities to divest.', 'https://www.nysenate.gov/newsroom/press-releases/2024/jabari-brisport/socialists-office-stand-solidarity-student-encampments', '2024-04-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 10, 'Mitaynes signed a joint statement with other democratic socialist officials demanding "an immediate and permanent ceasefire in Palestine and an end to Israeli apartheid and occupation."', 'https://www.nysenate.gov/newsroom/press-releases/2024/jabari-brisport/socialists-office-stand-solidarity-student-encampments', '2024-04-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 8, 'Mitaynes was arrested in August 2025 at a protest near Schumer''s residence demanding an arms embargo on Israel, following Senate votes against Bernie Sanders'' resolutions to block $8.8 billion in arms sales to Israel.', 'https://peoplesdispatch.org/2025/08/04/pressure-mounts-on-us-politicians-as-democratic-party-voter-base-pushes-to-end-aid-to-israel/', '2025-08-03');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (114, 13, 'Mitaynes did not issue an official statement condemning the October 7 Hamas attack. As a DSA-affiliated official, her response was notably absent while the NYC-DSA organized a rally the day after the attacks that was widely criticized for antisemitic content.', 'https://www.amny.com/news/nyc-dsa-israel-hamas-attack-response/', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (115, 8, 'Simon stated in her 2024 JOLDC questionnaire: "I feel there should be conditions" on aid to Israel, noting "Israel has to conduct its operations in a manner consistent with international law and its incessant bombing has caused way too many deaths of noncombatants, a disproportionate number of whom were children."', 'https://jimowles.org/news/candidate-answers-to-joldc-jo-anne-simon-for-ny-assembly-district-52-2024', '2024-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (120, 10, 'Souffrant Forrest tweeted: "It is a moral stain on our country and all who live here to have our government and elected officials continue to prop up an Israeli state dedicated to apartheid. We must change that. #BDS #FreePalestine."', 'https://www.jns.org/new-york-lawmaker-draws-fire-over-controversial-tweet-erasing-israel-off-map/', '2021-05-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (120, 10, 'Souffrant Forrest posted a map showing all of Israel labeled as "Palestine" with the caption: "This is a map of historic Palestine. This land has a history of peaceful coexistence. Today, as an @hrw report states, the reality on the ground is apartheid. We need to make sure our tax dollar don''t support the oppression of any peoples." She later deleted the tweet.', 'https://jewishjournal.com/news/336598/ny-state-assemblymember-deletes-tweet-showing-all-of-israel-as-palestine/', '2021-05-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (120, 3, 'Souffrant Forrest co-sponsored the "Not on Our Dime!: Ending New York Funding of Israeli Settler Violence Act" (A6943), introduced by Assemblymember Zohran Mamdani, which sought to prohibit New York nonprofits from funding Israeli settlement activity.', 'https://www.nysenate.gov/legislation/bills/2023/A6943', '2023-05-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (120, 13, 'Souffrant Forrest''s October 11 statement on the Hamas attack avoided naming Hamas: "I am deeply and profoundly saddened by the ongoing conflict in the Middle East. Every life is sacred, every loss is tragic and every person should have the right to live in peace and safety. I unequivocally condemn the killing of all innocent people, whether they are Israeli or Palestinian."', 'https://www.amny.com/news/nyc-dsa-israel-hamas-attack-response/', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (120, 11, 'Souffrant Forrest spoke at an October 20, 2023 pro-Palestine rally in Manhattan, stating: "A ceasefire is not a sign of weakness, but a testament to our strength as leaders and as peacemakers. By calling for a ceasefire, calling to bring the hostages home, calling for aid to be let into Gaza, we demonstrate our commitment to preserving life, promoting justice, and working toward a lasting solution."', 'https://socialists.nyc/press-releases/new-yorkers-demand-ceasefire-in-gaza/', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (120, 15, 'Souffrant Forrest spoke at the October 20, 2023 pro-Palestine rally outside the New York Public Library, organized by NYC-DSA, alongside other DSA legislators including Mamdani, Mitaynes, and Brisport. Over 3,000 attended and 139 were arrested.', 'https://www.ourtownny.com/news/139-arrested-as-thousands-of-palestine-supporters-rally-for-gaza-cease-fire-in-midtown-KY2809936', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (120, 8, 'Souffrant Forrest stated support for BDS in her DSA questionnaire, as confirmed by her predecessor Walter Mosley, and publicly tweeted the #BDS hashtag calling to end U.S. support for Israel.', 'https://jewishinsider.com/2020/07/assemblyman-walter-mosley-discusses-defeat-and-the-dsa-wave-roiling-new-york/', '2020-07-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (124, 14, 'Fall traveled to Israel in February 2020 on a JCRC-NY (Jewish Community Relations Council) sponsored delegation of NY Assembly members. He visited Bethlehem, the borders of Jordan/Syria/Lebanon, and Gaza, and met with Palestinian and Israeli figures. He stated: "I will not and should not have to justify or apologize for my trip and learning experience in Israel" and that "There is far more that unites Muslims, Christians, and Jews than divides us."', 'https://www.middleeasteye.net/news/politician-charles-fall-slammed-israel-visit', '2020-02-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (125, 5, 'Reilly co-signed a joint statement by Assembly Minority Members of the Education Committee condemning antisemitic incidents at Hillcrest High School, stating "there is no place for hatred or division in our public schools" and demanding "swift, significant action" against antisemitism spreading into schools. The statement referenced "rallies supporting terrorism" and "threats against Jewish teachers and students."', 'https://nyassembly.gov/mem/Michael-Reilly/story/108236', '2023-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (126, 5, 'Pirozzolo co-signed a joint statement by Assembly Minority Members of the Education Committee condemning antisemitic incidents at Hillcrest High School, calling for "swift, significant action" and stating that "tolerance of hatred and empty retorts will no longer suffice." He demanded reversing the cancellation of NYPD School Safety Agent academy classes.', 'https://nyassembly.gov/mem/Sam-Pirozzolo/story/108235', '2023-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (214, 11, 'Marte attended a 24-hour press conference/vigil outside City Hall on February 28, 2024 in support of a ceasefire in Gaza, organized by the NYC 4 Ceasefire coalition which included DSA, CAIR-NY, and other pro-Palestine groups', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-02-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (214, 14, 'Marte visited Israel with a program affiliated with the Charles and Lynn Schusterman Family Philanthropies prior to entering office; when the DSA asked candidates to pledge not to visit Israel, Marte declined to say whether he pledged but said "I have a different take on it, just because I''ve been there"', 'https://jewishinsider.com/2021/06/democratic-socialists-of-the-new-york-city-council/', '2021-06-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (215, 8, 'Epstein, as an Assembly member, co-signed an open letter with four other Jewish elected officials (Krueger, Hoylman-Sigal, Lander, Restler) stating "the Israeli government cannot continue the mass destruction of Gaza and the killing of civilians" and calling for prioritizing hostage negotiations, while condemning Hamas for the Oct 7 attack', 'https://www.nysenate.gov/newsroom/articles/2024/liz-krueger/open-letter-jewish-elected-officials-regarding-war-gaza', '2024-02-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (215, 11, 'Epstein co-signed an open letter from Jewish elected officials calling for an end to the war in Gaza, stating Palestinians "have been killed in shocking numbers by indiscriminate, large-scale bombing" and calling the situation "mass destruction," rooted in their "deepest Jewish values"', 'https://www.jns.org/rooted-in-their-deepest-jewish-values-five-nyc-state-officials-accuse-israel-of-mass-destruction/', '2024-02-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (215, 5, 'Epstein serves on the NYC Council Task Force to Combat Antisemitism alongside Brewer, Maloney, Narcisse, and Hanks, led by Vernikov and Dinowitz, and supported the concept of buffer zones around houses of worship, saying "Having perimeters to allow people to go in and out of houses of worship makes a lot of sense"', 'https://www.timesofisrael.com/nyc-council-launches-antisemitism-task-force-new-bill-would-limit-synagogue-protests/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (217, 5, 'Maloney sponsored Introduction 297-A requiring an agency designated by the mayor to provide religious and nonprofit institutions with support in establishing and maintaining emergency plans, as part of Speaker Menin''s antisemitism legislative package; passed 49-1', 'https://www.qchron.com/editions/central/antisemitism-bills-passed-by-council/article_c6cccd13-37fd-4b59-b2c1-548221831255.html', '2026-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (217, 5, 'Maloney serves on the NYC Council Task Force to Combat Antisemitism alongside Epstein, Brewer, Narcisse, and Hanks, a bipartisan body launched in January 2026 to hold hearings on antisemitic hate crimes in protests, schools, higher education, and city agencies', 'https://www.timesofisrael.com/nyc-council-launches-antisemitism-task-force-new-bill-would-limit-synagogue-protests/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (218, 14, 'Menin joined JCRCNY on a solidarity mission to Israel in February 2024 where she visited Kibbutz Kfar Aza, stating "I will never forget the horror and destruction" and praying for the return of hostages Doron and Emily', 'https://x.com/JulieMenin/status/1881050137914663365', '2024-02-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (218, 14, 'Menin marched in the Israel Day Parade on Fifth Avenue in May 2024 to advocate for the release of hostages held by Hamas', 'https://www.jta.org/2025/11/26/politics/jewish-moderate-julie-menin-claims-victory-as-next-city-council-speaker', '2024-05-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (218, 12, 'Menin spoke at a rally of 240 Holocaust survivors for 240 hostages kidnapped by Hamas at the Museum of Jewish Heritage on November 1, 2023, referring to the October 7 attack as "the largest slaughter of Jews since the Holocaust"', 'https://www.jta.org/2025/11/26/politics/jewish-moderate-julie-menin-claims-victory-as-next-city-council-speaker', '2023-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (218, 5, 'Menin as Speaker introduced a five-point plan to combat antisemitism including buffer zone legislation around houses of worship, a dedicated hotline to report antisemitic incidents, $1.25M funding for Museum of Jewish Heritage, and social media education requirements; buffer zone bill passed 44-5 with veto-proof majority', 'https://council.nyc.gov/press/2026/01/16/3060/', '2026-01-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (218, 5, 'Menin sponsored Introduction 1-A, the houses of worship buffer zone bill requiring NYPD to craft plans for managing protests near houses of worship, which passed 44-5 on March 26, 2026 with a veto-proof majority, her first major legislative win as Speaker', 'https://jewishinsider.com/2026/03/new-york-city-council-buffer-zone-mamdani-menin/', '2026-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (218, 16, 'Menin openly criticized Mayor Mamdani''s Day 1 revocation of the IHRA antisemitism definition and cancellation of anti-BDS executive orders, positioning herself as a counterweight to the mayor on Jewish and Israel issues', 'https://forward.com/news/798894/julie-menin-council-mamdani-antisemitism/', '2026-01-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (219, 14, 'Brewer participated in the JCRC-organized solidarity trip to Israel in November 2023, one of thirteen New York City politicians on the all-expenses-paid wartime tour following the October 7 Hamas attack', 'https://www.jfrej.org/news/2023/11/politico-war-time-tour', '2023-11-14');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (219, 14, 'Brewer marched up Fifth Avenue with Council Member Inna Vernikov during the JCRC-NY Celebrate Israel Parade, described as "the world''s largest expression of solidarity with the Jewish state"', 'https://jewishinsider.com/2021/12/gale-brewer-returns-to-the-city-council/', '2023-06-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (219, 1, 'Brewer describes herself as a strong supporter of the Jewish state and explicitly opposes BDS (Boycott, Divestment and Sanctions), stating she "weathered conflicts over Israel" during her previous tenure in the council', 'https://jewishinsider.com/2021/12/gale-brewer-returns-to-the-city-council/', '2021-12-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (219, 5, 'Brewer serves on the NYC Council Task Force to Combat Antisemitism alongside Epstein, Maloney, Narcisse, and Hanks, a bipartisan body launched in January 2026 to probe antisemitism in protests, schools, higher education, and city agencies', 'https://www.timesofisrael.com/nyc-council-launches-antisemitism-task-force-new-bill-would-limit-synagogue-protests/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (220, 12, 'Abreu condemned the tearing down of Israeli hostage posters on the Upper West Side, stating "Many in our community have family in Israel. Many have lost loved ones and know people who have been taken hostage by these terrorists" and "Tearing down posters does nothing but perpetuate hate and breed more chaos"', 'https://www.westsiderag.com/2023/10/25/more-than-a-dozen-israeli-hostage-posters-ripped-down-on-upper-west-side', '2023-10-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (220, 12, 'Abreu posted on X following Iran''s April 2024 missile attack on Israel: "Thinking about all of my neighbors with family in Israel and along the path of the Iranian missiles and grateful that tragedy was averted"', 'https://x.com/ShaunAbreu/status/1779337399484428489', '2024-04-13');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (220, 5, 'Abreu as Council Majority Leader sponsored Introduction 22-A requiring the Department of Education to distribute materials to students about risks of social media including online bullying, harassment, discrimination, and hate; passed 50-0 as part of Speaker Menin''s antisemitism legislative package', 'https://www.qchron.com/editions/central/antisemitism-bills-passed-by-council/article_c6cccd13-37fd-4b59-b2c1-548221831255.html', '2026-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (220, 14, 'Abreu received endorsement and $8,100 in fundraising support from Solidarity PAC, a pro-Israel group launched in 2023 to support candidates who share "deep-rooted American values and pro-Israel beliefs"', 'https://nysfocus.com/2025/03/20/new-york-city-council-mayor-election-israel-palestine', '2025-03-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (222, 11, 'Salaam released a statement on November 20, 2023 — before taking office — calling for a ceasefire: "I join voices in Harlem, New York City & State, congressional representatives...in urging President Biden to do what''s right by calling on the Israeli government for an immediate, durable and sustainable ceasefire."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-11-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (223, 14, 'De La Rosa attended a Yeshiva University assembly on October 12, 2023, where over 1,000 students and faculty gathered in solidarity with Israel following the October 7 attack. She "expressed strong support for Israel and the Jewish community" alongside Manhattan Deputy Borough President Aya Keefe.', 'https://yucommentator.org/2023/10/over-1000-yu-students-and-faculty-members-attend-assembly-in-solidarity-with-israel/', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (223, 11, 'De La Rosa signed on to a Local Progress letter on January 9, 2024 calling for "a durable ceasefire" in Gaza and urging President Biden and Congress to "take immediate action for a durable ceasefire in Israel and Palestine."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-01-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (224, 12, 'Dinowitz issued a statement on October 7, 2023 condemning Hamas, stating Israel "must respond in the most substantial possible way" to attacks. He called a planned NYC-DSA rally in solidarity with Palestinians on Simchas Torah "a sickening display of antisemitism," adding "It seems NYC-DSA is happy hundreds of Israelis have been viciously murdered."', 'https://www.norwoodnews.org/update-dinowitz-hochul-others-denounce-rally-in-support-of-palestinians-following-terrorist-attack-on-israel/', '2023-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (224, 14, 'Dinowitz joined thousands at a Times Square rally on October 19, 2023 demanding the release of all hostages held in Gaza, alongside Senate Majority Leader Chuck Schumer, his father Assemblyman Jeffrey Dinowitz, and Jewish leaders.', 'https://www.riverdalepress.com/stories/dinowitzes-release-hostages,129176', '2023-10-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (224, 14, 'Dinowitz attended a pro-Israel rally at Seton Park on October 24, 2023, drawing approximately 1,000 students and staff from the SAR Academy community along with elected officials including Assemblyman Jeffrey Dinowitz and Bronx Borough President Vanessa Gibson.', 'https://www.riverdalepress.com/stories/students-community-back-israel-rep-ritchie-torres,129863', '2023-10-24');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (224, 14, 'Dinowitz spoke at a June 15, 2024 community vigil at the Riverdale Monument in solidarity with Israel, alongside U.S. Rep. Ritchie Torres and Bronx Borough President Vanessa Gibson. He stated: "This is a question for each and every one of us and every level of governance. And it is worth asking every elected official and every community leader: Where do your morals guide you?"', 'https://www.riverdalepress.com/stories/torres-dinowitz-gibson-gather-in-support-of-israel,187064', '2024-06-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (224, 5, 'Dinowitz co-chairs the NYC Council Task Force to Combat Antisemitism launched in January 2026. He co-sponsored Introduction 0722, requiring the mayor to designate an agency to support religious institutions in establishing emergency plans, and sponsored a bill requiring NYPD to report on hate crime case outcomes on its crime dashboard.', 'https://council.nyc.gov/press/2026/01/29/3067/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (224, 16, 'Dinowitz issued a public statement standing with over 50 CUNY professors who resigned from the PSC-CUNY union after it passed a June 2021 resolution condemning Israel as an "apartheid" state and supporting BDS. Dinowitz called the resolution "anti-Semitic" and said the union "sided with a terrorist organization over the region''s only democracy."', 'https://council.nyc.gov/eric-dinowitz/council-member-dinowitz-stands-with-former-psc-cuny-members-who-resigned-from-their-union-over-anti-semitic-resolution/', '2021-06-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (224, 12, 'Dinowitz, who had visited Kibbutz Kfar Aza near Gaza during a December 2022 JCRC study tour, spoke about the October 7 attack on the kibbutz: "What Hamas did was unspeakable hatred." He reported contacting the local woman who had guided the tour and confirming she was safe, but noted others in the area had been "burned," "butchered" and "murdered."', 'https://www.bxtimes.com/bronx-kibbutz-tour-israel-war/', '2023-10-17');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (225, 14, 'Riley participated in a weeklong JCRC-sponsored study tour of Israel in late November 2022, alongside Bronx council members Eric Dinowitz, Marjorie Velazquez, and Althea Stevens. The tour included visits to Jerusalem, Tel Aviv-Jaffa, Haifa, the West Bank, and the Israel-Gaza border. JCRC covered the full cost of approximately $5,000-$7,500 per person.', 'https://www.bxtimes.com/councilmembers-visit-israel/', '2022-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (227, 11, 'Sanchez signed on to a Local Progress letter on January 9, 2024 calling for "a durable ceasefire" in Gaza and urging President Biden and Congress to pursue a durable ceasefire, secure the release of all hostages, deliver humanitarian aid, and begin creating conditions for a political agreement.', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-01-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (229, 14, 'Stevens participated in a JCRC-organized study tour of Israel in November 2022 with 12 NYC Council members, visiting Jerusalem, Tel Aviv-Jaffa, Haifa, the West Bank, and the Israel-Gaza border, meeting with Israeli and Palestinian scholars, NGO leaders, and civil society representatives', 'https://www.bxtimes.com/councilmembers-visit-israel/', '2022-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (229, 11, 'Stevens signed a Local Progress open letter in January 2024 with over 300 local elected officials calling on the Biden-Harris administration and Congress to take immediate action for a "durable ceasefire" in Israel and Palestine', 'https://localprogress.org/2024/01/05/hundreds-of-local-elected-officials-call-for-a-ceasefire/', '2024-01-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (232, 12, 'Paladino appeared on Fox News Live denouncing anti-Israel protests and surging antisemitism, calling pro-Palestinian protesters "small terrorist cells" rather than legitimate protesters, and expressing strong support for Israel following the October 7 Hamas attacks', 'https://www.foxnews.com/video/6340512545112', '2023-11-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (232, 12, 'Paladino stated "We can have a ceasefire the minute Hamas surrenders. It''s pretty simple actually," explicitly conditioning any ceasefire on Hamas''s unconditional surrender and expressing repeated support for Israel following the Oct. 7 attack that killed 1,200 Israelis and took 240 hostages', 'https://qns.com/2023/12/brooklyn-council-member-taunts-vickie-paladino-in-dispute-over-possible-gaza-ceasefire/', '2023-12-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (232, 12, 'Paladino described pro-Palestinian protesters as "the worst people our society has ever produced" and in response to 2024 campus protests against Israel''s bombardment of Gaza, called college students "monsters" who must be "slayed," asserting that progressives "marching through our streets, shutting down our bridges, harassing Jewish businesses, and taking over our universities FULLY support" Hamas', 'https://en.wikipedia.org/wiki/Vickie_Paladino', '2024-05-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (232, 16, 'Paladino joined fellow Republican council members Ariola, Carr, Morano, and Vernikov in filing a FOIL lawsuit against Mayor Mamdani on February 19, 2026 to compel release of records related to his revocation of executive orders that adopted the IHRA antisemitism definition and barred city employees from boycotting Israel', 'https://queenseagle.com/all/2026/2/19/queens-pols-and-civic-leaders-sue-mamdani-over-foil-request-regarding-israel-eos', '2026-02-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (232, 5, 'Paladino supported the NYC Council antisemitism legislation package creating buffer zones around houses of worship and schools during protests, which passed with a veto-proof 44-5 majority on March 26, 2026 as part of Speaker Julie Menin''s five-point plan to combat antisemitism', 'https://www.jta.org/2026/03/26/ny/nyc-council-approves-buffer-zone-legislation-insulating-houses-of-worship-from-protests', '2026-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (233, 14, 'Ung participated in a JCRC-organized study tour of Israel in November 2022 with 12 NYC Council members, later stating she gained "a deeper understanding of the concerns and complexities facing the region that I don''t think I could truly appreciate by just reading the newspaper and other accounts of the region"', 'https://jewishinsider.com/2023/01/jcrc-new-york-city-council-israel-trip/', '2022-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (233, 14, 'Ung attended a pro-Israel solidarity vigil in Kew Gardens Hills on October 9, 2023, organized by Queens Borough President Donovan Richards, where more than 100 people gathered to show support for Israel and mourn lives lost in the Hamas October 7 attack; Council Speaker Adrienne Adams spoke on behalf of attendees including Ung', 'https://qns.com/2023/10/queens-community-support-israel-kew-gardens/', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (233, 5, 'Ung supported the NYC Council antisemitism legislation package creating buffer zones around houses of worship and schools during protests, which passed with a veto-proof 44-5 majority on March 26, 2026 as part of Speaker Julie Menin''s five-point plan to combat antisemitism', 'https://www.jta.org/2026/03/26/ny/nyc-council-approves-buffer-zone-legislation-insulating-houses-of-worship-from-protests', '2026-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (235, 9, 'Caban tweeted "Even as I continue to grieve the Israeli civilians murdered by Hamas, I feel mounting fear that the conditions for genocide in Gaza are developing. The US must do everything in its power to secure an immediate ceasefire and de-escalation" on October 11, 2023, using the word "genocide" to describe conditions in Gaza', 'https://x.com/tiffany_caban/status/1712146243181277252', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (235, 11, 'Caban was the first NYC Council member to call for a ceasefire on October 11, 2023, stating "The US must do everything in its power to secure an immediate ceasefire and de-escalation"', 'https://x.com/tiffany_caban/status/1712146243181277252', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (235, 15, 'Caban participated in a Jewish Voice for Peace protest at Grand Central Station on October 27, 2023 demanding a ceasefire in Gaza, where thousands of pro-Palestinian protesters shut down the main terminal and nearly 400 people were arrested', 'https://www.commondreams.org/news/jewish-led-protests', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (235, 8, 'Caban was arrested on August 1, 2025 at the Manhattan offices of Senators Schumer and Gillibrand during a Jewish Voice for Peace protest demanding an end to U.S. arms shipments to Israel, stating "We''re here to stand in solidarity with Palestinians in Gaza who are being starved to death right now...We''re using U.S.A. dollars to help them do it, and it has to end"', 'https://www.amny.com/news/council-member-tiffany-caban-protesters-arrested-schumer-gillibrands-midtown/', '2025-08-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (235, 15, 'Caban was among 50 people arrested at a pro-Palestinian demonstration that stormed the lobby of Senator Chuck Schumer''s Midtown office on August 1, 2025, protesting senators'' votes against a measure to halt U.S. arms shipments to Israel', 'https://www.newsweek.com/protesters-arrested-chuck-schumer-kirsten-gillibrand-offices-gaza-2107782', '2025-08-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (235, 13, 'Caban equivocated on October 7 by immediately pivoting from acknowledging Israeli civilian deaths to warning about "conditions for genocide in Gaza," framing the Israeli response as the primary concern rather than offering a strong standalone condemnation of the Hamas attack', 'https://x.com/tiffany_caban/status/1712146243181277252', '2023-10-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (236, 5, 'Lee visited the owners of Bagels & Co. in Fresh Meadows after it was targeted by an anti-Semite who threatened to burn down the store for displaying an Israeli flag, stating "No matter your politics, we cannot accept this hatred in District 23 or NYC"', 'https://abc7ny.com/bagel-shop-anti-semitism-queens-nypd/11263346/', '2023-11-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (236, 14, 'Lee joined Council Members Gennaro, Schulman, Ariola, Brooks-Powers, and Ung in collectively presenting the Queens Jewish Community Council with a proclamation at the annual QJCC Gala on October 18, 2023, showing solidarity with Israel following the Hamas attack', 'https://qns.com/2023/10/electeds-solidarity-israel-qjcc-gala-elmhurst/', '2023-10-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (237, 12, 'Gennaro delivered remarks at a vigil at the Kew Gardens Library in Queens honoring lives lost in the Hamas attack, stating his "unwavering support of Israel" and that "We unwaveringly support Israel in its righteous imperative to do all that is necessary to defend itself and swiftly win this war"', 'https://qns.com/2023/10/queens-community-support-israel-kew-gardens/', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (237, 14, 'Gennaro attended the 54th Queens Jewish Community Council Gala on October 18, 2023, where he and fellow council members presented QJCC with a proclamation showing solidarity with Israel following the October 7 attack', 'https://qns.com/2023/10/electeds-solidarity-israel-qjcc-gala-elmhurst/', '2023-10-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (237, 14, 'Gennaro held a meeting with Idit Silman, Israel''s Minister of Environmental Protection, in July 2023 to discuss environmental solutions and climate change strategies between New York and Israel', 'https://www.queensjewishlink.com/index.php/local/79-community-corner/shabsie-saphirstein/9000-gennaro-discusses-environmental-solutions-with-israel-s-minister-of-environmental-protection', '2023-07-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (237, 16, 'Gennaro publicly rebutted Pope Leo XIV''s call for a two-state solution, arguing that "the record shows clearly that the Palestinians have never pursued a two-state solution and have consistently rejected two-state solutions" and pointing to Israeli-Muslim coexistence within Israel as the model', 'https://www.israelnationalnews.com/news/418966', '2025-11-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (237, 16, 'Gennaro responded to Pope Leo XIV''s suggestion that Christian leaders responsible for wars should go to confession by telling the Pope "with all due respect, maybe YOU should go to Confession," defending Israel''s position as "an observant Catholic" who represents "many Catholic parishes and Catholic institutions in Queens"', 'https://www.israelnationalnews.com/news/424476', '2026-03-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (237, 5, 'Gennaro was present outside the Yeshiva of Central Queens during a January 2026 pro-Hamas protest where demonstrators chanted "We are Hamas and we are here," which Gennaro characterized as "a direct threat," and was credited for his quick outreach to NYPD and the Jewish community regarding the incident', 'https://www.qchron.com/editions/north/synagogue-protest-roundly-condemned/article_1c743d71-7b14-490e-930e-74e0270573fa.html', '2026-01-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (238, 12, 'Krishnan tweeted on October 8, 2023: "Every human life is precious. The horrific, indiscriminate violence against Israeli civilians, including children, infants, and the elderly, is sickening and must be confronted. I unequivocally condemn Hamas. I grieve the loss of life."', 'https://x.com/voteshekar/status/1711849305781236111', '2023-10-08');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (238, 11, 'Krishnan wrote an op-ed in the Jackson Heights Post in April 2024 calling for "an immediate, permanent ceasefire and a release of all hostages," citing Israel''s killing of seven World Central Kitchen aid workers, stating "If we truly believe every human life is precious, which I do, this is the only way forward"', 'https://jacksonheightspost.com/op-ed-a-global-tragedy-hits-home', '2024-04-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (238, 5, 'Krishnan stated "Antisemitism and hate have no place in New York City, especially in our schools" and expressed deep concern about two antisemitic incidents at a school in Jackson Heights, saying he was working closely with the school and NYPD to investigate', 'https://x.com/CMShekarK/status/2019082314165207157', '2026-02-04');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (238, 14, 'Krishnan attended a model Passover seder organized by JCRC-NY alongside Holocaust survivors and NYC Council members in April 2024, an event designed to show solidarity and expose council members of different faiths to Holocaust survivors', 'https://www.jta.org/2024/04/16/ny/at-a-model-passover-seder-holocaust-survivors-and-nyc-council-members-celebrate-unity', '2024-04-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (239, 8, 'Won, as a 2021 City Council candidate from Long Island City, took to social media to protest Israel''s treatment of Palestinians and criticize Congress for sending billions of dollars in unconditional military aid to Israel during the May 2021 escalation', 'https://patch.com/new-york/astoria-long-island-city/queens-reps-show-support-gaza-criticize-u-s-aid-israel', '2021-05-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (239, 11, 'Won signed on to a Local Progress open letter on January 9, 2024 calling for "a durable ceasefire" in Israel and Palestine, joining more than 300 local elected officials across the country in the letter to the Biden-Harris administration and Congress', 'https://localprogress.org/2024/01/05/hundreds-of-local-elected-officials-call-for-a-ceasefire/', '2024-01-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (239, 11, 'Won stated she "believes there needs to be an end to the war in Gaza and that a ceasefire must continue" in the context of her 2026 congressional campaign for NY-7', 'https://www.nbcnewyork.com/news/politics/queens-city-councilmember-julie-won-enters-race-ny-7th-district/6453855/', '2026-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (240, 14, 'Williams participated in a JCRC-organized study tour of Israel in late November 2022 with 12 NYC Council members; the trip was fully paid for by the Jewish Community Relations Council of New York at a cost of approximately $5,000 to $7,500 per person', 'https://www.cityandstateny.com/politics/2023/06/some-nyc-council-members-didnt-disclose-their-free-tour-israel/387391/', '2022-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (240, 11, 'Williams wore a "Ceasefire Now" button on December 6, 2023 and signed on to a Local Progress letter on January 9, 2024 calling for "a durable ceasefire" in Israel and Palestine', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-12-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (242, 12, 'Schulman attended a vigil in Kew Gardens Hills in support of Israel organized by the Queens Jewish Community Council and JCRC following the October 7 attacks, stating "So many of my neighbors are hurting from the pain and loss of that day" and "Praying for the return of all hostages and stability in the region." She later said "As a Jew, Oct. 7, 2023, was heart breaking and mind numbing"', 'https://www.qchron.com/editions/queenswide/queens-shows-it-stands-with-israel/article_41257666-66e3-11ee-a71a-a3b00395347c.html', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (242, 14, 'Schulman, along with Council Members Lee, Ariola, Brooks-Powers, Ung, and Gennaro, collectively presented QJCC with a proclamation expressing solidarity with Israel at the annual QJCC Gala on October 18, 2023, where all speakers expressed their support for Israel defending itself', 'https://qns.com/2023/10/electeds-solidarity-israel-qjcc-gala-elmhurst/', '2023-10-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (242, 5, 'Schulman, as vice chair of the Jewish Caucus and member of the Combat Hate Committee, contributed bills to Speaker Menin''s five-point plan to combat antisemitism. She also criticized the DOH "Global Oppression Working Group" as fanning antisemitism, saying she was "deeply troubled" by the group''s focus on "foreign political issues" while "New Yorkers face serious and urgent public health challenges at home"', 'https://www.yahoo.com/news/articles/mamdani-health-department-global-oppression-170648646.html', '2026-03-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (244, 14, 'Brooks-Powers participated in a JCRC-organized study tour of Israel in November 2022 with approximately 12 NYC Council members. She disclosed the trip cost in the range of $1,000 to $5,000, though JCRC said the actual cost per person was $5,000 to $7,500', 'https://www.cityandstateny.com/politics/2023/06/some-nyc-council-members-didnt-disclose-their-free-tour-israel/387391/', '2022-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (244, 14, 'Brooks-Powers attended the QJCC Gala on October 18, 2023, and collectively presented QJCC with a proclamation expressing solidarity with Israel alongside Council Members Schulman, Lee, Ariola, Ung, and Gennaro', 'https://qns.com/2023/10/electeds-solidarity-israel-qjcc-gala-elmhurst/', '2023-10-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (244, 12, 'Brooks-Powers attended a vigil in support of Israel at the Kew Gardens Hills library following the October 7 attacks, where City Council Speaker Adrienne Adams spoke on behalf of several Council members in attendance including Brooks-Powers', 'https://qns.com/2023/10/queens-community-support-israel-kew-gardens/', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (245, 12, 'Ariola released a joint statement with the Common-Sense Caucus on October 10, 2023, condemning the DSA for promoting a pro-Hamas rally in Times Square, stating "There is no ''both sides'' argument. There is no moral relativism. This is pure evil. The atrocities being committed by Hamas must be condemned." She also prayed for Israel at the Howard Beach Judea Center with Rabbi Richter', 'http://theforumnewsgroup.com/2023/10/13/pols-rally-around-israel/', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (245, 14, 'Ariola attended the QJCC Gala on October 18, 2023, and collectively presented QJCC with a proclamation expressing solidarity with Israel alongside other Council members. She also prayed for Israel at the Howard Beach Judea Center, stating "Their strength and words of faith were inspiring" and expressing "our unwavering support of Israel"', 'https://qns.com/2023/10/electeds-solidarity-israel-qjcc-gala-elmhurst/', '2023-10-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (245, 5, 'Ariola co-sponsored Introduction 0751 with Council Member Dinowitz requiring police to submit a plan to establish security perimeters at educational facilities, as part of the Council''s five-point antisemitism action plan. She stated that "during the waves of protests we saw in recent years, we heard from many, many New Yorkers that they were afraid for their safety while trying to simply get an education"', 'https://council.nyc.gov/press/2026/01/29/3067/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (245, 16, 'Ariola, as Council Minority Leader, along with Council Members Carr, Morano, Vernikov, and Paladino, filed a FOIL lawsuit against Mayor Mamdani to compel release of records related to his revocation of executive orders that adopted the IHRA antisemitism definition and barred city employees from boycotting Israel, accusing the administration of having "stonewalled, deflected, delayed, and denied" their request', 'https://queenseagle.com/all/2026/2/19/queens-pols-and-civic-leaders-sue-mamdani-over-foil-request-regarding-israel-eos', '2026-02-19');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (245, 5, 'Ariola rallied with Queens lawmakers and Jewish community leaders outside Department of Education offices in Ozone Park in November 2023, demanding accountability for an antisemitic rampage at Hillcrest High School in Jamaica and calling for people to "wake up" to continuing problems', 'https://qns.com/2023/11/queens-officials-jewish-leaders-rally-hillcrest-high-school-jamaica/', '2023-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (246, 12, 'Restler co-signed an open letter from Jewish elected officials in February 2024 that called the October 7 Hamas attacks "monstrous and indefensible" and demanded Hamas release all remaining hostages immediately. He also attended Brooklyn Heights Synagogue after the attacks, posting "Comfort and solace in being in community as neighbors still try to figure out if family members and friends are okay"', 'https://www.nysenate.gov/newsroom/articles/2024/liz-krueger/open-letter-jewish-elected-officials-regarding-war-gaza', '2024-02-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (246, 11, 'Restler co-signed an open letter from Jewish elected officials stating "the Israeli government cannot continue the mass destruction of Gaza and the killing of civilians who are trapped in a war zone with no possibility to flee to safety" and "we cannot support the actions of the current Israeli government," effectively calling for a ceasefire. He was listed on the City & State NY ceasefire tracker', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-02-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (246, 8, 'Restler co-signed an open letter from Jewish elected officials that stated "we make no excuses for terrorists or their defenders, but we cannot support the actions of the current Israeli government," calling for conditions on continued U.S. support for Israeli military operations in Gaza', 'https://www.brooklynpaper.com/jewish-values-pols-letter-gaza-israel-war/', '2024-02-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (246, 5, 'Restler sponsored Introduction 388/796 to establish a hotline and detailed reporting system for antisemitism and other hate- and bias-related incidents in NYC, as part of the broader Council response to rising antisemitic incidents which accounted for 57% of reported hate crimes in 2025', 'https://council.nyc.gov/press/2026/01/29/3067/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (246, 14, 'Restler condemned the May 2025 murder of two Israeli Embassy staffers Yaron Lischinsky and Sarah Lynn Milgram in Washington DC, tweeting "The murder of two Israeli Embassy staffers... is terrifying. This tragic attack only serves to sow fear across the Jewish community"', 'https://x.com/LincolnRestler/status/1925529386255614407', '2025-05-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (247, 11, 'Gutierrez called for an immediate ceasefire on November 21, 2023, stating "This war must come to an immediate end to save lives, we must condemn Hamas and promote enduring peace in the region" and "Above all else, we must prioritize preserving all civilian lives and ensuring a safe return of the hostages"', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-11-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (247, 11, 'Gutierrez wore a "Ceasefire Now" shirt at a NYC Council stated meeting on December 6, 2023, alongside eight other council members, and posted on social media: "Proud to stand in solidarity with some of my @nyccouncil colleagues today at the Stated Meeting calling for an immediate and permanent #ceasefire"', 'https://worldisraelnews.com/anti-israel-nyc-council-members-ripped-for-ceasefire-now-shirts/', '2023-12-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (248, 11, 'Hudson called for a permanent ceasefire in Gaza and the release of hostages, as confirmed by a Crown Heights community op-ed that acknowledged her ceasefire stance while noting she had also called for hostages to be released. She was listed on the City & State NY elected officials ceasefire tracker', 'https://crownheights.info/op-ed/864599/op-ed-crown-heights-city-council-members-betrayal-has-not-gone-unnoticed/', '2024-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (248, 5, 'Hudson issued a joint statement with State Senator Zellnor Myrie and Assembly Member Brian Cunningham condemning a planned antisemitic gathering in Crown Heights organized by "Crown Heights Bites Back," stating "Any individual or organization that aims to stoke the flames of division and rewrite history in a blatantly antisemitic fashion has no place in our community"', 'https://collive.com/officials-denounce-planned-antisemitic-event-in-crown-heights/', '2025-08-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (249, 13, 'Osse released a statement on October 9, 2023 — two days after the Hamas attack — declaring that Israel''s "occupation" was the "primary root of the violence," drawing criticism from Jewish constituents in Crown Heights who said he blamed Israel for the terror attack.', 'https://crownheights.info/communal-matters/838452/shocking-statements-by-crown-heights-representative-blames-israel-for-terror-attack/', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (249, 9, 'Osse tweeted: "Israel is a terror state. Shame on every single person who is continuing to defend the ongoing genocide of the Palestinian people. You will be remembered poorly in history. Continued prayers for the people of Gaza."', 'https://x.com/OsseChi/status/1925244023624585387', '2025-05-21');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (249, 11, 'Osse participated in the Jewish Voice for Peace-led protest at Grand Central Station on October 27, 2023, alongside other NYC Council members and state legislators, demanding an immediate ceasefire in Gaza. Over 350 people were arrested at the action.', 'https://www.jewishvoiceforpeace.org/2023/10/30/shut-it-down-grand-central-coverage/', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (249, 11, 'Osse was among 17 NYC City Council members who publicly called for a ceasefire in Gaza and joined a 24-hour vigil at City Hall on February 28, 2024 demanding the Council pass a ceasefire resolution.', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-02-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (249, 15, 'Osse attended the JVP-organized Grand Central Station protest on October 27, 2023, where thousands filled the terminal with chants of "ceasefire now" and "let Gaza live" until the station was fully shut down.', 'https://www.democracynow.org/2023/10/30/grand_central_protest', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (249, 15, 'Osse tweeted: "Students protesting at @Columbia for Palestinian life have my full support. I unequivocally condemn the vile antisemitic incidents from OUTSIDE perpetrators we''ve seen in the area. I reject attempts to use those incidents to smear the broader student movement. Free Palestine."', 'https://x.com/OsseChi/status/1782418295313895894', '2024-04-22');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (249, 8, 'Osse filed paperwork to run in the 2026 Democratic primary against pro-Israel US House Minority Leader Hakeem Jeffries, positioning himself as a vocal critic of US military support for Israel and calling Israel a "terror state."', 'https://x.com/DropSiteNews/status/1990500744047301062', '2025-11-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (250, 11, 'Nurse, co-chair of the Council Progressive Caucus, called for a ceasefire on October 12, 2023, criticizing Gov. Hochul: "Right now our state needs disciplined leadership that can both condemn Hamas and call for de-escalation and ceasefire. As we get reports of white phosphorus used on Gaza and carrying out a complete leveling of the strip as collective punishment, I''m disappointed to read this."', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (250, 15, 'Nurse joined Council Members Tiffany Caban, Alexa Aviles, and Chi Osse at the JVP-organized Grand Central Station protest on October 27, 2023, where thousands demanded an immediate ceasefire in Gaza.', 'https://www.democracynow.org/2023/10/30/grand_central_protest', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (250, 15, 'Nurse visited the Gaza Solidarity Encampment at Columbia University on April 20, 2024, alongside Council Members Hanif, Aviles, and Caban, co-authoring an op-ed supporting students'' calls for ceasefire and divestment from Israel.', 'https://www.cityandstateny.com/opinion/2024/04/opinion-we-visited-solidarity-encampment-columbia-university-heres-what-its-really/395989/', '2024-04-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (251, 15, 'Aviles was photographed at an anti-Israel protest holding a sign reading "NAKBA 74 RESISTANCE AND RETURN BY ANY MEANS NECESSARY" during Israel''s war against Hamas in April 2024.', 'https://canarymission.org/individual/Alexa_Aviles', '2024-04-18');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (251, 15, 'Aviles joined Council Members Osse, Nurse, and Caban at the JVP-organized Grand Central Station protest on October 27, 2023, demanding an immediate ceasefire in Gaza.', 'https://www.democracynow.org/2023/10/30/grand_central_protest', '2023-10-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (251, 15, 'Aviles visited the Gaza Solidarity Encampment at Columbia University on April 20, 2024, alongside Council Members Hanif, Nurse, and Caban, co-authoring an op-ed supporting students'' calls for ceasefire and divestment from Israel.', 'https://www.cityandstateny.com/opinion/2024/04/opinion-we-visited-solidarity-encampment-columbia-university-heres-what-its-really/395989/', '2024-04-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (251, 11, 'Aviles was among 17 NYC City Council members who publicly called for a ceasefire in Gaza and joined a 24-hour vigil at City Hall on February 28, 2024 demanding the Council pass a ceasefire resolution.', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-02-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (251, 8, 'Aviles wrote an op-ed in City & State NY titled "From Puerto Rico to Palestine, now is the time to grow our movement," stating: "No matter how often our residents voice dissent to additional military funding for Israel, many of their representatives still vote to aid violence."', 'https://www.cityandstateny.com/opinion/2025/12/opinion-puerto-rico-palestine-now-time-grow-our-movement/409828/', '2025-12-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (251, 10, 'Aviles is a supporter of the Boycott, Divestment, Sanctions (BDS) movement targeting Israel and a member of DSA, which posted on October 9, 2023: "Today''s events are a direct result of Israel''s apartheid regime."', 'https://canarymission.org/individual/Alexa_Aviles', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (251, 13, 'Aviles, as a DSA member, was associated with the group''s October 9, 2023 statement calling the Hamas attack "a direct result of Israel''s apartheid regime." She also co-signed a letter condemning Columbia for suspending SJP and JVP, groups that had expressed support for October 7 attacks.', 'https://canarymission.org/individual/Alexa_Aviles', '2023-11-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 13, 'Hanif''s initial response after October 7, 2023 focused on context rather than condemnation, writing that "the root cause of this war is the illegal, immoral and unjust occupation of the Palestinian people." Her condemnation of Hamas came belatedly in April 2024, drawing criticism from Brad Lander who said he was "deeply disappointed" by her failure to immediately condemn Hamas.', 'https://jewishinsider.com/2024/08/shahana-hanif-new-york-city-brooklyn-maya-kornberg-primary/', '2023-10-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 9, 'Hanif stated that "the conditions for genocide in Gaza are developing" and tweeted demanding "an end to the apartheid and genocide" following her arrest at a Gaza ceasefire protest on October 20, 2023.', 'https://x.com/ShahanaFromBK/status/1716465788389916884', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 10, 'Hanif tweeted demanding "an end to the apartheid and genocide" in reference to Israel''s treatment of Palestinians, following her arrest at a ceasefire protest in October 2023.', 'https://x.com/ShahanaFromBK/status/1716465788389916884', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 11, 'Hanif was arrested on October 20, 2023 alongside State Senator Jabari Brisport at a rally outside Senator Gillibrand''s office organized by Within Our Lifetime and DSA, demanding an immediate ceasefire in Gaza. About 130 protesters were arrested.', 'https://x.com/ShahanaFromBK/status/1716465788389916884', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 15, 'Hanif was arrested alongside Brooklyn State Senator Jabari Brisport at a rally in Manhattan organized by Within Our Lifetime and DSA on October 20, 2023, where she called for an immediate ceasefire in Gaza.', 'https://www.amny.com/news/hundreds-of-pro-palestinian-protestors-rally-outside-u-s-sen-gillibrands-office-scores-arrested/', '2023-10-20');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 15, 'Hanif visited the Gaza Solidarity Encampment at Columbia University on April 20, 2024, co-authoring an op-ed with Aviles, Nurse, and Caban supporting students'' calls for ceasefire and divestment from Israel, stating the encampment was "completely peaceful."', 'https://council.nyc.gov/shahana-hanif/2024/04/30/we-visited-the-solidarity-encampment-at-columbia-university-heres-what-its-really-like/', '2024-04-30');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 8, 'Hanif stated "our money is funding this genocide" and called for "the prevention of any more US dollars going to bomb Palestinian children." She endorsed the Leave It Blank campaign during the 2024 presidential primary to protest Biden''s military support for Israel.', 'https://jewishinsider.com/2024/12/new-york-city-primary-shahana-hanif-maya-kornberg/', '2024-03-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 11, 'Hanif was a leading voice pushing the NYC Council to vote on a ceasefire resolution, joining the 24-hour vigil at City Hall in February 2024 and consistently calling for a permanent ceasefire throughout 2023-2024.', 'https://www.cityandstateny.com/politics/2024/03/new-york-elected-officials-calling-ceasefire-gaza/394535/', '2024-02-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (252, 12, 'Hanif on the one-year anniversary of October 7 stated: "Today marks one year since the horrific attacks by Hamas" and that she mourns "the loss of over 1,200 Israelis," "categorically condemn[s] Hamas'' atrocities and urge[s] the safe return of all hostages." However, this condemnation came over a year after the attacks; her initial condemnation of Hamas was in April 2024.', 'https://council.nyc.gov/shahana-hanif/2024/10/07/council-member-shahana-hanifs-statement-on-one-year-since-the-october-7th-attacks/', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (254, 14, 'Mealy participated in a free all-expenses-paid trip to Israel in February 2015 sponsored by the Jewish Community Relations Council of New York and United Jewish Appeal, part of the NYC Council delegation. Over 40 community organizations protested the trip.', 'https://imemc.org/article/70281/', '2015-02-01');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (256, 5, 'Zhuang condemned antisemitism at CUNY during her 2023 council campaign, stating "As an Asian-American, I understand discrimination and the horrific and chilling impact it has on our communities. That''s why it''s so important for me to call out and strongly condemn antisemitism whenever I see it. We must have zero tolerance for hatred coming from radical elements at CUNY"', 'https://jewishinsider.com/2023/06/charles-barron-susan-zhuang-chris-banks-wai-yee-chan-new-york-city-council/', '2023-06-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (257, 1, 'Felder co-sponsored anti-BDS bill S6378A in the New York State Senate with Senator Jack Martins, which expanded existing state law to prevent New York from entering into state contracts with those seeking to economically harm Israel. Felder stated "Those who advocate and engage in boycotts against Israel, and who promote anti-Semitic ideology, have no place as a state contractor"', 'https://www.nysenate.gov/newsroom/press-releases/2016/martin-j-golden/senate-passes-bill-supporting-israel-and-other-us', '2016-01-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (257, 12, 'Felder released a statement marking one year since October 7, calling the attacks "unimaginable atrocities perpetrated against innocent children, women and men of all ages" on the Jewish holiday of Simchas Torah, and described Israel as "engaged in a battle of biblical proportions, not only for its existence, but for an end to global terrorism"', 'https://www.nysenate.gov/newsroom/articles/2024/simcha-felder/senator-felders-statement-marking-one-year-october-7-2023', '2024-10-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (257, 5, 'Felder pushed for immediate release of $45 million in Non-Public School Safety Equipment funding after October 7, working with Senate Majority Leader Stewart-Cousins to address Jewish schools'' urgent need to quickly bolster security amid alarming rise in antisemitism', 'https://www.nysenate.gov/newsroom/press-releases/2023/simcha-felder/felder-fights-protect-yeshivas-amid-alarming-rise-anti', '2023-11-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (257, 5, 'Felder partnered with NYPD Counterterrorism Bureau to hold active shooter drill training for yeshiva school administrators representing tens of thousands of students, as part of ongoing efforts to protect Jewish institutions', 'https://www.nysenate.gov/newsroom/press-releases/2019/simcha-felder/senator-felder-and-nypd-counterterrorism-hold-active', '2019-09-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (257, 14, 'Felder blasted Governor Hochul for endorsing mayoral candidate Zohran Mamdani, calling him "an outspoken and unapologetic antisemite" whose policies endanger Jews including backing BDS, Globalize the Intifada, and defunding the NYPD, then criticized Hochul for visiting Midwood to announce yeshiva security funding after swastikas appeared in the neighborhood', 'https://vinnews.com/2025/11/06/councilman-felder-slams-hochuls-antisemitic-chutzpah-as-outrageous-hypocrisy/', '2025-11-06');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (258, 5, 'Louis denounced an antisemitic attack on a Jewish man assaulted on his way to shul in her district, stating "anti-Semitic acts are absolutely unacceptable and will not be tolerated in District 45 or New York City" and calling it "an attack on the very foundation of who we are as a community"', 'https://council.nyc.gov/farah-louis/2021/07/16/louis-denounces-anti-semitic-attack/', '2021-07-16');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (258, 5, 'Louis issued a statement condemning the increase in anti-Semitic hate crimes across New York City, declaring "I condemn all forms of bigotry and hate"', 'https://council.nyc.gov/farah-louis/2021/05/25/louis-statement-on-jewish-hate-crimes/', '2021-05-25');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (258, 14, 'Louis attended the Brooklyn College counter-rally on October 12, 2023 alongside Council Members Inna Vernikov and Kalman Yeger in solidarity with Jewish students during a pro-Palestinian demonstration, issuing a joint statement about helping students who felt unsafe', 'https://x.com/InnaVernikov/status/1712565826706931955', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (259, 5, 'Narcisse is a member of the NYC Council''s Task Force to Combat Antisemitism launched in January 2026 to address hate crimes disproportionately targeting Jews, alongside co-chairs Vernikov and Dinowitz', 'https://www.timesofisrael.com/nyc-council-launches-antisemitism-task-force-new-bill-would-limit-synagogue-protests/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (259, 5, 'Narcisse sponsored Introduction 726 to expand the existing security guard reimbursement program for nonpublic schools, and Introduction 327 to reimburse nonpublic schools for video surveillance cameras, as part of the Council''s five-point plan to combat antisemitism', 'https://council.nyc.gov/press/2026/01/29/3067/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 1, 'Vernikov pulled $50,000 in council funding from CUNY Law School after its faculty endorsed a pro-BDS resolution, redirecting funds to Legal Services NYC. She stated "During a time when antisemitic hate crimes are up by 300 percent, it is incumbent upon our academic institutions to do everything in their power to protect their Jewish and pro-Israel students"', 'https://jewishjournal.com/news/united-states/348979/nyc-city-councilwoman-revokes-50000-in-funding-for-cuny-law-following-bds-endorsement/', '2022-05-27');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 12, 'Vernikov attended the Brooklyn College pro-Palestinian rally on October 12, 2023, declaring protesters "nothing short of a terrorist without the bombs" while confronting demonstrators chanting "Globalize the Intifada" and "From the River to the Sea" days after the October 7 massacre', 'https://www.thecity.nyc/2023/10/13/inna-vernikov-gun-arrest-brookl-college-palestinian-israel-protest/', '2023-10-12');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 14, 'Vernikov marched in the Celebrate Israel Parade on Fifth Avenue in June 2024, describing bipartisan backing for the Jewish state and increased security. She walked alongside fellow Council Member Gale Brewer and other officials including Governor Hochul', 'https://www.jpost.com/diaspora/article-804807', '2024-06-02');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 14, 'Vernikov wore a custom Israeli flag dress designed by Project Runway winner Irina Shabayeva to the New York Young Republican Club gala on the third night of Chanukah 2023, stating Jewish New Yorkers and college students "are afraid to display their Jewish identity, wear a Kipa, a Star of David, or say that they support Israel"', 'https://x.com/InnaVernikov/status/1733678493215453664', '2023-12-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 12, 'Vernikov quit the NYC Council Women''s Caucus in February 2025 because it refused to condemn Hamas terrorists after October 7, stating she could not "stay part of a body that purports to stand up for women, but refuses to condemn the RAPE, MURDER, and CAPTIVITY of Jewish women by jihadi terrorists"', 'https://x.com/InnaVernikov/status/1888569487097844125', '2025-02-09');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 5, 'Vernikov was elected co-chair of the NYC Council''s bipartisan Task Force to Combat Antisemitism in January 2026, alongside Democrat Eric Dinowitz, to examine antisemitic hate crimes in protests, schools, higher education, and city agencies', 'https://www.cityandstateny.com/politics/2026/01/nyc-council-announces-antisemitism-task-force-raising-eyebrows-vernikov-leadership/411075/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 14, 'Vernikov invited Israeli PM Netanyahu to visit New York City on January 1, 2026 — inauguration day for Mayor Mamdani who had pledged to arrest Netanyahu — and Netanyahu responded that he planned to visit the city at a later time', 'https://www.foxnews.com/politics/nyc-lawmaker-dares-mamdani-make-good-pipe-dream-pledge-inviting-netanyahu', '2025-11-11');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 14, 'Vernikov praised the US and Israel for eliminating Iran''s supreme leader, tweeting "The world is safer today because US & Israel eliminated a top sponsor of GLOBAL TERRORISM" and noting Iran bankrolled Hamas, Islamic Jihad, Hezbollah, and Houthi rebels', 'https://x.com/InnaVernikov/status/2027908930014216234', '2026-03-15');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (261, 5, 'Vernikov led a push for a NYC Council hearing to investigate antisemitism at CUNY, probing claims of systemic anti-Jewish bias across the university system', 'https://www.jpost.com/bds-threat/article-708704', '2022-06-07');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (262, 14, 'Hanks traveled to Israel on a JCRC-organized study tour in November 2022 with eight other council colleagues. She reflected that the trip "was about the strength and importance of identity" and "underscored the depth and the insidiousness of antisemitism," noting she represents "many Jewish constituents on Staten Island"', 'https://jewishinsider.com/2023/01/jcrc-new-york-city-council-israel-trip/', '2022-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (262, 14, 'Hanks returned to Israel in February 2024 on a solidarity trip with other NY officials, visiting Kibbutz Kfar Aza devastated on October 7. She stated "I come from a rough neighborhood in Staten Island so I know a little about living in fear, but nothing like this" and "When I heard this kibbutz was attacked, I was determined to come back. You have to bear witness"', 'https://unitedwithisrael.org/new-york-officials-witness-gaza-border-devastation/', '2024-02-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (262, 5, 'Hanks is a member of the NYC Council''s Task Force to Combat Antisemitism launched in January 2026 alongside co-chairs Vernikov and Dinowitz, examining antisemitic hate crimes and bias in schools, protests, and city agencies', 'https://www.timesofisrael.com/nyc-council-launches-antisemitism-task-force-new-bill-would-limit-synagogue-protests/', '2026-01-29');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (263, 12, 'Carr stated that public officials should make clear where they stand and "everyone should be standing with Israel right now" in response to the October 7 Hamas attacks, adding that those who haven''t denounced the attacks should be ashamed', 'https://ny1.com/nyc/all-boroughs/politics/2023/10/10/new-york-officials-respond-to-terror-attacks-in-israel', '2023-10-10');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (263, 14, 'Carr participated in a JCRC-organized study tour of Israel in November 2022 with 12 NYC Council members, stating his biggest takeaway was that he "came to understand better the need that is felt amongst the Jewish community in Israel for a Jewish state" and highlighting Haifa as a model of Jewish-Arab coexistence', 'https://jewishinsider.com/2023/01/jcrc-new-york-city-council-israel-trip/', '2022-11-28');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (263, 5, 'Carr as Council Minority Leader denounced colleagues for hosting a policy briefing that "included radical terrorist sympathizers Mahmoud Khalil and Badar Khan Suri," stating the right to free speech "does not require an elective body to platform vile, antisemitic, anti-American bigots," hours before the council voted on antisemitism legislation', 'https://www.jta.org/2026/03/27/ny/nyc-council-members-host-mahmoud-khalil-at-islamophobia-briefing-sparking-backlash-from-colleagues', '2026-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (263, 5, 'Carr supported the NYC Council antisemitism legislation package creating buffer zones around houses of worship and schools during protests, which passed with a veto-proof 44-5 majority as part of Speaker Julie Menin''s five-point plan to combat antisemitism', 'https://www.jpost.com/diaspora/antisemitism/article-891388', '2026-03-26');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (263, 16, 'Carr joined fellow Republican council members Ariola, Morano, Vernikov, and Paladino in filing a FOIL lawsuit against Mayor Mamdani to compel release of records related to his revocation of executive orders that adopted the IHRA antisemitism definition and barred city employees from boycotting Israel', 'https://www.jns.org/city-council-members-citizens-to-sue-nyc-to-force-records-release-on-axed-policies-defending-jews/', '2026-02-22');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (264, 16, 'Morano joined fellow Republican council members Ariola, Carr, Vernikov, and Paladino in filing a FOIL lawsuit against Mayor Mamdani to compel release of records about his revocation of executive orders that adopted the IHRA antisemitism definition and barred city employees from boycotting or divesting from Israel', 'https://www.jns.org/city-council-members-citizens-to-sue-nyc-to-force-records-release-on-axed-policies-defending-jews/', '2026-02-22');
INSERT INTO person_criteria (person_id, criterion_id, evidence, source_url, source_date)
VALUES (264, 5, 'Morano as part of the Republican minority conference denounced colleagues for hosting a policy briefing featuring Mahmoud Khalil and other anti-Israel activists, calling them "radical terrorist sympathizers" who were "in no small part responsible" for the antisemitism the council''s new legislation sought to combat', 'https://www.jta.org/2026/03/27/ny/nyc-council-members-host-mahmoud-khalil-at-islamophobia-briefing-sparking-backlash-from-colleagues', '2026-03-26');
COMMIT;
